/* Org chart explorer. Re-theme with --ahr-orgchart-paper, -ink and -accent; department hues live in the data. */
@property --ahr-orgchart-n { syntax: "<integer>"; inherits: false; initial-value: 0; }

.ahr-orgchart {
  --ahr-orgchart-paper: oklch(0.975 0.008 128);
  --ahr-orgchart-ink: oklch(0.25 0.03 160);
  --ahr-orgchart-accent: oklch(0.5 0.11 162);
  --ahr-orgchart-card: oklch(0.995 0.003 128);

  --ahr-orgchart-muted: color-mix(in oklch, var(--ahr-orgchart-ink) 62%, var(--ahr-orgchart-paper));
  --ahr-orgchart-faint: color-mix(in oklch, var(--ahr-orgchart-ink) 40%, var(--ahr-orgchart-paper));
  --ahr-orgchart-rule: color-mix(in oklch, var(--ahr-orgchart-ink) 11%, transparent);
  --ahr-orgchart-rule2: color-mix(in oklch, var(--ahr-orgchart-ink) 18%, transparent);
  --ahr-orgchart-wire: color-mix(in oklch, var(--ahr-orgchart-ink) 30%, var(--ahr-orgchart-paper));
  --ahr-orgchart-tint: color-mix(in oklch, var(--ahr-orgchart-accent) 10%, var(--ahr-orgchart-card));
  --ahr-orgchart-hover: color-mix(in oklch, var(--ahr-orgchart-ink) 5%, transparent);
  --ahr-orgchart-hit: oklch(0.86 0.13 95);
  --ahr-orgchart-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-orgchart-spring: linear(0, 0.09 5%, 0.34 11%, 0.74 20%, 0.97 28%, 1.05 35%, 1.06 41%, 1.03 51%, 1.005 64%, 0.998 78%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-orgchart-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-orgchart-paper);
  color: var(--ahr-orgchart-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--ahr-orgchart-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--ahr-orgchart-rule);
}
:where(.ahr-orgchart) *, :where(.ahr-orgchart) *::before, :where(.ahr-orgchart) *::after { box-sizing: border-box; }
:where(.ahr-orgchart) :is(button, input) { font: inherit; color: inherit; }
:where(.ahr-orgchart) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-orgchart) button:disabled { cursor: not-allowed; opacity: .4; }
:where(.ahr-orgchart) :is(p, h2, h3, ul, dl, dd) { margin: 0; padding: 0; }
:where(.ahr-orgchart) ul { list-style: none; }
:where(.ahr-orgchart) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-orgchart) :focus-visible { outline: 2px solid var(--ahr-orgchart-accent); outline-offset: 2px; }
:where(.ahr-orgchart) kbd {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-orgchart-muted);
  background: var(--ahr-orgchart-card); box-shadow: inset 0 0 0 1px var(--ahr-orgchart-rule2), 0 1px 0 var(--ahr-orgchart-rule2);
}

.ahr-orgchart__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "bar bar" "main side";
  grid-template-columns: minmax(0, 1fr) clamp(280px, 27cqi, 320px);
  grid-template-rows: auto auto minmax(0, 1fr);
}

/* ---------- header ---------- */
.ahr-orgchart__head {
  grid-area: head;
  display: flex; align-items: center; gap: 14px;
  padding: 14px 16px 10px;
}
.ahr-orgchart__brand {
  display: flex; align-items: center; gap: 10px; min-width: 0; margin-right: auto;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; color: var(--ahr-orgchart-card); background: var(--ahr-orgchart-accent); stroke-width: 1.9; }
  & b { display: block; font-size: 14px; font-weight: 680; letter-spacing: -0.01em; text-wrap: balance; }
  & span { display: block; font-size: 11px; color: var(--ahr-orgchart-muted); letter-spacing: .04em; text-transform: uppercase; font-weight: 600; }
}
.ahr-orgchart__search {
  position: relative; flex: 0 1 340px; min-width: 0;
  display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 11px; border-radius: 10px;
  background: var(--ahr-orgchart-card); box-shadow: inset 0 0 0 1px var(--ahr-orgchart-rule2);
  transition: box-shadow .2s var(--ahr-orgchart-ease);
  & > svg { color: var(--ahr-orgchart-faint); width: 16px; height: 16px; }
  & input { flex: 1; min-width: 0; height: 100%; border: 0; background: none; outline: none; font-size: 13px; }
  & input::placeholder { color: var(--ahr-orgchart-faint); }
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--ahr-orgchart-accent), 0 0 0 4px color-mix(in oklch, var(--ahr-orgchart-accent) 16%, transparent); }
  &:has(input:not(:placeholder-shown)) kbd { opacity: 0; }
}
.ahr-orgchart__results {
  position: absolute; z-index: 30; top: calc(100% + 6px); left: 0; right: 0;
  padding: 5px; border-radius: 12px; background: var(--ahr-orgchart-card);
  box-shadow: 0 0 0 1px var(--ahr-orgchart-rule2), 0 18px 40px -12px color-mix(in oklch, var(--ahr-orgchart-ink) 35%, transparent);
  transform-origin: 50% 0;
  transition: opacity .18s var(--ahr-orgchart-ease), transform .24s var(--ahr-orgchart-ease);
  @starting-style { opacity: 0; transform: translateY(-4px) scale(.98); }
  & li {
    display: grid; grid-template-columns: 28px 1fr auto; gap: 9px; align-items: center;
    padding: 6px 8px; border-radius: 8px; cursor: pointer;
  }
  & li[aria-selected="true"] { background: var(--ahr-orgchart-tint); }
  & li b { display: block; font-weight: 600; font-size: 12.5px; }
  & li small { display: block; color: var(--ahr-orgchart-muted); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li em { font-style: normal; font-size: 10.5px; color: var(--ahr-orgchart-faint); }
  & mark { background: color-mix(in oklch, var(--ahr-orgchart-hit) 70%, transparent); color: inherit; border-radius: 3px; padding: 0 1px; }
  & .ahr-orgchart__none { display: block; padding: 10px; color: var(--ahr-orgchart-muted); font-size: 12px; cursor: default; }
}
.ahr-orgchart__seg {
  position: relative; display: inline-flex; padding: 3px; border-radius: 10px;
  background: color-mix(in oklch, var(--ahr-orgchart-ink) 6%, transparent);
  & button { position: relative; z-index: 1; height: 30px; padding: 0 13px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--ahr-orgchart-muted); transition: color .2s, background-color .25s var(--ahr-orgchart-ease), box-shadow .25s; }
  & button[aria-selected="true"] { color: var(--ahr-orgchart-ink); background: var(--ahr-orgchart-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--ahr-orgchart-ink) 18%, transparent), 0 0 0 1px var(--ahr-orgchart-rule); }
}

/* ---------- filter bar ---------- */
.ahr-orgchart__bar {
  grid-area: bar;
  display: flex; align-items: center; gap: 12px; min-width: 0;
  padding: 0 16px 10px; border-bottom: 1px solid var(--ahr-orgchart-rule);
}
.ahr-orgchart__depts {
  display: flex; gap: 6px; min-width: 0; overflow-x: auto; scrollbar-width: none;
  & button {
    display: inline-flex; align-items: center; gap: 6px; flex: none; height: 28px; padding: 0 11px 0 9px; border-radius: 99px;
    font-size: 12px; font-weight: 560; color: var(--ahr-orgchart-muted);
    box-shadow: inset 0 0 0 1px var(--ahr-orgchart-rule2);
    transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & button:hover { background: var(--ahr-orgchart-hover); color: var(--ahr-orgchart-ink); }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.62 0.12 var(--h, 160)); }
  & button[aria-pressed="true"] { color: var(--ahr-orgchart-ink); background: color-mix(in oklch, oklch(0.62 0.12 var(--h, 160)) 14%, var(--ahr-orgchart-card)); box-shadow: inset 0 0 0 1.5px oklch(0.62 0.12 var(--h, 160)); }
  & button span { font-variant-numeric: tabular-nums; color: var(--ahr-orgchart-faint); font-size: 11px; }
}
.ahr-orgchart__crumb {
  display: flex; align-items: center; gap: 4px; min-width: 0; font-size: 12px;
  &:empty { display: none; }
  & button { height: 26px; padding: 0 8px; border-radius: 7px; font-weight: 560; color: var(--ahr-orgchart-accent); white-space: nowrap; }
  & button:hover { background: var(--ahr-orgchart-tint); }
  & svg { width: 12px; height: 12px; color: var(--ahr-orgchart-faint); }
  & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-orgchart__stats { margin-left: auto; flex: none; font-size: 12px; color: var(--ahr-orgchart-muted); font-variant-numeric: tabular-nums; white-space: nowrap; & b { color: var(--ahr-orgchart-ink); font-weight: 650; } }

/* ---------- chart ---------- */
.ahr-orgchart__main { grid-area: main; position: relative; min-height: 0; min-width: 0; }
.ahr-orgchart__viewport {
  position: absolute; inset: 0; overflow: auto; overscroll-behavior: contain; cursor: grab;
  scrollbar-width: thin; scrollbar-color: var(--ahr-orgchart-rule2) transparent;
  background: radial-gradient(circle, color-mix(in oklch, var(--ahr-orgchart-ink) 13%, transparent) 1px, transparent 1.5px) 0 0 / 22px 22px;
  background-attachment: local;
  &.is-panning { cursor: grabbing; user-select: none; }
  &.is-fit { animation: ahr-orgchart-frame .7s var(--ahr-orgchart-ease); }
}
.ahr-orgchart[data-mode="outline"] :is(.ahr-orgchart__viewport, .ahr-orgchart__zoom, .ahr-orgchart__keys) { display: none; }
.ahr-orgchart[data-mode="chart"] .ahr-orgchart__outline { display: none; }
.ahr-orgchart__sizer { position: relative; margin: 0 auto; }
.ahr-orgchart__stage { position: absolute; left: 0; top: 0; transform-origin: 0 0; }
.ahr-orgchart__wires {
  position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none;
  & path { fill: none; stroke: var(--ahr-orgchart-wire); stroke-width: 1.6; }
  & path.is-lit { stroke: var(--ahr-orgchart-accent); stroke-width: 2; }
}
.ahr-orgchart__node {
  position: absolute; left: 0; top: 0; width: 196px; height: 66px;
  outline: none; cursor: pointer;
  transition: opacity .3s var(--ahr-orgchart-ease), filter .3s var(--ahr-orgchart-ease);
  &.is-dim { opacity: .34; filter: saturate(.15); }
}
.ahr-orgchart__card {
  position: absolute; inset: 0; display: grid; grid-template-columns: 36px minmax(0, 1fr); align-items: center; gap: 10px;
  padding: 0 12px 0 12px; border-radius: 13px; background: var(--ahr-orgchart-card);
  box-shadow: 0 0 0 1px var(--ahr-orgchart-rule2), 0 1px 2px color-mix(in oklch, var(--ahr-orgchart-ink) 8%, transparent);
  transition: box-shadow .25s var(--ahr-orgchart-ease), translate .25s var(--ahr-orgchart-ease);
  &::before { content: ""; position: absolute; left: 0; top: 14px; bottom: 14px; width: 3px; border-radius: 0 3px 3px 0; background: oklch(0.62 0.12 var(--h)); }
  & b { display: block; font-size: 13px; font-weight: 640; letter-spacing: -0.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.2px; color: var(--ahr-orgchart-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-orgchart__node:hover .ahr-orgchart__card { translate: 0 -1px; box-shadow: 0 0 0 1px var(--ahr-orgchart-wire), 0 8px 18px -10px color-mix(in oklch, var(--ahr-orgchart-ink) 40%, transparent); }
.ahr-orgchart__node[aria-selected="true"] .ahr-orgchart__card {
  box-shadow: 0 0 0 2px var(--ahr-orgchart-accent), 0 0 0 6px color-mix(in oklch, var(--ahr-orgchart-accent) 15%, transparent), 0 12px 24px -14px color-mix(in oklch, var(--ahr-orgchart-ink) 50%, transparent);
}
.ahr-orgchart__node:focus-visible .ahr-orgchart__card { outline: 2px solid var(--ahr-orgchart-accent); outline-offset: 4px; }
.ahr-orgchart__node.is-hit .ahr-orgchart__card { background: color-mix(in oklch, var(--ahr-orgchart-hit) 26%, var(--ahr-orgchart-card)); }
.ahr-orgchart__node.is-ping .ahr-orgchart__card::after {
  content: ""; position: absolute; inset: -2px; border-radius: 15px; border: 2px solid var(--ahr-orgchart-accent);
  animation: ahr-orgchart-ping .9s var(--ahr-orgchart-ease) 2 both;
}
.ahr-orgchart__av {
  display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; flex: none;
  font-size: 12px; font-weight: 680; letter-spacing: .02em;
  color: oklch(0.36 0.09 var(--h)); background: oklch(0.92 0.045 var(--h));
  box-shadow: inset 0 0 0 1px oklch(0.84 0.06 var(--h));
}
.ahr-orgchart__badge {
  position: absolute; left: 50%; bottom: -11px; translate: -50% 0; z-index: 2;
  display: inline-flex; align-items: center; gap: 3px; height: 22px; min-width: 34px; padding: 0 7px 0 8px; border-radius: 11px;
  font-size: 11px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--ahr-orgchart-muted);
  background: var(--ahr-orgchart-card); box-shadow: 0 0 0 1px var(--ahr-orgchart-rule2), 0 2px 5px -2px color-mix(in oklch, var(--ahr-orgchart-ink) 25%, transparent);
  transition: color .2s, background-color .2s, box-shadow .2s;
  & svg { width: 11px; height: 11px; stroke-width: 2.4; transition: rotate .35s var(--ahr-orgchart-spring); }
  &:hover { color: var(--ahr-orgchart-ink); box-shadow: 0 0 0 1.5px var(--ahr-orgchart-accent); }
  &[aria-expanded="true"] { color: var(--ahr-orgchart-card); background: var(--ahr-orgchart-accent); box-shadow: none; }
  &[aria-expanded="true"] svg { rotate: 180deg; }
}
.ahr-orgchart__node.is-stackkid .ahr-orgchart__badge { left: auto; right: 10px; translate: 0 0; }

.ahr-orgchart__zoom {
  position: absolute; left: 14px; bottom: 14px; z-index: 5;
  display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px;
  background: color-mix(in oklch, var(--ahr-orgchart-card) 92%, transparent);
  box-shadow: 0 0 0 1px var(--ahr-orgchart-rule2), 0 10px 24px -14px color-mix(in oklch, var(--ahr-orgchart-ink) 45%, transparent);
  & button { display: grid; place-items: center; min-width: 32px; height: 32px; border-radius: 8px; color: var(--ahr-orgchart-muted); transition: background-color .15s, color .15s; }
  & button:hover:not(:disabled) { background: var(--ahr-orgchart-hover); color: var(--ahr-orgchart-ink); }
  & button svg { width: 16px; height: 16px; }
  & i { width: 1px; height: 18px; margin: 0 3px; background: var(--ahr-orgchart-rule2); }
}
.ahr-orgchart__pct { padding: 0 6px; font-size: 11.5px; font-weight: 650; font-variant-numeric: tabular-nums; }
.ahr-orgchart__keys {
  position: absolute; right: 14px; bottom: 16px; z-index: 4; pointer-events: none;
  display: flex; gap: 12px; font-size: 11px; color: var(--ahr-orgchart-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}

/* ---------- outline ---------- */
.ahr-orgchart__outline {
  position: absolute; inset: 0; overflow: auto; padding: 10px 12px 24px; overscroll-behavior: contain;
  scrollbar-width: thin; scrollbar-color: var(--ahr-orgchart-rule2) transparent;
}
.ahr-orgchart__orow {
  position: relative; display: grid; grid-template-columns: 22px 30px minmax(0, 1fr) auto; align-items: center; gap: 8px;
  min-height: 46px; padding: 6px 10px 6px calc(6px + var(--d) * 22px); border-radius: 10px; cursor: pointer; outline: none;
  transition: background-color .15s;
  &::before { content: ""; position: absolute; left: calc(17px + (var(--d) - 1) * 22px); top: 0; bottom: 0; width: 1px; background: var(--ahr-orgchart-rule2); }
  &[aria-level="1"]::before { display: none; }
  &:hover { background: var(--ahr-orgchart-hover); }
  &[aria-selected="true"] { background: var(--ahr-orgchart-tint); box-shadow: inset 2px 0 0 var(--ahr-orgchart-accent); }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--ahr-orgchart-accent); }
  &.is-dim { opacity: .4; }
  & .ahr-orgchart__av { width: 30px; height: 30px; font-size: 11px; }
  & b { display: block; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.5px; color: var(--ahr-orgchart-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { font-style: normal; font-size: 11px; font-weight: 600; color: var(--ahr-orgchart-faint); font-variant-numeric: tabular-nums; }
}
.ahr-orgchart__twisty {
  display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; color: var(--ahr-orgchart-muted);
  & svg { width: 13px; height: 13px; stroke-width: 2.2; transition: rotate .3s var(--ahr-orgchart-spring); }
  &[data-open="true"] svg { rotate: 90deg; }
  &:hover { background: var(--ahr-orgchart-hover); }
}
@supports (animation-timeline: view()) {
  .ahr-orgchart__orow { animation: ahr-orgchart-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}

/* ---------- profile ---------- */
.ahr-orgchart__side {
  grid-area: side; min-height: 0; overflow: auto; overscroll-behavior: contain;
  border-left: 1px solid var(--ahr-orgchart-rule); background: color-mix(in oklch, var(--ahr-orgchart-card) 55%, var(--ahr-orgchart-paper));
  scrollbar-width: thin; scrollbar-color: var(--ahr-orgchart-rule2) transparent;
}
.ahr-orgchart__pf { position: relative; padding: 18px 18px 22px; display: grid; gap: 18px; animation: ahr-orgchart-in .45s var(--ahr-orgchart-ease) both; }
.ahr-orgchart__close { display: none; position: absolute; right: 12px; top: 12px; width: 32px; height: 32px; border-radius: 9px; place-items: center; color: var(--ahr-orgchart-muted); &:hover { background: var(--ahr-orgchart-hover); } }
.ahr-orgchart__pfhead {
  display: grid; justify-items: start; gap: 2px;
  & .ahr-orgchart__av { width: 56px; height: 56px; font-size: 18px; margin-bottom: 8px; }
  & h2 { font-size: clamp(17px, 1.7cqi, 20px); font-weight: 700; letter-spacing: -0.015em; text-wrap: balance; line-height: 1.2; }
  & p { color: var(--ahr-orgchart-muted); text-wrap: pretty; }
}
.ahr-orgchart__chip {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; height: 22px; padding: 0 9px; border-radius: 99px;
  font-size: 11px; font-weight: 650; letter-spacing: .02em; color: oklch(0.38 0.09 var(--h));
  background: oklch(0.93 0.04 var(--h));
}
.ahr-orgchart__nums {
  display: grid; grid-template-columns: repeat(3, 1fr); border-radius: 12px; overflow: hidden;
  box-shadow: 0 0 0 1px var(--ahr-orgchart-rule);
  & > div { padding: 10px 12px; background: var(--ahr-orgchart-card); }
  & > div + div { border-left: 1px solid var(--ahr-orgchart-rule); }
  & span { display: block; font-size: 10.5px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: var(--ahr-orgchart-faint); }
}
.ahr-orgchart__num {
  display: block; font-size: 22px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums;
  counter-reset: ahr-orgchart-n var(--ahr-orgchart-n);
  transition: --ahr-orgchart-n .9s cubic-bezier(.16, 1, .3, 1);
  @starting-style { --ahr-orgchart-n: 0; }
  &::after { content: counter(ahr-orgchart-n); }
}
.ahr-orgchart__mix {
  display: grid; gap: 7px;
  & .ahr-orgchart__mixbar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px; }
  & .ahr-orgchart__mixbar i { flex: var(--n) 1 0; background: oklch(0.64 0.12 var(--h)); transform-origin: 0 50%; animation: ahr-orgchart-grow .6s var(--ahr-orgchart-ease) calc(var(--i) * 60ms) both; }
  & ul { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--ahr-orgchart-muted); font-variant-numeric: tabular-nums; }
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li i { width: 7px; height: 7px; border-radius: 2px; background: oklch(0.64 0.12 var(--h)); }
  & li b { color: var(--ahr-orgchart-ink); font-weight: 650; }
}
.ahr-orgchart__facts {
  display: grid; gap: 9px;
  & div { display: grid; grid-template-columns: 18px 1fr; gap: 9px; align-items: start; }
  & dt { color: var(--ahr-orgchart-faint); padding-top: 1px; }
  & dt svg { width: 16px; height: 16px; }
  & dd { min-width: 0; overflow-wrap: anywhere; }
  & dd small { display: block; color: var(--ahr-orgchart-muted); font-size: 11.5px; font-variant-numeric: tabular-nums; }
}
.ahr-orgchart__sec {
  display: grid; gap: 6px;
  & h3 { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-orgchart-faint); }
}
.ahr-orgchart__person {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) 14px; align-items: center; gap: 9px; width: 100%;
  padding: 6px 8px; margin: 0 -8px; width: calc(100% + 16px); border-radius: 9px; text-align: left;
  transition: background-color .15s;
  & .ahr-orgchart__av { width: 30px; height: 30px; font-size: 10.5px; }
  & b { display: block; font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; color: var(--ahr-orgchart-muted); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > svg { width: 14px; height: 14px; color: var(--ahr-orgchart-faint); transition: translate .2s var(--ahr-orgchart-ease); }
  &:hover { background: var(--ahr-orgchart-hover); }
  &:hover > svg { translate: 3px 0; color: var(--ahr-orgchart-ink); }
}
.ahr-orgchart__reports li { animation: ahr-orgchart-in .4s var(--ahr-orgchart-ease) calc(var(--i) * 40ms) both; }
.ahr-orgchart__actions {
  display: flex; flex-wrap: wrap; gap: 8px;
  & button {
    display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--ahr-orgchart-rule2); transition: background-color .15s, box-shadow .15s;
  }
  & button svg { width: 15px; height: 15px; }
  & button:hover:not(:disabled) { background: var(--ahr-orgchart-hover); box-shadow: inset 0 0 0 1px var(--ahr-orgchart-wire); }
  & button.is-primary { background: var(--ahr-orgchart-accent); color: var(--ahr-orgchart-card); box-shadow: none; }
  & button.is-primary:hover:not(:disabled) { background: color-mix(in oklch, var(--ahr-orgchart-accent) 86%, black); }
}

/* ---------- toast ---------- */
.ahr-orgchart__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 0;
  display: flex; align-items: center; gap: 8px; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 11px;
  font-size: 12.5px; font-weight: 550; color: var(--ahr-orgchart-card); background: var(--ahr-orgchart-ink);
  box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--ahr-orgchart-ink) 60%, transparent);
  transition: opacity .2s var(--ahr-orgchart-ease), transform .3s var(--ahr-orgchart-spring);
  & svg { width: 15px; height: 15px; color: var(--ahr-orgchart-hit); }
  &:empty { opacity: 0; transform: translateY(10px); pointer-events: none; visibility: hidden; }
  @starting-style { opacity: 0; transform: translateY(10px); }
}

@keyframes ahr-orgchart-ping { from { opacity: 1; scale: 1; } to { opacity: 0; scale: 1.12; } }
@keyframes ahr-orgchart-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-orgchart-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes ahr-orgchart-grow { from { transform: scaleX(0); } }
@keyframes ahr-orgchart-frame { 0% { box-shadow: inset 0 0 0 0 transparent; } 35% { box-shadow: inset 0 0 0 3px color-mix(in oklch, var(--ahr-orgchart-accent) 45%, transparent); } 100% { box-shadow: inset 0 0 0 0 transparent; } }

/* ---------- container: medium — profile becomes a drawer ---------- */
@container (max-width: 959px) {
  .ahr-orgchart__app { grid-template-areas: "head" "bar" "main"; grid-template-columns: minmax(0, 1fr); }
  .ahr-orgchart__side {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 10px; width: min(340px, calc(100% - 20px));
    border: 0; border-radius: 16px; background: var(--ahr-orgchart-card);
    box-shadow: 0 0 0 1px var(--ahr-orgchart-rule2), 0 30px 60px -20px color-mix(in oklch, var(--ahr-orgchart-ink) 45%, transparent);
    transform: translateX(calc(100% + 20px)); visibility: hidden;
    transition: transform .45s var(--ahr-orgchart-spring), visibility 0s .45s;
  }
  .ahr-orgchart[data-sheet="open"] .ahr-orgchart__side { transform: none; visibility: visible; transition: transform .45s var(--ahr-orgchart-spring), visibility 0s; }
  .ahr-orgchart__close { display: grid; }
  .ahr-orgchart__keys { display: none; }
}
/* ---------- container: narrow — single pane ---------- */
@container (max-width: 759px) {
  .ahr-orgchart__head { flex-wrap: wrap; gap: 10px; padding: 12px 12px 8px; }
  .ahr-orgchart__brand span { display: none; }
  .ahr-orgchart__search { order: 3; flex: 1 1 100%; }
  .ahr-orgchart__bar { padding: 0 12px 8px; flex-wrap: wrap; }
  .ahr-orgchart__depts { flex: 1 1 100%; }
  .ahr-orgchart__stats { display: none; }
  .ahr-orgchart__side { inset: 0; width: auto; border-radius: 0; }
  .ahr-orgchart__orow { padding-left: calc(4px + var(--d) * 14px); &::before { left: calc(15px + (var(--d) - 1) * 14px); } }
}
@container (max-width: 420px) {
  .ahr-orgchart__orow { grid-template-columns: 22px 28px minmax(0, 1fr); & em { display: none; } }
  .ahr-orgchart__nums .ahr-orgchart__num { font-size: 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-orgchart *, .ahr-orgchart *::before, .ahr-orgchart *::after { animation: none !important; transition-duration: .01s !important; transition-delay: 0s !important; }
  .ahr-orgchart .ahr-orgchart__num { transition: none; }
  .ahr-orgchart .ahr-orgchart__orow { opacity: 1; translate: none; }
}

