  const z = (a, dis, why) => { const b = $(`.ahr-orgchart__zoom [data-act="${a}"]`); b.disabled = dis; if (dis) b.title = why; else b.removeAttribute('title'); };
  z('in', S.scale >= 1.4, 'Already at the maximum zoom (140%)');
  z('out', S.scale <= 0.4, 'Already at the minimum zoom (40%)');
  z('reset', Math.abs(S.scale - 1) < 0.001, 'Already at 100%');
  const all = Object.keys(K).filter((id) => K[id].length);
