/* Team leave planner. Re-theme with --ahr-timeoff-paper, -ink, -accent and -ok; leave types carry their own hue (--t). */
.ahr-timeoff {
  --ahr-timeoff-paper: oklch(0.984 0.005 250);
  --ahr-timeoff-ink: oklch(0.26 0.025 258);
  --ahr-timeoff-accent: oklch(0.62 0.17 33);
  --ahr-timeoff-ok: oklch(0.64 0.1 172);

  --ahr-timeoff-card: oklch(1 0 0);
  --ahr-timeoff-muted: color-mix(in oklch, var(--ahr-timeoff-ink) 62%, var(--ahr-timeoff-paper));
  --ahr-timeoff-faint: color-mix(in oklch, var(--ahr-timeoff-ink) 40%, var(--ahr-timeoff-paper));
  --ahr-timeoff-rule: color-mix(in oklch, var(--ahr-timeoff-ink) 9%, transparent);
  --ahr-timeoff-rule2: color-mix(in oklch, var(--ahr-timeoff-ink) 16%, transparent);
  --ahr-timeoff-hover: color-mix(in oklch, var(--ahr-timeoff-ink) 5%, transparent);
  --ahr-timeoff-tint: color-mix(in oklch, var(--ahr-timeoff-accent) 9%, var(--ahr-timeoff-card));
  --ahr-timeoff-weekend: color-mix(in oklch, var(--ahr-timeoff-ink) 4%, var(--ahr-timeoff-paper));
  --ahr-timeoff-low: oklch(0.58 0.19 27);
  --ahr-timeoff-namew: 146px;
  --ahr-timeoff-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-timeoff-spring: linear(0, 0.1 5%, 0.38 12%, 0.78 21%, 1 29%, 1.06 36%, 1.05 44%, 1.02 54%, 1 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-timeoff-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-timeoff-paper);
  color: var(--ahr-timeoff-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--ahr-timeoff-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2);
}
:where(.ahr-timeoff) *, :where(.ahr-timeoff) *::before, :where(.ahr-timeoff) *::after { box-sizing: border-box; }
:where(.ahr-timeoff) :is(button, input, textarea, select) { font: inherit; color: inherit; }
:where(.ahr-timeoff) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-timeoff) button:disabled, :where(.ahr-timeoff) button[aria-disabled="true"] { cursor: not-allowed; opacity: .42; }
:where(.ahr-timeoff) :is(p, h2, h3, ul, fieldset, legend) { margin: 0; padding: 0; }
:where(.ahr-timeoff) ul { list-style: none; }
:where(.ahr-timeoff) fieldset { border: 0; min-width: 0; }
:where(.ahr-timeoff) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-timeoff) :focus-visible { outline: 2px solid var(--ahr-timeoff-accent); outline-offset: 2px; }
:where(.ahr-timeoff) kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-timeoff-muted);
  background: var(--ahr-timeoff-card); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2), 0 1px 0 var(--ahr-timeoff-rule2);
}

.ahr-timeoff__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "queue cal";
  grid-template-columns: clamp(256px, 25cqi, 300px) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
}

/* ---------- header ---------- */
.ahr-timeoff__head {
  grid-area: head; display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--ahr-timeoff-rule);
}
.ahr-timeoff__brand {
  display: flex; align-items: center; gap: 10px; min-width: 0; margin-right: auto;
  & > svg { width: 32px; height: 32px; padding: 6px; border-radius: 10px; color: var(--ahr-timeoff-card); background: var(--ahr-timeoff-ink); }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -0.01em; }
  & span { display: block; font-size: 11.5px; color: var(--ahr-timeoff-muted); }
}
.ahr-timeoff__views { display: none; padding: 3px; border-radius: 9px; background: var(--ahr-timeoff-hover);
