.ahr-timeoff__tabs {
  display: flex; gap: 2px; padding: 10px 12px 0; border-bottom: 1px solid var(--ahr-timeoff-rule); overflow: hidden;
  & button { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 9px; font-size: 12.5px; font-weight: 600; color: var(--ahr-timeoff-muted); }
  & button::after { content: ""; position: absolute; left: 6px; right: 6px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--ahr-timeoff-ink); scale: 0 1; transition: scale .3s var(--ahr-timeoff-spring); }
  & button[aria-selected="true"] { color: var(--ahr-timeoff-ink); }
