  &.is-sel { box-shadow: 0 0 0 1.5px var(--ahr-timeoff-ink), 0 10px 24px -14px color-mix(in oklch, var(--ahr-timeoff-ink) 40%, transparent); }
  &.is-new { animation: ahr-timeoff-arrive .6s var(--ahr-timeoff-spring) both; }
}
.ahr-timeoff__cardmain {
  display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 4px 10px; align-items: center; width: 100%; padding: 11px 12px; text-align: left; border-radius: 12px;
  &:hover { background: var(--ahr-timeoff-hover); }
  & b { display: block; font-weight: 650; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.5px; color: var(--ahr-timeoff-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-timeoff__av {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; font-size: 11.5px; font-weight: 700;
  color: oklch(0.36 0.06 var(--ah)); background: oklch(0.93 0.035 var(--ah));
}
.ahr-timeoff__type {
  display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: 6px;
  font-size: 10.5px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase;
  color: oklch(0.4 0.09 var(--t)); background: color-mix(in oklch, var(--c, oklch(0.62 0.11 var(--t))) 15%, var(--ahr-timeoff-card));
