.ahr-timeoff__flag { grid-column: 2 / -1; display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600; color: var(--ahr-timeoff-low);
  & svg { width: 14px; height: 14px; }
