}
.ahr-timeoff__bal {
  display: grid; gap: 6px;
  & header { display: flex; justify-content: space-between; font-size: 11.5px; color: var(--ahr-timeoff-muted); }
  & header b { color: var(--ahr-timeoff-ink); font-variant-numeric: tabular-nums; }
  & .ahr-timeoff__balbar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px; background: var(--ahr-timeoff-hover); }
  & .ahr-timeoff__balbar i { flex: var(--n) 0 0; transform-origin: 0 50%; animation: ahr-timeoff-grow .6s var(--ahr-timeoff-ease) calc(var(--i) * 70ms) both; }
  & ul { display: flex; flex-wrap: wrap; gap: 3px 11px; font-size: 11px; color: var(--ahr-timeoff-muted); font-variant-numeric: tabular-nums; }
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li i { width: 7px; height: 7px; border-radius: 2px; }
