  & .is-approve kbd { background: color-mix(in oklch, var(--ahr-timeoff-card) 20%, transparent); color: inherit; box-shadow: none; }
  & .is-approve:hover:not(:disabled):not([aria-disabled="true"]) { background: color-mix(in oklch, var(--ahr-timeoff-ink) 82%, var(--ahr-timeoff-accent)); }
  & .is-approve.is-confirm { background: var(--ahr-timeoff-low); }
  & .is-decline { flex: 1; }
}
.ahr-timeoff__reasons {
  display: grid; gap: 6px; padding: 10px; border-radius: 10px; background: var(--ahr-timeoff-paper); animation: ahr-timeoff-open .3s var(--ahr-timeoff-ease) both;
  & p { font-size: 12px; font-weight: 600; }
  & div { display: flex; flex-wrap: wrap; gap: 5px; }
  & button { height: 28px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 560; background: var(--ahr-timeoff-card); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); }
  & button:hover { box-shadow: inset 0 0 0 1.5px var(--ahr-timeoff-low); color: var(--ahr-timeoff-low); }
  & button.is-cancel { background: none; box-shadow: none; color: var(--ahr-timeoff-muted); }
}
.ahr-timeoff__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 9px 14px; border-top: 1px solid var(--ahr-timeoff-rule); font-size: 11px; color: var(--ahr-timeoff-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}

/* ---------- calendar ---------- */
.ahr-timeoff__cal { grid-area: cal; position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.ahr-timeoff__legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 10px 14px 8px;
  & button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px 0 8px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--ahr-timeoff-muted); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); transition: opacity .2s, background-color .2s; }
  & button i { width: 10px; height: 10px; border-radius: 3px; background: oklch(0.62 0.11 var(--t)); transition: scale .3s var(--ahr-timeoff-spring); }
  & button[aria-pressed="false"] { opacity: .55; }
  & button[aria-pressed="false"] i { scale: .5; }
  & button:hover { background: var(--ahr-timeoff-hover); }
  & .ahr-timeoff__key { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--ahr-timeoff-faint); margin-left: 4px; }
  & .ahr-timeoff__key i { width: 14px; height: 10px; border-radius: 3px; }
}
.ahr-timeoff__k-pend { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--ahr-timeoff-ink) 35%, transparent) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); }
.ahr-timeoff__k-hol { background: repeating-linear-gradient(90deg, var(--ahr-timeoff-rule2) 0 1px, transparent 1px 3px); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); }
.ahr-timeoff__scroll {
  position: relative; overflow: auto; overscroll-behavior: contain; margin: 0 14px; border-radius: 12px; background: var(--ahr-timeoff-card);
  box-shadow: 0 0 0 1px var(--ahr-timeoff-rule2);
  scrollbar-width: thin; scrollbar-color: var(--ahr-timeoff-rule2) transparent;
}
.ahr-timeoff__grid {
  position: relative;
  display: grid;
  grid-template-columns: var(--ahr-timeoff-namew) repeat(var(--days), minmax(21px, 1fr));
  grid-template-rows: 44px repeat(var(--rows), 48px) 74px;
  min-width: min-content;
}
.ahr-timeoff__grid.is-slide-l { animation: ahr-timeoff-slide-l .4s var(--ahr-timeoff-ease); }
.ahr-timeoff__grid.is-slide-r { animation: ahr-timeoff-slide-r .4s var(--ahr-timeoff-ease); }
.ahr-timeoff__col { grid-row: 1 / -1; pointer-events: none; }
.ahr-timeoff__col.is-wkd { background: var(--ahr-timeoff-weekend); }
.ahr-timeoff__col.is-hol { background: repeating-linear-gradient(90deg, var(--ahr-timeoff-rule) 0 1px, transparent 1px 4px), var(--ahr-timeoff-weekend); }
.ahr-timeoff__col.is-sel { background: color-mix(in oklch, var(--ahr-timeoff-accent) 9%, transparent); box-shadow: inset 1.5px 0 0 color-mix(in oklch, var(--ahr-timeoff-accent) 45%, transparent), inset -1.5px 0 0 color-mix(in oklch, var(--ahr-timeoff-accent) 45%, transparent); z-index: 0; animation: ahr-timeoff-fade .35s var(--ahr-timeoff-ease) both; }
.ahr-timeoff__col.is-now { justify-self: center; width: 2px; background: var(--ahr-timeoff-accent); z-index: 4; border-radius: 2px; }
.ahr-timeoff__row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; position: relative; border-bottom: 1px solid var(--ahr-timeoff-rule); }
.ahr-timeoff__dh {
  position: sticky; top: 0; z-index: 6; background: color-mix(in oklch, var(--ahr-timeoff-card) 94%, transparent); backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--ahr-timeoff-rule2);
  & > span { grid-row: 1; display: grid; justify-items: center; gap: 1px; font-size: 10px; font-weight: 600; color: var(--ahr-timeoff-faint); letter-spacing: .04em; }
  & > span b { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; font-size: 11.5px; font-weight: 650; color: var(--ahr-timeoff-ink); font-variant-numeric: tabular-nums; letter-spacing: 0; }
  & > span.is-off b { color: var(--ahr-timeoff-faint); }
  & > span.is-today b { color: var(--ahr-timeoff-card); background: var(--ahr-timeoff-accent); }
  & > span.is-in b { box-shadow: inset 0 0 0 1.5px var(--ahr-timeoff-accent); }
}
.ahr-timeoff__corner { grid-column: 1; grid-row: 1; position: sticky; left: 0; z-index: 7; align-self: stretch; display: flex; align-items: center; padding: 0 12px; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ahr-timeoff-faint); background: var(--ahr-timeoff-card); }
.ahr-timeoff__who {
  grid-column: 1; grid-row: 1; position: sticky; left: 0; z-index: 5; align-self: stretch;
  display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 0 10px 0 12px;
  background: var(--ahr-timeoff-card); border-right: 1px solid var(--ahr-timeoff-rule);
  & .ahr-timeoff__av { width: 28px; height: 28px; font-size: 10px; }
  & b { display: block; font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 10.5px; color: var(--ahr-timeoff-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { font-style: normal; font-size: 10.5px; font-weight: 650; color: var(--ahr-timeoff-muted); font-variant-numeric: tabular-nums; }
}
@supports (animation-timeline: scroll()) {
  .ahr-timeoff__scroll { scroll-timeline: --ahr-timeoff-x inline; }
  .ahr-timeoff__who, .ahr-timeoff__corner { animation: ahr-timeoff-edge linear both; animation-timeline: --ahr-timeoff-x; animation-range: 0 40px; }
}
.ahr-timeoff__row.is-me .ahr-timeoff__who b::after { content: " (you)"; font-weight: 500; color: var(--ahr-timeoff-faint); }
.ahr-timeoff__cell { grid-row: 1; align-self: stretch; cursor: crosshair; z-index: 1; }
.ahr-timeoff__row.is-me .ahr-timeoff__cell:hover { background: color-mix(in oklch, var(--ahr-timeoff-accent) 10%, transparent); }
.ahr-timeoff__bar {
  --c: oklch(0.62 0.11 var(--t));
  grid-row: 1; z-index: 2; position: relative; min-width: 0; height: 30px; margin: 0 2px;
  display: flex; align-items: center; gap: 6px; padding: 0 8px; border-radius: 8px; overflow: hidden;
  font-size: 11.5px; font-weight: 650; white-space: nowrap; text-align: left;
  color: var(--ahr-timeoff-card); background: var(--c);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--c) 40%, transparent);
  transition: translate .2s var(--ahr-timeoff-ease), box-shadow .2s, filter .2s;
  & span { overflow: hidden; text-overflow: ellipsis; }
  & svg { width: 13px; height: 13px; stroke-width: 2.2; }
  &::before { content: ""; position: absolute; inset: 0; pointer-events: none; opacity: 0;
    background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) 30%, var(--ahr-timeoff-card)) 0 5px, color-mix(in oklch, var(--c) 12%, var(--ahr-timeoff-card)) 5px 10px); }
  &:hover { translate: 0 -1px; box-shadow: 0 6px 14px -6px color-mix(in oklch, var(--c) 70%, transparent); }
  &.is-sel { box-shadow: 0 0 0 2px var(--ahr-timeoff-card), 0 0 0 3.5px var(--ahr-timeoff-ink); }
  &.is-clip-s { border-top-left-radius: 0; border-bottom-left-radius: 0; margin-left: 0; }
  &.is-clip-e { border-top-right-radius: 0; border-bottom-right-radius: 0; margin-right: 0; }
  &[data-status="pending"] { color: oklch(0.36 0.09 var(--t)); background: var(--ahr-timeoff-card); box-shadow: inset 0 0 0 1.5px var(--c); }
  &[data-status="pending"]::before { opacity: 1; }
  & > * { position: relative; }
  &.is-tiny { padding: 0; justify-content: center; }
  &.is-fresh::before { opacity: 1; animation: ahr-timeoff-wipe .7s cubic-bezier(.65, 0, .35, 1) .1s both; }
  &.is-draft { --c: var(--ahr-timeoff-accent); color: oklch(0.42 0.14 33); background: color-mix(in oklch, var(--ahr-timeoff-accent) 12%, var(--ahr-timeoff-card)); box-shadow: inset 0 0 0 1.5px var(--ahr-timeoff-accent); outline: 2px dashed color-mix(in oklch, var(--ahr-timeoff-accent) 50%, transparent); outline-offset: 2px; pointer-events: none; }
  &.is-hidden { display: none; }
}
.ahr-timeoff__covrow { background: var(--ahr-timeoff-paper); border-bottom: 0; }
.ahr-timeoff__covrow .ahr-timeoff__who { grid-template-columns: minmax(0, 1fr); background: var(--ahr-timeoff-paper); & b { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--ahr-timeoff-muted); } }
.ahr-timeoff__cov {
  grid-row: 1; align-self: stretch; display: grid; grid-template-rows: 1fr auto; justify-items: center; gap: 4px; padding: 10px 2px 8px;
  & i { position: relative; width: min(12px, 70%); border-radius: 3px; overflow: hidden; background: color-mix(in oklch, var(--ahr-timeoff-ink) 7%, transparent); }
  & i s { position: absolute; inset: 0; transform-origin: 50% 100%; transform: scaleY(var(--a)); background: var(--ahr-timeoff-ok); border-radius: 3px; }
  & i u { position: absolute; left: 0; right: 0; bottom: calc(var(--p) * 100%); height: calc((var(--a) - var(--p)) * 100%); background: repeating-linear-gradient(-45deg, var(--ahr-timeoff-low) 0 2px, transparent 2px 4px); opacity: .9; }
  & i::after { content: ""; position: absolute; left: -3px; right: -3px; bottom: calc(var(--m) * 100%); height: 1.5px; background: var(--ahr-timeoff-ink); opacity: .55; }
  & b { font-size: 10.5px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--ahr-timeoff-muted); }
  &[data-state="low"] i s { background: var(--ahr-timeoff-low); }
  &[data-state="low"] b, &[data-state="risk"] b { color: var(--ahr-timeoff-low); }
  &[data-state="off"] i { visibility: hidden; }
  &[data-state="off"] b { color: var(--ahr-timeoff-faint); font-weight: 500; }
}
.ahr-timeoff__hint { padding: 8px 16px 12px; font-size: 11.5px; color: var(--ahr-timeoff-faint); text-wrap: pretty; }

/* ---------- composer ---------- */
.ahr-timeoff__composer {
  position: absolute; z-index: 30; right: 16px; bottom: 16px; width: min(360px, calc(100% - 32px));
  display: grid; gap: 12px; padding: 16px; border-radius: 16px; background: var(--ahr-timeoff-card);
  box-shadow: 0 0 0 1px var(--ahr-timeoff-rule2), 0 30px 60px -24px color-mix(in oklch, var(--ahr-timeoff-ink) 50%, transparent);
  transform-origin: 100% 100%;
  transition: opacity .2s var(--ahr-timeoff-ease), transform .35s var(--ahr-timeoff-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.97); }
  &[hidden] { display: none; }
  & header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
  & h3 { font-size: 14.5px; font-weight: 700; letter-spacing: -0.01em; }
  & header button { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; color: var(--ahr-timeoff-muted); }
  & header button:hover { background: var(--ahr-timeoff-hover); }
  & legend { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ahr-timeoff-faint); margin-bottom: 6px; }
  & .ahr-timeoff__types { display: flex; flex-wrap: wrap; gap: 6px; }
  & .ahr-timeoff__types label { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px 0 9px; border-radius: 99px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); transition: background-color .15s, box-shadow .15s; }
  & .ahr-timeoff__types input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & .ahr-timeoff__types i { width: 9px; height: 9px; border-radius: 50%; background: oklch(0.62 0.11 var(--t)); }
  & .ahr-timeoff__types label:has(input:checked) { background: color-mix(in oklch, oklch(0.62 0.11 var(--t)) 14%, var(--ahr-timeoff-card)); box-shadow: inset 0 0 0 1.5px oklch(0.62 0.11 var(--t)); }
  & .ahr-timeoff__types label:has(input:focus-visible) { outline: 2px solid var(--ahr-timeoff-accent); outline-offset: 2px; }
  & .ahr-timeoff__dates { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  & .ahr-timeoff__dates label { display: grid; gap: 4px; font-size: 11px; font-weight: 600; color: var(--ahr-timeoff-muted); }
  & input[type="date"], & textarea { width: 100%; border: 0; border-radius: 9px; padding: 8px 10px; background: var(--ahr-timeoff-paper); box-shadow: inset 0 0 0 1px var(--ahr-timeoff-rule2); font-size: 12.5px; font-variant-numeric: tabular-nums; }
  & textarea { resize: none; min-height: 54px; }
  & :is(input[type="date"], textarea):focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--ahr-timeoff-accent); }
  & [aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ahr-timeoff-low) !important; }
  & footer { display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
  & footer button { height: 34px; padding: 0 14px; border-radius: 9px; font-size: 12.5px; font-weight: 650; }
  & footer .is-ghost { color: var(--ahr-timeoff-muted); }
  & footer .is-ghost:hover { background: var(--ahr-timeoff-hover); }
  & footer button[type="submit"] { color: var(--ahr-timeoff-card); background: var(--ahr-timeoff-accent); }
}
.ahr-timeoff__sum { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; padding: 10px 12px; border-radius: 10px; background: var(--ahr-timeoff-paper); font-size: 12px; color: var(--ahr-timeoff-muted);
  & b { font-size: 20px; font-weight: 750; letter-spacing: -0.02em; color: var(--ahr-timeoff-ink); font-variant-numeric: tabular-nums; }
  & .is-err { flex-basis: 100%; color: var(--ahr-timeoff-low); font-weight: 600; }
}

/* ---------- toast ---------- */
.ahr-timeoff__toast {
  position: absolute; z-index: 40; left: 16px; bottom: 16px; display: flex; align-items: center; gap: 10px; max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px; border-radius: 12px; color: var(--ahr-timeoff-card); background: var(--ahr-timeoff-ink); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 30px -14px color-mix(in oklch, var(--ahr-timeoff-ink) 70%, transparent);
  transition: opacity .2s var(--ahr-timeoff-ease), transform .35s var(--ahr-timeoff-spring);
  @starting-style { opacity: 0; transform: translateY(12px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(12px); }
  & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 8px; font-weight: 650; color: oklch(0.85 0.1 50); }
  & button:hover { background: color-mix(in oklch, var(--ahr-timeoff-card) 12%, transparent); }
  & button kbd { color: inherit; background: color-mix(in oklch, var(--ahr-timeoff-card) 16%, transparent); box-shadow: none; }
}

@keyframes ahr-timeoff-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-timeoff-arrive { from { opacity: 0; transform: translateY(-14px) scale(.96); } }
@keyframes ahr-timeoff-open { from { opacity: 0; translate: 0 -4px; } }
@keyframes ahr-timeoff-grow { from { transform: scaleX(0); } }
@keyframes ahr-timeoff-fade { from { opacity: 0; } }
@keyframes ahr-timeoff-wipe { from { clip-path: inset(0 0 0 0); } to { clip-path: inset(0 0 0 100%); } }
@keyframes ahr-timeoff-slide-l { from { opacity: .2; translate: -28px 0; } }
@keyframes ahr-timeoff-slide-r { from { opacity: .2; translate: 28px 0; } }
@keyframes ahr-timeoff-edge { from { box-shadow: none; } to { box-shadow: 8px 0 14px -10px color-mix(in oklch, var(--ahr-timeoff-ink) 40%, transparent); } }
@keyframes ahr-timeoff-flash { 0%, 100% { opacity: 1; } 40% { opacity: .2; } }
.ahr-timeoff__col.is-now.is-flash { animation: ahr-timeoff-flash .45s ease-in-out 3; }

/* ---------- container: medium ---------- */
@container (max-width: 1080px) {
  .ahr-timeoff__min span { display: none; }
  .ahr-timeoff__brand span { display: none; }
}
@container (max-width: 959px) {
  .ahr-timeoff__app { grid-template-columns: 268px minmax(0, 1fr); }
  .ahr-timeoff__tabs { padding: 10px 8px 0; & button { padding: 0 6px; font-size: 12px; } }
  .ahr-timeoff__new span, .ahr-timeoff__new kbd { display: none; }
  .ahr-timeoff__new { padding: 0 9px; }
  .ahr-timeoff { --ahr-timeoff-namew: 132px; }
  .ahr-timeoff__who em { display: none; }
  .ahr-timeoff__who { grid-template-columns: 28px minmax(0, 1fr); }
}
/* ---------- container: narrow — one pane at a time ---------- */
@container (max-width: 759px) {
  .ahr-timeoff__app { grid-template-areas: "head" "pane"; grid-template-columns: minmax(0, 1fr); }
  .ahr-timeoff__queue, .ahr-timeoff__cal { grid-area: pane; border: 0; }
  .ahr-timeoff[data-view="queue"] .ahr-timeoff__cal, .ahr-timeoff[data-view="cal"] .ahr-timeoff__queue { display: none; }
  .ahr-timeoff__head { flex-wrap: wrap; padding: 10px 12px; gap: 8px; }
  .ahr-timeoff__brand { flex: 1 1 auto; }
  .ahr-timeoff__views { display: inline-flex; order: 2; }
  .ahr-timeoff__month { order: 3; flex: 1 1 auto; }
  .ahr-timeoff__month h2 { min-width: 0; flex: 1; }
  .ahr-timeoff__min { order: 4; }
  .ahr-timeoff__new { order: 1; }
  .ahr-timeoff__keys { display: none; }
  .ahr-timeoff__scroll { margin: 0 10px; }
  .ahr-timeoff { --ahr-timeoff-namew: 112px; }
  .ahr-timeoff__who { grid-template-columns: minmax(0, 1fr); padding: 0 8px; & .ahr-timeoff__av { display: none; } }
}
@container (max-width: 420px) {
  .ahr-timeoff__todaybtn kbd { display: none; }
  .ahr-timeoff__brand b { font-size: 13px; }
  .ahr-timeoff__composer { right: 8px; bottom: 8px; width: calc(100% - 16px); }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-timeoff *, .ahr-timeoff *::before, .ahr-timeoff *::after { animation: none !important; transition-duration: .01s !important; }
  .ahr-timeoff .ahr-timeoff__bar.is-fresh::before { opacity: 0; }
}

