// Team leave planner. Requests are the single source of truth: the queue, the bars, the
// coverage strip and every balance are derived from `R` on each render.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.38 12%, 0.78 21%, 1 29%, 1.06 36%, 1.05 44%, 1.02 54%, 1 68%, 1)';
root.addEventListener('submit', (e) => e.preventDefault());

const ICON = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  x: '<path d="M6 6l12 12M18 6 6 18"/>',
  warn: '<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4.5M12 17.2v.1"/>',
  ok: '<circle cx="12" cy="12" r="8.5"/><path d="m8.5 12.3 2.4 2.4 4.8-5"/>',
  undo: '<path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
  send: '<path d="M4 12 20 4l-5 16-3.5-6.5z"/><path d="m11.5 13.5 3-3"/>',
  sun: '<circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4"/>',
  inbox: '<path d="M3.5 13.5 6 5h12l2.5 8.5V19a1 1 0 0 1-1 1h-15a1 1 0 0 1-1-1z"/><path d="M3.5 13.5H9a3 3 0 0 0 6 0h5.5"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

/* ---------------- calendar maths (UTC noon, so no DST surprises) ---------------- */
const TODAY = '2026-10-02';
const dt = (s) => new Date(s + 'T12:00:00Z');
const iso = (d) => d.toISOString().slice(0, 10);
const add = (s, n) => iso(new Date(dt(s).getTime() + n * 864e5));
const dow = (s) => dt(s).getUTCDay();
const HOL = { '2026-10-12': 'Studio holiday', '2026-11-11': 'Veterans Day', '2026-11-26': 'Thanksgiving', '2026-11-27': 'Day after Thanksgiving' };
const isWork = (s) => dow(s) % 6 !== 0 && !HOL[s];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MON = MONTHS.map((m) => m.slice(0, 3));
const DOW1 = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
function workdays(a, b) { let n = 0; for (let s = a; s <= b; s = add(s, 1)) if (isWork(s)) n++; return n; }
function fmtRange(a, b) {
  const A = dt(a), B = dt(b);
  if (a === b) return `${MON[A.getUTCMonth()]} ${A.getUTCDate()}`;
  if (A.getUTCMonth() === B.getUTCMonth()) return `${MON[A.getUTCMonth()]} ${A.getUTCDate()}–${B.getUTCDate()}`;
  return `${MON[A.getUTCMonth()]} ${A.getUTCDate()} – ${MON[B.getUTCMonth()]} ${B.getUTCDate()}`;
}
function fmtDays(list) {
  // collapse consecutive work days: ["2026-10-15","2026-10-16"] -> "Oct 15–16"
  const out = []; let run = null;
  list.forEach((s) => {
    if (run && workdays(add(run[1], 1), s) === 1 && workdays(add(run[1], 1), add(s, -1)) === 0) run[1] = s;
    else { run = [s, s]; out.push(run); }
  });
  return out.map(([a, b]) => fmtRange(a, b)).join(', ');
}

/* ---------------- people & requests ---------------- */
const TYPES = {
  vacation: { name: 'Vacation', t: 182, pto: true },
  personal: { name: 'Personal', t: 82, pto: true },
  sick: { name: 'Sick', t: 350, pto: false },
  parental: { name: 'Parental', t: 255, pto: false },
  training: { name: 'Training', t: 128, pto: false },
};
const ME = 'noa';
const APPROVER = 'Odile Fairbanks';
const PEOPLE = [
  { id: 'noa', name: 'Noa Whitfield', role: 'Studio Director', allow: 25, used: 14, h: 20 },
  { id: 'kai', name: 'Kai Brennan-Ito', role: 'Senior Designer', allow: 25, used: 12, h: 200 },
  { id: 'marisol', name: 'Marisol Vega', role: 'Account Lead', allow: 20, used: 9, h: 60 },
  { id: 'theo', name: 'Theo Lindgren', role: 'Motion Designer', allow: 20, used: 13, h: 240 },
  { id: 'adaeze', name: 'Adaeze Nwosu', role: 'Strategist', allow: 20, used: 10, h: 140 },
  { id: 'jonas', name: 'Jonas Pereira', role: 'Developer', allow: 25, used: 15, h: 300 },
  { id: 'saoirse', name: 'Saoirse Kenny', role: 'Producer', allow: 20, used: 11, h: 100 },
  { id: 'ravi', name: 'Ravi Menon', role: 'Designer', allow: 25, used: 6, h: 330 },
];
const PP = Object.fromEntries(PEOPLE.map((p) => [p.id, p]));
const N = PEOPLE.length;
let R = [
  { id: 'r1', who: 'ravi', type: 'parental', from: '2026-09-28', to: '2026-10-23', status: 'approved', note: 'Back on the 26th — Saoirse has my client handovers.', at: 'Aug 14' },
  { id: 'r2', who: 'marisol', type: 'sick', from: '2026-10-01', to: '2026-10-01', status: 'approved', note: 'Migraine, offline today.', at: 'Oct 1' },
  { id: 'r3', who: 'kai', type: 'vacation', from: '2026-10-14', to: '2026-10-16', status: 'approved', note: 'Long weekend in the San Juans.', at: 'Sep 9' },
  { id: 'r4', who: 'adaeze', type: 'training', from: '2026-10-15', to: '2026-10-16', status: 'approved', note: 'Speaking at the Northbound Design Summit.', at: 'Sep 2' },
  { id: 'r5', who: 'theo', type: 'vacation', from: '2026-10-13', to: '2026-10-16', status: 'pending', note: 'Sister’s wedding in Gothenburg — flights are booked.', at: 'Sep 30' },
  { id: 'r6', who: 'saoirse', type: 'personal', from: '2026-10-09', to: '2026-10-09', status: 'pending', note: 'Moving apartments.', at: 'Oct 1' },
  { id: 'r7', who: 'jonas', type: 'vacation', from: '2026-10-26', to: '2026-10-30', status: 'pending', note: 'After the Fernway launch ships on the 22nd.', at: 'Sep 28' },
  { id: 'r8', who: 'marisol', type: 'vacation', from: '2026-11-02', to: '2026-11-06', status: 'approved', note: 'Family visit, Oaxaca.', at: 'Aug 30' },
  { id: 'r9', who: 'saoirse', type: 'vacation', from: '2026-11-23', to: '2026-11-25', status: 'pending', note: 'Turning Thanksgiving into a full week.', at: 'Sep 29' },
  { id: 'r10', who: 'jonas', type: 'vacation', from: '2026-10-05', to: '2026-10-06', status: 'declined', note: 'Short trip before launch.', at: 'Sep 12', reason: 'Launch week' },
];
let seq = 11;

const S = { y: 2026, m: 9, tab: 'pending', sel: 'r5', min: 5, hidden: new Set(), confirm: null, declining: null, view: 'queue', fresh: null, newId: null, draft: null, composing: false };
const undo = [];
const snapshot = () => R.map((r) => ({ ...r }));

/* ---------------- derived figures ---------------- */
const covers = (r, s) => r.from <= s && s <= r.to;
function outOn(s, extra) {
  const out = new Set();
  R.forEach((r) => { if (r.status === 'approved' && covers(r, s)) out.add(r.who); });
  if (extra && covers(extra, s)) out.add(extra.who);
  return out;
}
function conflicts(r) {
  const days = [];
  if (r.status !== 'pending') return days;
  for (let s = r.from; s <= r.to; s = add(s, 1)) {
    if (!isWork(s)) continue;
    if (N - outOn(s, r).size < S.min) days.push(s);
  }
  return days;
}
function balance(who, extra) {
  const p = PP[who], o = { allow: p.allow, used: p.used, booked: 0, pending: 0, thisReq: 0 };
  R.forEach((r) => {
    if (r.who !== who || !TYPES[r.type].pto || r.status === 'declined') return;
    const n = workdays(r.from, r.to);
    if (extra && r.id === extra.id) { o.thisReq += n; return; }
    if (r.status === 'approved') { if (r.to < TODAY) o.used += n; else o.booked += n; }
    else o.pending += n;
  });
  o.left = o.allow - o.used - o.booked - o.pending - o.thisReq;
  return o;
}
const byId = (id) => R.find((r) => r.id === id);
const monthDays = () => { const n = new Date(Date.UTC(S.y, S.m + 1, 0)).getUTCDate(); return Array.from({ length: n }, (_, i) => iso(new Date(Date.UTC(S.y, S.m, i + 1, 12)))); };
const ini = (id) => PP[id].name.split(/[\s-]/).map((w) => w[0]).slice(0, 2).join('');
const av = (id) => `<span class="ahr-timeoff__av" style="--ah:${PP[id].h}" aria-hidden="true">${ini(id)}</span>`;
const typeChip = (t) => `<span class="ahr-timeoff__type" style="--t:${TYPES[t].t}"><i></i>${TYPES[t].name}</span>`;
const first = (id) => PP[id].name.split(' ')[0];

/* ---------------- render: header ---------------- */
function renderHead() {
  $('.ahr-timeoff__month h2').textContent = `${MONTHS[S.m]} ${S.y}`;
  const prev = $('[data-act="prev"]'), next = $('[data-act="next"]');
  prev.disabled = S.m <= 8; prev.title = prev.disabled ? 'Leave data starts in September 2026' : '';
  next.disabled = S.m >= 11; next.title = next.disabled ? 'Requests are open through December 2026' : '';
  $('.ahr-timeoff__min output').textContent = S.min;
  const lo = $('[data-act="min-"]'), hi = $('[data-act="min+"]');
  lo.disabled = S.min <= 3; lo.title = lo.disabled ? 'Client Services needs at least 3 people on duty' : '';
  hi.disabled = S.min >= 7; hi.title = hi.disabled ? 'A minimum of 8 would block all leave' : '';
  $$('.ahr-timeoff__views [role="tab"]').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.view === S.view)));
  root.dataset.view = S.view;
}

/* ---------------- render: queue ---------------- */
function flip(container, sel, fn) {
  const before = new Map($$(sel, container).map((el) => [el.dataset.key, el.getBoundingClientRect()]));
  fn();
  if (RM.matches) return;
  $$(sel, container).forEach((el) => {
    const b = before.get(el.dataset.key); if (!b) return;
    const a = el.getBoundingClientRect(), dy = b.top - a.top;
    if (Math.abs(dy) > 1) el.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 420, easing: SPRING });
  });
}
function cardHTML(r, i) {
  const p = PP[r.who], n = workdays(r.from, r.to), sel = r.id === S.sel, mine = r.who === ME;
  const cf = conflicts(r);
  let flag = '';
  if (r.status === 'pending') {
    if (mine) flag = `<span class="ahr-timeoff__flag is-own">${ic('send')}Sent to ${APPROVER}</span>`;
    else if (cf.length) flag = `<span class="ahr-timeoff__flag">${ic('warn')}Coverage under ${S.min} on ${fmtDays(cf)}</span>`;
    else flag = `<span class="ahr-timeoff__flag is-ok">${ic('ok')}Coverage holds</span>`;
  } else if (r.status === 'declined') flag = `<span class="ahr-timeoff__flag is-own">${ic('x')}Declined · ${esc(r.reason || 'No reason given')}</span>`;
  let body = '';
  if (sel) {
    const b = balance(r.who, r.status === 'pending' ? r : null), pto = TYPES[r.type].pto;
    const segs = pto ? [['used', b.used, 'Used'], ['booked', b.booked, 'Booked'], ['pend', b.pending, 'Other pending'], ['this', b.thisReq, 'This request'], ['left', Math.max(0, b.left), 'Left']].filter((s) => s[1] > 0) : [];
    const balHTML = pto ? `<div class="ahr-timeoff__bal"><header><span>${first(r.who)}’s PTO ${S.y}</span><span><b>${b.left}</b> of ${b.allow} days left</span></header>
      <div class="ahr-timeoff__balbar" role="img" aria-label="${segs.map((s) => s[1] + ' ' + s[2]).join(', ')}">${segs.map((s, k) => `<i class="ahr-timeoff__seg-${s[0]}" style="--n:${s[1]};--i:${k}"></i>`).join('')}</div>
      <ul>${segs.map((s) => `<li><i class="ahr-timeoff__seg-${s[0]}"></i>${s[2]} <b>${s[1]}</b></li>`).join('')}</ul></div>`
      : `<div class="ahr-timeoff__bal"><header><span>${TYPES[r.type].name} leave doesn’t use PTO</span><span><b>${balance(r.who).left}</b> PTO days left</span></header></div>`;
    let acts = '';
    if (S.declining === r.id) {
      acts = `<div class="ahr-timeoff__reasons"><p>Why decline ${first(r.who)}’s request?</p><div>${['Coverage', 'Launch week', 'Overlaps a teammate', 'Needs more notice'].map((x) => `<button type="button" data-reason="${esc(x)}">${esc(x)}</button>`).join('')}<button type="button" class="is-cancel" data-act="nodecline">Cancel</button></div></div>`;
    } else if (r.status === 'pending' && mine) {
      acts = `<div class="ahr-timeoff__acts"><button type="button" class="is-approve" aria-disabled="true" title="Your own requests are approved by ${APPROVER}">${ic('clock')}Awaiting ${APPROVER.split(' ')[0]}</button><button type="button" data-act="withdraw">${ic('undo')}Withdraw</button></div>`;
    } else if (r.status === 'pending') {
      const confirming = S.confirm === r.id;
      acts = `<div class="ahr-timeoff__acts"><button type="button" class="is-approve${confirming ? ' is-confirm' : ''}" data-act="approve">${ic('check')}${confirming ? 'Approve anyway' : 'Approve'}<kbd>A</kbd></button><button type="button" class="is-decline" data-act="decline">${ic('x')}Decline<kbd>D</kbd></button></div>`;
    } else if (r.status === 'approved') {
      acts = `<div class="ahr-timeoff__acts"><button type="button" data-act="reopen">${ic('undo')}Move back to pending</button></div>`;
    } else {
      acts = `<div class="ahr-timeoff__acts"><button type="button" data-act="reopen">${ic('undo')}Reconsider</button></div>`;
    }
    body = `<div class="ahr-timeoff__body" id="ahr-timeoff-b-${r.id}">
      ${r.note ? `<p class="ahr-timeoff__note"><q>${esc(r.note)}</q><small>Requested ${esc(r.at)} · ${n} workday${n === 1 ? '' : 's'}${r.from !== r.to ? ' · ' + fmtRange(r.from, r.to) : ''}</small></p>` : ''}
      ${balHTML}${acts}</div>`;
  }
  return `<li data-key="${r.id}"><article class="ahr-timeoff__card${sel ? ' is-sel' : ''}${S.newId === r.id ? ' is-new' : ''}" style="--t:${TYPES[r.type].t};--i:${i}">
    <button type="button" class="ahr-timeoff__cardmain" data-sel="${r.id}" aria-expanded="${sel}">
      ${av(r.who)}<span><b>${esc(PP[r.who].name)}${r.who === ME ? ' (you)' : ''}</b><small>${fmtRange(r.from, r.to)} · ${n} day${n === 1 ? '' : 's'}</small></span>${typeChip(r.type)}${flag}
    </button>${body}</article></li>`;
}
function renderQueue() {
  const counts = { pending: 0, approved: 0, declined: 0 };
  R.forEach((r) => counts[r.status]++);
  $('.ahr-timeoff__tabs').innerHTML = [['pending', 'Pending'], ['approved', 'Approved'], ['declined', 'Declined']]
    .map(([k, l]) => `<button type="button" role="tab" data-tab="${k}" aria-selected="${S.tab === k}">${l}<span>${counts[k] || (k === 'pending' ? '' : 0)}</span></button>`).join('');
  const list = R.filter((r) => r.status === S.tab).sort((a, b) => (a.from < b.from ? -1 : 1));
  const ul = $('.ahr-timeoff__list');
  flip(ul, 'li[data-key]', () => {
    ul.innerHTML = list.length ? list.map(cardHTML).join('')
      : `<li class="ahr-timeoff__empty">${ic(S.tab === 'pending' ? 'sun' : 'inbox')}<b>${S.tab === 'pending' ? 'Inbox zero' : 'Nothing here yet'}</b><span>${S.tab === 'pending' ? 'Every request is decided. New ones land here.' : 'Decided requests show up here.'}</span></li>`;
  });
