}

/* ---------------- render: calendar ---------------- */
function renderLegend() {
  $('.ahr-timeoff__legend').innerHTML = Object.entries(TYPES).map(([k, t]) => `<button type="button" data-type="${k}" aria-pressed="${!S.hidden.has(k)}" style="--t:${t.t}"><i></i>${t.name}</button>`).join('') +
    `<span class="ahr-timeoff__key"><i class="ahr-timeoff__k-pend"></i>Pending</span><span class="ahr-timeoff__key"><i class="ahr-timeoff__k-hol"></i>Holiday</span>`;
}
let prevCov = new Map();
function renderGrid(dir) {
  const days = monthDays(), grid = $('.ahr-timeoff__grid');
  grid.style.setProperty('--days', days.length);
  grid.style.setProperty('--rows', N);
  const col = (s) => days.indexOf(s) + 2;
  const sel = byId(S.sel);
  const showSel = sel && sel.status !== 'declined' && sel.to >= days[0] && sel.from <= days[days.length - 1];
  let h = '';
  // column overlays
  days.forEach((s, i) => {
    if (HOL[s]) h += `<div class="ahr-timeoff__col is-hol" style="grid-column:${i + 2}" title="${esc(HOL[s])}"></div>`;
    else if (!isWork(s)) h += `<div class="ahr-timeoff__col is-wkd" style="grid-column:${i + 2}"></div>`;
  });
  if (showSel) {
    const a = Math.max(2, col(sel.from < days[0] ? days[0] : sel.from)), b = col(sel.to > days[days.length - 1] ? days[days.length - 1] : sel.to) + 1;
    h += `<div class="ahr-timeoff__col is-sel" style="grid-column:${a} / ${b}"></div>`;
  }
  if (days.includes(TODAY)) h += `<div class="ahr-timeoff__col is-now" style="grid-column:${col(TODAY)}"></div>`;
  // day header
  h += `<div class="ahr-timeoff__row ahr-timeoff__dh" style="grid-row:1"><div class="ahr-timeoff__corner">Team · ${N}</div>${days.map((s, i) => {
    const inSel = showSel && covers(sel, s);
    return `<span class="${!isWork(s) ? 'is-off' : ''}${s === TODAY ? ' is-today' : ''}${inSel && s !== TODAY ? ' is-in' : ''}" style="grid-column:${i + 2}" title="${s}${HOL[s] ? ' · ' + esc(HOL[s]) : ''}">${DOW1[dow(s)]}<b>${dt(s).getUTCDate()}</b></span>`;
  }).join('')}</div>`;
  // people
  PEOPLE.forEach((p, pi) => {
    const left = balance(p.id).left;
    let cells = '';
    if (p.id === ME) cells = days.map((s, i) => `<div class="ahr-timeoff__cell" data-day="${s}" style="grid-column:${i + 2}"></div>`).join('');
    const bars = R.filter((r) => r.who === p.id && r.status !== 'declined' && r.to >= days[0] && r.from <= days[days.length - 1]).map((r) => {
      const a = r.from < days[0] ? days[0] : r.from, b = r.to > days[days.length - 1] ? days[days.length - 1] : r.to;
      const n = workdays(r.from, r.to), span = col(b) - col(a) + 1;
      const label = span >= 4 ? `<span>${TYPES[r.type].name}${span >= 7 ? ' · ' + n + 'd' : ''}</span>` : span >= 2 ? `<span>${n}d</span>` : '';
      const cls = ['ahr-timeoff__bar', span === 1 ? 'is-tiny' : '', r.id === S.sel ? 'is-sel' : '', r.from < days[0] ? 'is-clip-s' : '', r.to > days[days.length - 1] ? 'is-clip-e' : '', S.fresh === r.id ? 'is-fresh' : '', S.hidden.has(r.type) ? 'is-hidden' : ''].filter(Boolean).join(' ');
