    h += `<div class="ahr-timeoff__row${p.id === ME ? ' is-me' : ''}" style="grid-row:${pi + 2}" data-who="${p.id}">
      <div class="ahr-timeoff__who" title="${esc(p.name)} · ${esc(p.role)} · ${left} PTO days left">${av(p.id)}<span><b>${esc(first(p.id))}</b><small>${esc(p.role)}</small></span><em>${left}d</em></div>${cells}${bars}${draft}</div>`;
  });
