    if (!isWork(s)) return `<div class="ahr-timeoff__cov" data-state="off" style="grid-column:${i + 2}"><i></i><b>–</b></div>`;
    const now = N - outOn(s).size, proj = projected ? N - outOn(s, projected).size : now;
    const state = proj < S.min ? (now < S.min ? 'low' : 'risk') : now < S.min ? 'low' : 'ok';
    return `<div class="ahr-timeoff__cov" data-day="${s}" data-state="${state}" style="grid-column:${i + 2}" title="${fmtRange(s, s)}: ${now} of ${N} on duty${proj !== now ? ', ' + proj + ' if approved' : ''} (minimum ${S.min})"><i style="--a:${now / N};--p:${proj / N};--m:${S.min / N}"><s></s>${proj !== now ? '<u></u>' : ''}</i><b>${proj !== now ? proj : now}</b></div>`;
  }).join('')}</div>`;
  grid.innerHTML = h;
  // coverage bars tween from their previous height (they are new nodes after innerHTML)
  if (!RM.matches) {
    $$('.ahr-timeoff__cov[data-day]', grid).forEach((c) => {
      const a = parseFloat(c.querySelector('i').style.getPropertyValue('--a')), was = prevCov.get(c.dataset.day);
      if (was != null && Math.abs(was - a) > 0.001) c.querySelector('s').animate([{ transform: `scaleY(${was})` }, { transform: `scaleY(${a})` }], { duration: 520, easing: SPRING });
    });
  }
  prevCov = new Map($$('.ahr-timeoff__cov[data-day]', grid).map((c) => [c.dataset.day, parseFloat(c.querySelector('i').style.getPropertyValue('--a'))]));
  if (dir && !RM.matches) { grid.classList.remove('is-slide-l', 'is-slide-r'); void grid.offsetWidth; grid.classList.add(dir < 0 ? 'is-slide-l' : 'is-slide-r'); }
  S.fresh = null;
}

/* ---------------- composer ---------------- */
const form = $('.ahr-timeoff__composer');
function openComposer(from, to) {
  S.composing = true;
  S.draft = { from, to, type: (S.draft && S.draft.type) || 'vacation', note: '' };
  form.hidden = false;
  form.innerHTML = `<header><h3>Request time off</h3><button type="button" data-act="cancel" aria-label="Close">${ic('x')}</button></header>
    <fieldset><legend>Type</legend><div class="ahr-timeoff__types">${['vacation', 'personal', 'sick', 'training'].map((k) => `<label style="--t:${TYPES[k].t}"><input type="radio" name="ahr-timeoff-type" value="${k}" ${S.draft.type === k ? 'checked' : ''}><i></i>${TYPES[k].name}</label>`).join('')}</div></fieldset>
    <div class="ahr-timeoff__dates"><label>First day<input type="date" name="from" min="2026-10-01" max="2026-12-31" value="${from}"></label><label>Last day<input type="date" name="to" min="2026-10-01" max="2026-12-31" value="${to}"></label></div>
    <textarea name="note" placeholder="Note for ${APPROVER} (optional)" aria-label="Note"></textarea>
    <div class="ahr-timeoff__sum" aria-live="polite"></div>
    <footer><button type="button" class="is-ghost" data-act="cancel">Cancel <kbd>Esc</kbd></button><button type="submit">Send request</button></footer>`;
  renderSummary();
  render();
  const fd = form.querySelector('input:checked');
  if (fd) fd.focus({ preventScroll: true });
}
function draftErrors() {
  const d = S.draft, errs = [];
  if (!d.from || !d.to) errs.push('Pick both dates.');
  else if (d.to < d.from) errs.push('The last day is before the first day.');
  else if (workdays(d.from, d.to) === 0) errs.push('That range has no working days.');
  else if (TYPES[d.type].pto && workdays(d.from, d.to) > balance(ME).left) errs.push(`Only ${balance(ME).left} PTO days left.`);
  return errs;
}
function renderSummary() {
  const d = S.draft, n = d.from && d.to && d.to >= d.from ? workdays(d.from, d.to) : 0, b = balance(ME), errs = draftErrors();
  form.querySelector('.ahr-timeoff__sum').innerHTML = `<b>${n}</b><span>workday${n === 1 ? '' : 's'} · ${d.from && d.to && d.to >= d.from ? fmtRange(d.from, d.to) : '—'}</span><span>${TYPES[d.type].pto ? `${b.left - n} of ${b.allow} PTO left after` : TYPES[d.type].name + ' doesn’t use PTO'}</span>${errs.length ? `<span class="is-err">${esc(errs[0])}</span>` : ''}`;
  form.querySelector('[name="from"]').setAttribute('aria-invalid', String(errs.length > 0 && !/PTO/.test(errs[0])));
  form.querySelector('[name="to"]').setAttribute('aria-invalid', String(errs.length > 0 && !/PTO/.test(errs[0])));
}
function closeComposer() { S.composing = false; S.draft = null; form.hidden = true; form.innerHTML = ''; render(); }
form.addEventListener('input', (e) => {
  if (!S.draft) return;
  const t = e.target;
  if (t.name === 'from' || t.name === 'to') { S.draft[t.name] = t.value; renderSummary(); renderGrid(); }
  if (t.name === 'note') S.draft.note = t.value;
});
form.addEventListener('click', (e) => {
  const r = e.target.closest('input[type="radio"]');
  if (r && S.draft) { S.draft.type = r.value; renderSummary(); }
});
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const errs = draftErrors();
  if (errs.length) { renderSummary(); form.querySelector('.is-err') && form.querySelector('.is-err').animate([{ translate: '-4px 0' }, { translate: '4px 0' }, { translate: '0 0' }], { duration: 220 }); return; }
  undo.push(snapshot());
  const d = S.draft, id = 'r' + seq++;
  R.push({ id, who: ME, type: d.type, from: d.from, to: d.to, status: 'pending', note: d.note.trim(), at: 'Oct 2' });
  S.tab = 'pending'; S.sel = id; S.newId = id;
  const n = workdays(d.from, d.to);
  form.hidden = true; form.innerHTML = ''; S.composing = false; S.draft = null;
  goMonthOf(d.from);
  render();
  toast(`Sent ${n} day${n === 1 ? '' : 's'} of ${TYPES[d.type].name.toLowerCase()} to ${APPROVER}`, true);
});

/* drag across your own row to draft */
let drag = null;
const gridEl = $('.ahr-timeoff__grid');
function dayAt(row, x) {
  const cells = $$('.ahr-timeoff__cell', row);
  if (!cells.length) return null;
  const a = cells[0].getBoundingClientRect(), w = a.width;
  const i = Math.max(0, Math.min(cells.length - 1, Math.floor((x - a.left) / w)));
  return cells[i].dataset.day;
}
gridEl.addEventListener('pointerdown', (e) => {
  const cell = e.target.closest('.ahr-timeoff__cell');
  if (!cell || e.button !== 0) return;
  e.preventDefault();
  drag = { row: cell.closest('.ahr-timeoff__row'), start: cell.dataset.day, id: e.pointerId };
  S.draft = { from: drag.start, to: drag.start, type: (S.draft && S.draft.type) || 'vacation', note: '' };
  try { gridEl.setPointerCapture(e.pointerId); } catch (_) { /* pointer gone */ }
  renderGrid();
});
gridEl.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const d = dayAt($('.ahr-timeoff__row.is-me'), e.clientX);
  if (!d) return;
  const from = d < drag.start ? d : drag.start, to = d < drag.start ? drag.start : d;
  if (from !== S.draft.from || to !== S.draft.to) { S.draft.from = from; S.draft.to = to; renderGrid(); }
});
gridEl.addEventListener('pointerup', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  drag = null;
  openComposer(S.draft.from, S.draft.to);
});

/* ---------------- actions ---------------- */
let toastT = 0;
function toast(msg, canUndo) {
  const el = $('.ahr-timeoff__toast');
  el.innerHTML = `<span>${esc(msg)}</span>${canUndo ? `<button type="button" data-act="undo">${ic('undo')}Undo <kbd>Z</kbd></button>` : ''}`;
  clearTimeout(toastT);
  toastT = setTimeout(() => { el.innerHTML = ''; }, 5200);
}
function goMonthOf(s) { const d = dt(s); const m = d.getUTCMonth(); const dir = m - S.m; S.m = m; S.y = d.getUTCFullYear(); return dir; }
function selectReq(id, fromGrid) {
  const r = byId(id); if (!r) return;
  S.sel = id; S.confirm = null; S.declining = null;
  if (fromGrid && r.status !== S.tab) S.tab = r.status;
  if (fromGrid && root.clientWidth < 760) S.view = 'queue';
  const days = monthDays();
  const dir = r.to >= days[0] && r.from <= days[days.length - 1] ? 0 : goMonthOf(r.from);
  render(dir);
  const card = $(`.ahr-timeoff__list [data-key="${id}"]`);
  if (card) card.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
  const bar = $(`.ahr-timeoff__bar[data-sel="${id}"]`);
  if (bar && !fromGrid) bar.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
}
function decide(status, reason) {
  const r = byId(S.sel);
  if (!r || r.status !== 'pending' || r.who === ME) return;
  undo.push(snapshot());
  r.status = status; if (reason) r.reason = reason;
  const list = R.filter((x) => x.status === 'pending' && x.id !== r.id).sort((a, b) => (a.from < b.from ? -1 : 1));
  S.confirm = null; S.declining = null;
  if (status === 'approved') S.fresh = r.id;
  const keepSel = r.id;
  S.sel = list.length ? list[0].id : keepSel;
  render();
  const n = workdays(r.from, r.to);
