}
function doUndo() {
  if (!undo.length) { toast('Nothing to undo'); return; }
  R = undo.pop(); S.confirm = null; S.declining = null;
  if (!byId(S.sel)) S.sel = R[0].id;
  render();
  toast('Undone');
}
function render(dir) { renderHead(); renderQueue(); renderLegend(); renderGrid(dir); }

root.addEventListener('click', (e) => {
  const t = e.target;
  if (t.closest('.ahr-timeoff__composer') && !t.closest('[data-act]')) return;
  const selB = t.closest('[data-sel]');
  if (selB) { selectReq(selB.dataset.sel, !!selB.closest('.ahr-timeoff__grid')); return; }
  const tab = t.closest('[data-tab]');
  if (tab) {
    S.tab = tab.dataset.tab; S.confirm = null; S.declining = null;
    const first1 = R.filter((r) => r.status === S.tab).sort((a, b) => (a.from < b.from ? -1 : 1))[0];
    if (first1) S.sel = first1.id;
    render(); return;
  }
  const view = t.closest('[data-view]');
  if (view && view.closest('.ahr-timeoff__views')) { S.view = view.dataset.view; render(); return; }
  const type = t.closest('[data-type]');
  if (type) { const k = type.dataset.type; if (S.hidden.has(k)) S.hidden.delete(k); else S.hidden.add(k); render(); return; }
  const reason = t.closest('[data-reason]');
