  switch (act.dataset.act) {
    case 'prev': S.m = Math.max(8, S.m - 1); render(-1); break;
    case 'next': S.m = Math.min(11, S.m + 1); render(1); break;
    case 'today': {
      const dir = goMonthOf(TODAY); render(dir || 0);
      const now = $('.ahr-timeoff__col.is-now');
      if (now) { now.classList.add('is-flash'); const sc = $('.ahr-timeoff__scroll'); sc.scrollTo({ left: 0, behavior: RM.matches ? 'auto' : 'smooth' }); }
      break;
    }
    case 'min-': S.min = Math.max(3, S.min - 1); S.confirm = null; render(); break;
    case 'min+': S.min = Math.min(7, S.min + 1); S.confirm = null; render(); break;
    case 'new': openComposer('2026-10-19', '2026-10-23'); break;
    case 'cancel': closeComposer(); break;
    case 'approve': approve(); break;
    case 'decline': S.declining = S.sel; S.confirm = null; renderQueue(); { const b = $('.ahr-timeoff__reasons button'); if (b) b.focus(); } break;
    case 'nodecline': S.declining = null; renderQueue(); break;
    case 'withdraw': {
      const r = byId(S.sel); if (!r) break;
      undo.push(snapshot()); R = R.filter((x) => x.id !== r.id);
      S.sel = (R.find((x) => x.status === 'pending') || R[0]).id; render();
      toast('Withdrew your request', true); break;
    }
    case 'reopen': {
      const r = byId(S.sel); if (!r) break;
      undo.push(snapshot()); r.status = 'pending'; delete r.reason; S.tab = 'pending'; render();
