  }
});

root.addEventListener('keydown', (e) => {
  if (e.target.closest('input, textarea')) { if (e.key === 'Escape' && S.composing) { e.preventDefault(); closeComposer(); } return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  const list = R.filter((r) => r.status === S.tab).sort((a, b) => (a.from < b.from ? -1 : 1));
  const i = list.findIndex((r) => r.id === S.sel);
  if (k === 'j' || k === 'k') {
    e.preventDefault();
    const nx = list[Math.max(0, Math.min(list.length - 1, i + (k === 'j' ? 1 : -1)))];
    if (nx) { selectReq(nx.id); const b = $(`.ahr-timeoff__cardmain[data-sel="${nx.id}"]`); if (b) b.focus({ preventScroll: true }); }
  } else if (k === 'a') { e.preventDefault(); approve(); }
  else if (k === 'd') { const r = byId(S.sel); if (r && r.status === 'pending' && r.who !== ME) { e.preventDefault(); S.declining = r.id; renderQueue(); const b = $('.ahr-timeoff__reasons button'); if (b) b.focus(); } }
  else if (k === 'z') { e.preventDefault(); doUndo(); }
  else if (k === 'n') { e.preventDefault(); openComposer('2026-10-19', '2026-10-23'); }
  else if (k === 't') { e.preventDefault(); const dir = goMonthOf(TODAY); render(dir || 0); }
  else if (e.key === 'ArrowLeft' && !e.target.closest('.ahr-timeoff__scroll')) { if (S.m > 8) { e.preventDefault(); S.m--; render(-1); } }
  else if (e.key === 'ArrowRight' && !e.target.closest('.ahr-timeoff__scroll')) { if (S.m < 11) { e.preventDefault(); S.m++; render(1); } }
  else if (e.key === 'Escape') {
    if (S.composing) { closeComposer(); } else if (S.declining) { S.declining = null; renderQueue(); } else if (S.confirm) { S.confirm = null; renderQueue(); }
  }
});

render();

