/* Payroll run review. Re-theme with --ahr-payroll-bg, -ink, -accent, -up and -down. */
@property --ahr-payroll-p { syntax: "<integer>"; inherits: true; initial-value: 0; }
@property --ahr-payroll-ring { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.ahr-payroll {
  --ahr-payroll-bg: oklch(0.19 0.008 75);
  --ahr-payroll-ink: oklch(0.94 0.012 85);
  --ahr-payroll-accent: oklch(0.8 0.14 76);
  --ahr-payroll-up: oklch(0.79 0.12 155);
  --ahr-payroll-down: oklch(0.72 0.15 28);

  --ahr-payroll-panel: color-mix(in oklch, var(--ahr-payroll-ink) 4.5%, var(--ahr-payroll-bg));
  --ahr-payroll-raise: color-mix(in oklch, var(--ahr-payroll-ink) 8%, var(--ahr-payroll-bg));
  --ahr-payroll-muted: color-mix(in oklch, var(--ahr-payroll-ink) 62%, var(--ahr-payroll-bg));
  --ahr-payroll-faint: color-mix(in oklch, var(--ahr-payroll-ink) 40%, var(--ahr-payroll-bg));
  --ahr-payroll-rule: color-mix(in oklch, var(--ahr-payroll-ink) 9%, transparent);
  --ahr-payroll-rule2: color-mix(in oklch, var(--ahr-payroll-ink) 15%, transparent);
  --ahr-payroll-hover: color-mix(in oklch, var(--ahr-payroll-ink) 5%, transparent);
  --ahr-payroll-glow: color-mix(in oklch, var(--ahr-payroll-accent) 14%, transparent);
  --ahr-payroll-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-payroll-spring: linear(0, 0.1 5%, 0.37 12%, 0.77 21%, 0.99 29%, 1.05 36%, 1.05 44%, 1.02 54%, 1 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-payroll-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-payroll-bg);
  color: var(--ahr-payroll-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--ahr-payroll-accent);
  outline: none;
}
:where(.ahr-payroll) *, :where(.ahr-payroll) *::before, :where(.ahr-payroll) *::after { box-sizing: border-box; }
:where(.ahr-payroll) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.ahr-payroll) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-payroll) button:disabled, :where(.ahr-payroll) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.ahr-payroll) :is(p, h2, h3, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
:where(.ahr-payroll) :is(ol, ul) { list-style: none; }
:where(.ahr-payroll) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-payroll) :focus-visible { outline: 2px solid var(--ahr-payroll-accent); outline-offset: 2px; }
:where(.ahr-payroll) kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-payroll-muted);
  background: var(--ahr-payroll-raise); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule2);
}
.ahr-payroll__num { font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.ahr-payroll__up { color: var(--ahr-payroll-up); }
.ahr-payroll__down { color: var(--ahr-payroll-down); }

.ahr-payroll__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head" "kpis" "body";
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-columns: minmax(0, 1fr);
}

/* ---------- header ---------- */
.ahr-payroll__head { grid-area: head; display: flex; align-items: center; gap: 16px; padding: 14px 18px 12px; }
.ahr-payroll__title {
  display: flex; align-items: center; gap: 12px; min-width: 0; margin-right: auto;
  & h2 { font-size: clamp(15px, 1.5cqi, 17px); font-weight: 700; letter-spacing: -0.015em; text-wrap: balance; }
  & p { font-size: 11.5px; color: var(--ahr-payroll-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-payroll__logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: var(--ahr-payroll-bg); background: var(--ahr-payroll-accent); flex: none; & svg { stroke-width: 2.1; } }
.ahr-payroll__steps {
  display: flex; align-items: center; gap: 4px; font-size: 11.5px; font-weight: 600; color: var(--ahr-payroll-faint);
  & li { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
  & li + li::before { content: ""; width: 18px; height: 1.5px; margin-right: 2px; border-radius: 1px; background: var(--ahr-payroll-rule2); }
  & i { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-rule2); font-style: normal; font-size: 9.5px; }
  & i svg { width: 11px; height: 11px; stroke-width: 2.6; }
  & li[data-s="done"] { color: var(--ahr-payroll-muted); }
  & li[data-s="done"] i { color: var(--ahr-payroll-bg); background: var(--ahr-payroll-up); box-shadow: none; }
  & li[data-s="done"] + li::before { background: var(--ahr-payroll-up); }
  & li[data-s="now"] { color: var(--ahr-payroll-ink); }
  & li[data-s="now"] i { box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-accent); background: var(--ahr-payroll-glow); animation: ahr-payroll-pulse 2.2s ease-in-out infinite; }
}
.ahr-payroll__cta { display: flex; align-items: center; gap: 8px; }
.ahr-payroll__btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; padding: 0 13px; border-radius: 9px;
  font-size: 12.5px; font-weight: 650; white-space: nowrap; box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule2);
  transition: background-color .15s, box-shadow .15s, color .15s, translate .2s var(--ahr-payroll-ease);
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled):not([aria-disabled="true"]) { background: var(--ahr-payroll-hover); }
  &.is-primary { color: var(--ahr-payroll-bg); background: var(--ahr-payroll-accent); box-shadow: 0 8px 20px -10px var(--ahr-payroll-accent); }
  &.is-primary:hover:not(:disabled):not([aria-disabled="true"]) { background: color-mix(in oklch, var(--ahr-payroll-accent) 88%, white); translate: 0 -1px; }
  &.is-primary[aria-disabled="true"] { color: var(--ahr-payroll-muted); background: var(--ahr-payroll-raise); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule2); }
  &:disabled { opacity: .45; }
}
.ahr-payroll__progress {
  position: relative; display: grid; gap: 5px; width: 210px; font-size: 11.5px; color: var(--ahr-payroll-muted);
  & b { color: var(--ahr-payroll-ink); font-weight: 650; }
  & span { display: flex; justify-content: space-between; }
  & span em { font-style: normal; font-variant-numeric: tabular-nums; counter-reset: ahr-payroll-p var(--ahr-payroll-p); }
  & span em::after { content: counter(ahr-payroll-p) "%"; }
  & i { height: 6px; border-radius: 3px; background: var(--ahr-payroll-raise); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: calc(var(--ahr-payroll-p) * 1%); border-radius: inherit; background: linear-gradient(90deg, color-mix(in oklch, var(--ahr-payroll-accent) 60%, var(--ahr-payroll-bg)), var(--ahr-payroll-accent)); }
  --ahr-payroll-p: 100;
  transition: --ahr-payroll-p 1.7s cubic-bezier(.45, .05, .25, 1);
  @starting-style { --ahr-payroll-p: 0; }
}
.ahr-payroll__done { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--ahr-payroll-muted); white-space: nowrap;
  & b { color: var(--ahr-payroll-up); font-weight: 650; }
  & code { font: 600 11px ui-monospace, Menlo, monospace; color: var(--ahr-payroll-ink); }
  & svg { color: var(--ahr-payroll-up); }
}

/* ---------- KPI strip ---------- */
.ahr-payroll__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)) minmax(0, 1.5fr); gap: 1px; margin: 0 18px;
  border-radius: 14px; overflow: hidden; background: var(--ahr-payroll-rule); box-shadow: 0 0 0 1px var(--ahr-payroll-rule);
}
.ahr-payroll__kpi {
  position: relative; display: grid; align-content: start; gap: 2px; padding: 12px 14px; background: var(--ahr-payroll-panel);
  & > span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); }
  & > b { font-size: clamp(17px, 1.9cqi, 22px); font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  & > b sup { font-size: .55em; font-weight: 600; color: var(--ahr-payroll-muted); vertical-align: .55em; margin-left: 1px; }
  & > small { font-size: 11.5px; color: var(--ahr-payroll-muted); font-variant-numeric: tabular-nums; }
}
.ahr-payroll__ring {
  position: absolute; right: 14px; top: 14px; width: 40px; height: 40px; border-radius: 50%;
  background: conic-gradient(var(--ahr-payroll-up) var(--ahr-payroll-ring), var(--ahr-payroll-raise) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4.5px)); mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4.5px));
  transition: --ahr-payroll-ring .8s var(--ahr-payroll-ease);
  @starting-style { --ahr-payroll-ring: 0%; }
}
.ahr-payroll__depts {
  padding: 10px 12px; display: grid; gap: 3px; background: var(--ahr-payroll-panel);
  & > span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); margin: 0 2px 2px; }
  & button {
    display: grid; grid-template-columns: 70px 1fr 64px; align-items: center; gap: 8px; height: 19px; padding: 0 2px; border-radius: 5px; font-size: 11.5px; text-align: left;
    transition: background-color .15s, opacity .2s;
  }
  & button:hover { background: var(--ahr-payroll-hover); }
  & button[aria-pressed="true"] { background: var(--ahr-payroll-glow); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-payroll-accent) 40%, transparent); }
  &:has(button[aria-pressed="true"]) button[aria-pressed="false"] { opacity: .5; }
  & button > em { font-style: normal; text-align: right; font-variant-numeric: tabular-nums; font-size: 11px; }
  & .ahr-payroll__track { position: relative; height: 9px; }
  & .ahr-payroll__track::before { content: ""; position: absolute; left: 50%; top: -2px; bottom: -2px; width: 1px; background: var(--ahr-payroll-rule2); }
  & .ahr-payroll__track i { position: absolute; top: 0; bottom: 0; border-radius: 2px; transform-origin: var(--o) 50%; animation: ahr-payroll-grow .7s var(--ahr-payroll-ease) calc(var(--i) * 70ms) both; }
}

/* ---------- body ---------- */
.ahr-payroll__body { grid-area: body; display: grid; grid-template-columns: minmax(0, 1fr) clamp(300px, 31cqi, 360px); min-height: 0; padding-top: 12px; }
.ahr-payroll__tablewrap { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; container: ahr-payroll-t / inline-size; }
.ahr-payroll__toolbar { display: flex; align-items: center; gap: 10px; padding: 0 18px 10px; flex-wrap: wrap; }
.ahr-payroll__filter, .ahr-payroll__thresh {
  display: inline-flex; padding: 3px; border-radius: 9px; background: var(--ahr-payroll-panel); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule);
  & button { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--ahr-payroll-muted); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--ahr-payroll-ink); }
  & button[aria-selected="true"], & button[aria-checked="true"] { color: var(--ahr-payroll-ink); background: var(--ahr-payroll-raise); box-shadow: 0 1px 2px rgb(0 0 0 / .3), inset 0 0 0 1px var(--ahr-payroll-rule2); }
  & button span { font-size: 10.5px; font-variant-numeric: tabular-nums; color: var(--ahr-payroll-faint); }
}
.ahr-payroll__thresh { align-items: center; & > em { font-style: normal; font-size: 11px; color: var(--ahr-payroll-faint); padding: 0 6px 0 7px; white-space: nowrap; } & button { padding: 0 8px; font-variant-numeric: tabular-nums; } }
.ahr-payroll__find {
  display: flex; align-items: center; gap: 7px; height: 32px; margin-left: auto; padding: 0 10px; border-radius: 9px; min-width: 0; flex: 0 1 200px;
  background: var(--ahr-payroll-panel); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule);
  & svg { width: 15px; height: 15px; color: var(--ahr-payroll-faint); }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px; }
  & input::placeholder { color: var(--ahr-payroll-faint); }
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-accent); }
}
.ahr-payroll__scroll { overflow: auto; overscroll-behavior: contain; padding: 0 18px; scrollbar-width: thin; scrollbar-color: var(--ahr-payroll-rule2) transparent; }
.ahr-payroll__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 2; height: 34px; padding: 0 10px; text-align: right; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ahr-payroll-faint); background: var(--ahr-payroll-bg); border-bottom: 1px solid var(--ahr-payroll-rule2); white-space: nowrap; }
  & th:first-child, & td:first-child { text-align: left; padding-left: 4px; }
  & th button { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 4px; margin: 0 -4px; border-radius: 5px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & th button:hover { color: var(--ahr-payroll-ink); background: var(--ahr-payroll-hover); }
  & th button svg { width: 11px; height: 11px; stroke-width: 2.4; opacity: 0; transition: rotate .3s var(--ahr-payroll-spring), opacity .2s; }
  & th[aria-sort] button { color: var(--ahr-payroll-ink); }
  & th[aria-sort] button svg { opacity: 1; }
  & th[aria-sort="ascending"] button svg { rotate: 180deg; }
  & td { height: 46px; padding: 0 10px; text-align: right; border-bottom: 1px solid var(--ahr-payroll-rule); white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: var(--ahr-payroll-hover); }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--ahr-payroll-accent) 9%, transparent); }
  & tbody tr[aria-selected="true"] td:first-child { box-shadow: inset 2px 0 0 var(--ahr-payroll-accent); }
  & tfoot td { height: 40px; font-weight: 700; border-top: 1px solid var(--ahr-payroll-rule2); border-bottom: 0; position: sticky; bottom: 0; background: var(--ahr-payroll-bg); }
  & tfoot td:first-child { font-size: 10.5px; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); }
}
@supports (animation-timeline: view()) {
  .ahr-payroll__table tbody tr { animation: ahr-payroll-row linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}
.ahr-payroll__who {
  display: grid; grid-template-columns: 30px minmax(0, 1fr); align-items: center; gap: 10px; width: 100%; text-align: left; padding: 4px 0;
  & b { display: block; font-weight: 620; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11px; color: var(--ahr-payroll-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-payroll__av { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; font-size: 10.5px; font-weight: 700; color: oklch(0.86 0.06 var(--h)); background: oklch(0.32 0.04 var(--h)); }
.ahr-payroll__dept { font-size: 11.5px; color: var(--ahr-payroll-muted); text-align: left !important; }
.ahr-payroll__hrs { font-size: 12px; color: var(--ahr-payroll-muted); & em { font-style: normal; color: var(--ahr-payroll-accent); } }
.ahr-payroll__pct {
  display: inline-flex; align-items: center; justify-content: flex-end; min-width: 58px; height: 22px; padding: 0 7px; border-radius: 6px; font-size: 12px; font-weight: 650;
  &.is-flag { color: var(--ahr-payroll-bg); background: var(--ahr-payroll-accent); }
  &.is-flag.is-down { background: var(--ahr-payroll-down); }
}
.ahr-payroll__state {
  display: inline-grid; place-items: center; width: 24px; height: 24px; border-radius: 7px;
  & svg { width: 15px; height: 15px; }
  &.is-todo { color: var(--ahr-payroll-accent); background: var(--ahr-payroll-glow); }
  &.is-ok { color: var(--ahr-payroll-up); }
  &.is-clear { color: var(--ahr-payroll-faint); }
}
.ahr-payroll__empty td { height: 120px; text-align: center !important; color: var(--ahr-payroll-muted); white-space: normal; }
.ahr-payroll__keys { display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 8px 18px 12px; font-size: 11px; color: var(--ahr-payroll-faint); & span { display: inline-flex; align-items: center; gap: 3px; } }

/* ---------- detail ---------- */
.ahr-payroll__detail { min-height: 0; overflow: auto; overscroll-behavior: contain; margin: 0 18px 16px 0; border-radius: 14px; background: var(--ahr-payroll-panel); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule); scrollbar-width: thin; scrollbar-color: var(--ahr-payroll-rule2) transparent; }
.ahr-payroll__dv { display: grid; gap: 16px; padding: 16px; animation: ahr-payroll-in .4s var(--ahr-payroll-ease) both; }
.ahr-payroll__dhead {
  display: grid; grid-template-columns: auto 40px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  & .ahr-payroll__av { width: 40px; height: 40px; font-size: 13px; border-radius: 11px; grid-column: 2; }
  & h3 { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
  & p { font-size: 11.5px; color: var(--ahr-payroll-muted); }
  & nav { display: flex; gap: 2px; }
  & nav button, & .ahr-payroll__back { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; color: var(--ahr-payroll-muted); }
  & nav button:hover:not(:disabled), & .ahr-payroll__back:hover { background: var(--ahr-payroll-hover); color: var(--ahr-payroll-ink); }
  & nav button:disabled { opacity: .35; }
  & .ahr-payroll__back { display: none; grid-column: 1; }
}
.ahr-payroll__dhead > div { grid-column: 3; min-width: 0; }
.ahr-payroll__dhead > nav { grid-column: 4; }
.ahr-payroll__why {
  display: grid; grid-template-columns: auto 1fr; gap: 2px 10px; align-items: center; padding: 11px 12px; border-radius: 11px;
  background: var(--ahr-payroll-raise); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule);
  & b { grid-row: span 2; font-size: 22px; font-weight: 750; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; font-weight: 600; }
  & small { font-size: 11.5px; color: var(--ahr-payroll-muted); text-wrap: pretty; }
  &.is-flag { background: color-mix(in oklch, var(--ahr-payroll-accent) 10%, var(--ahr-payroll-panel)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-payroll-accent) 35%, transparent); }
}
.ahr-payroll__wf {
  & figcaption { display: flex; justify-content: space-between; font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); margin-bottom: 6px; }
  & svg { display: block; width: 100%; height: auto; overflow: visible; stroke: none; }
  & rect { shape-rendering: crispEdges; transform-box: fill-box; transform-origin: 50% 100%; animation: ahr-payroll-bar .6s var(--ahr-payroll-spring) calc(var(--i) * 60ms) both; }
  & .is-total { fill: color-mix(in oklch, var(--ahr-payroll-ink) 35%, var(--ahr-payroll-bg)); }
  & .is-total.is-end { fill: var(--ahr-payroll-ink); }
  & .is-pos { fill: var(--ahr-payroll-up); }
  & .is-neg { fill: var(--ahr-payroll-down); }
  & line { stroke: var(--ahr-payroll-rule2); stroke-dasharray: 2 3; }
  & text { fill: var(--ahr-payroll-muted); font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums; }
  & text.is-v { fill: var(--ahr-payroll-ink); font-size: 10px; }
}
.ahr-payroll__lines {
  width: 100%; border-collapse: collapse; font-size: 12px; font-variant-numeric: tabular-nums;
  & th { font-size: 10px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); text-align: right; padding: 0 0 6px; }
  & th:first-child, & td:first-child { text-align: left; }
  & td { padding: 5px 0; text-align: right; border-top: 1px solid var(--ahr-payroll-rule); }
  & td:first-child { color: var(--ahr-payroll-muted); }
  & tr.is-sum td { font-weight: 700; color: var(--ahr-payroll-ink); border-top: 1px solid var(--ahr-payroll-rule2); }
}
.ahr-payroll__net {
  display: grid; gap: 7px;
  & header { display: flex; justify-content: space-between; align-items: baseline; font-size: 11.5px; color: var(--ahr-payroll-muted); }
  & header b { font-size: 16px; color: var(--ahr-payroll-ink); font-variant-numeric: tabular-nums; }
  & .ahr-payroll__stack { display: flex; height: 10px; gap: 2px; border-radius: 4px; overflow: hidden; }
  & .ahr-payroll__stack i { flex: var(--n) 0 0; background: var(--c); transform-origin: 0 50%; animation: ahr-payroll-grow .6s var(--ahr-payroll-ease) calc(var(--i) * 50ms) both; }
  & ul { display: grid; grid-template-columns: 1fr 1fr; gap: 3px 12px; font-size: 11px; color: var(--ahr-payroll-muted); font-variant-numeric: tabular-nums; }
  & li { display: flex; align-items: center; gap: 6px; }
  & li i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
  & li b { margin-left: auto; color: var(--ahr-payroll-ink); font-weight: 600; }
}
.ahr-payroll__review {
  display: grid; gap: 8px;
  & label { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-payroll-faint); }
  & textarea { width: 100%; min-height: 58px; resize: vertical; border: 0; border-radius: 9px; padding: 9px 10px; font-size: 12.5px; background: var(--ahr-payroll-bg); box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule2); }
  & textarea:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-accent); }
  & .ahr-payroll__btn { width: 100%; }
  & .ahr-payroll__btn[aria-pressed="true"] { color: var(--ahr-payroll-bg); background: var(--ahr-payroll-up); box-shadow: none; }
  & .ahr-payroll__btn[aria-pressed="true"] svg { animation: ahr-payroll-tick .45s var(--ahr-payroll-spring) both; }
}

/* ---------- toast ---------- */
.ahr-payroll__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 10px; max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px; border-radius: 11px; font-size: 12.5px; font-weight: 550; color: var(--ahr-payroll-bg); background: var(--ahr-payroll-ink);
  box-shadow: 0 18px 40px -16px rgb(0 0 0 / .7);
  transition: opacity .2s var(--ahr-payroll-ease), transform .35s var(--ahr-payroll-spring);
  @starting-style { opacity: 0; transform: translateY(10px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(10px); }
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font-weight: 700; color: color-mix(in oklch, var(--ahr-payroll-accent) 55%, black); }
  & button:hover { background: color-mix(in oklch, var(--ahr-payroll-bg) 10%, transparent); }
}

@keyframes ahr-payroll-pulse { 0%, 100% { box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-accent), 0 0 0 0 var(--ahr-payroll-glow); } 50% { box-shadow: inset 0 0 0 1.5px var(--ahr-payroll-accent), 0 0 0 5px var(--ahr-payroll-glow); } }
@keyframes ahr-payroll-grow { from { transform: scaleX(0); } }
@keyframes ahr-payroll-bar { from { transform: scaleY(0); } }
@keyframes ahr-payroll-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-payroll-row { from { opacity: 0; } }
@keyframes ahr-payroll-tick { from { scale: .2; rotate: -40deg; } }

/* ---------- table columns by table width ---------- */
@container ahr-payroll-t (max-width: 760px) { .ahr-payroll__table .ahr-payroll__c-dept { display: none; } }
@container ahr-payroll-t (max-width: 640px) { .ahr-payroll__table .ahr-payroll__c-hrs, .ahr-payroll__table .ahr-payroll__c-prev { display: none; } .ahr-payroll__keys { display: none; } }
@container ahr-payroll-t (max-width: 470px) { .ahr-payroll__table .ahr-payroll__c-delta { display: none; } .ahr-payroll__find { flex-basis: 100%; margin-left: 0; } }

/* ---------- container: medium — detail becomes a drawer ---------- */
@container (max-width: 1099px) {
  .ahr-payroll__steps li:not([data-s="now"]) span { display: none; }
  .ahr-payroll__kpis { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .ahr-payroll__depts { display: none; }
  .ahr-payroll__body { grid-template-columns: minmax(0, 1fr); }
  .ahr-payroll__detail {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 10px; width: min(360px, calc(100% - 20px)); margin: 0;
    background: color-mix(in oklch, var(--ahr-payroll-ink) 6%, var(--ahr-payroll-bg));
    box-shadow: inset 0 0 0 1px var(--ahr-payroll-rule2), 0 30px 70px -20px rgb(0 0 0 / .8);
    transform: translateX(calc(100% + 20px)); visibility: hidden;
    transition: transform .45s var(--ahr-payroll-spring), visibility 0s .45s;
  }
  .ahr-payroll[data-pane="detail"] .ahr-payroll__detail { transform: none; visibility: visible; transition: transform .45s var(--ahr-payroll-spring), visibility 0s; }
  .ahr-payroll__dhead .ahr-payroll__back { display: grid; }
}
@container (max-width: 759px) {
  .ahr-payroll__head { flex-wrap: wrap; gap: 10px; padding: 12px 12px 10px; }
  .ahr-payroll__title { flex: 1 1 100%; }
  .ahr-payroll__steps { flex: 1 1 auto; }
  .ahr-payroll__steps li + li::before { width: 8px; }
  .ahr-payroll__kpis { margin: 0 12px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ahr-payroll__kpi:nth-child(n+3) { display: none; }
  .ahr-payroll__toolbar, .ahr-payroll__scroll { padding-left: 12px; padding-right: 12px; }
  .ahr-payroll__detail { inset: 0; width: auto; border-radius: 0; }
  .ahr-payroll__progress { width: 150px; }
}
@container (max-width: 440px) {
  .ahr-payroll__title p { white-space: normal; }
  .ahr-payroll__thresh > em { display: none; }
  .ahr-payroll__steps li[data-s="now"] span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-payroll *, .ahr-payroll *::before, .ahr-payroll *::after { animation: none !important; transition-duration: .01s !important; }
  .ahr-payroll .ahr-payroll__progress { transition: none; }
}
.ahr-payroll__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

