// Payroll run review. Every figure on screen is derived from the per-employee earnings
// lines below, so the KPIs, department bars, register, footer and waterfall always tie out.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.37 12%, 0.77 21%, 0.99 29%, 1.05 36%, 1.05 44%, 1.02 54%, 1 68%, 1)';

const ICON = {
  flag: '<path d="M5 21V4"/><path d="M5 4h11l-2 4 2 4H5"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  dot: '<circle cx="12" cy="12" r="3"/>',
  sort: '<path d="m6 9 6 6 6-6"/>',
  left: '<path d="m15 18-6-6 6-6"/>',
  up: '<path d="m18 15-6-6-6 6"/>',
  down: '<path d="m6 9 6 6 6-6"/>',
  lock: '<rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/>',
  send: '<path d="M4 12 20 4l-5 16-3.5-6.5z"/><path d="m11.5 13.5 3-3"/>',
  undo: '<path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>',
  bank: '<path d="M3 10 12 4l9 6"/><path d="M5 10v8M9.5 10v8M14.5 10v8M19 10v8M3 20h18"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

const LINES = { base: ['Base pay', 'Base'], ot: ['Overtime', 'OT'], diff: ['Night differential', 'Night'], perdiem: ['Per diem', 'Per diem'], comm: ['Commission', 'Comm.'], bonus: ['Bonus', 'Bonus'], payout: ['PTO payout', 'Payout'] };
const DEPT = { office: { name: 'Office', h: 75 }, dispatch: { name: 'Dispatch', h: 215 }, drivers: { name: 'Drivers', h: 150 }, warehouse: { name: 'Warehouse', h: 35 } };
const STATE_TAX = 0.044, FICA = 0.0765, MATCH_CAP = 0.04;
// hrs: [regular, overtime] for September and October. Overtime is paid at 1.5x the hourly rate.
const E = [
  { id: 'delia', name: 'Delia Okonkwo', title: 'Operations Manager', dept: 'office', pay: 'S', fed: 0.16, k: 0.06, health: 412, prev: { base: 7916.67 }, cur: { base: 7916.67 } },
  { id: 'marcus', name: 'Marcus Feld', title: 'Dispatcher', dept: 'dispatch', pay: 'H', rate: 28, hrs: [[168, 6], [176, 22]], fed: 0.11, k: 0.04, health: 242, prev: { base: 4704, ot: 252 }, cur: { base: 4928, ot: 924 } },
  { id: 'rosa', name: 'Rosa Imbert', title: 'Warehouse Lead', dept: 'warehouse', pay: 'H', rate: 26, hrs: [[168, 4], [176, 8]], fed: 0.10, k: 0.05, health: 242, prev: { base: 4368, ot: 156 }, cur: { base: 4576, ot: 312 } },
  { id: 'tomasz', name: 'Tomasz Kraus', title: 'Driver, CDL-A', dept: 'drivers', pay: 'H', rate: 31, hrs: [[168, 10], [176, 12]], fed: 0.12, k: 0.03, health: 412, prev: { base: 5208, ot: 465, perdiem: 340 }, cur: { base: 5456, ot: 558, perdiem: 380 } },
  { id: 'imani', name: 'Imani Price', title: 'Driver, CDL-A', dept: 'drivers', pay: 'H', rate: 31, hrs: [[168, 12], [96, 0]], fed: 0.12, k: 0.04, health: 242, prev: { base: 5208, ot: 558, perdiem: 340 }, cur: { base: 2976, perdiem: 200 }, event: 'Unpaid leave Oct 19–30, approved by Delia Okonkwo' },
  { id: 'owen', name: 'Owen Castellano', title: 'Driver, CDL-B', dept: 'drivers', pay: 'H', rate: 29, hrs: [[168, 8], [176, 6]], fed: 0.11, k: 0, health: 186, prev: { base: 4872, ot: 348, perdiem: 300 }, cur: { base: 5104, ot: 261, perdiem: 320 } },
  { id: 'priyanka', name: 'Priyanka Rao', title: 'Account Manager', dept: 'office', pay: 'S', fed: 0.14, k: 0.06, health: 242, prev: { base: 6250, comm: 1180 }, cur: { base: 6250, comm: 2960 }, event: 'Q3 renewals closed: Cascade Cold Storage, Pinemoor Farms' },
  { id: 'gus', name: 'Gus Halvorsen', title: 'Forklift Operator', dept: 'warehouse', pay: 'H', rate: 23, hrs: [[168, 3], [176, 5]], fed: 0.09, k: 0.03, health: 186, prev: { base: 3864, ot: 103.5 }, cur: { base: 4048, ot: 172.5 } },
  { id: 'lena', name: 'Lena Vasquez', title: 'Warehouse Associate', dept: 'warehouse', pay: 'H', rate: 21, hrs: [[168, 0], [176, 0]], fed: 0.08, k: 0, health: 186, prev: { base: 3528 }, cur: { base: 3696, diff: 264 }, event: 'Moved to night shift Oct 1 (+$1.50/h on 176 h)' },
  { id: 'bram', name: 'Bram de Vries', title: 'Fleet Mechanic', dept: 'drivers', pay: 'H', rate: 30, hrs: [[168, 9], [176, 6]], fed: 0.12, k: 0.05, health: 412, prev: { base: 5040, ot: 405 }, cur: { base: 5280, ot: 270 } },
  { id: 'hana', name: 'Hana Sato', title: 'HR & Payroll Specialist', dept: 'office', pay: 'S', fed: 0.12, k: 0.05, health: 242, prev: { base: 5416.67 }, cur: { base: 5416.67 } },
  { id: 'felipe', name: 'Felipe Ortega', title: 'Controller', dept: 'office', pay: 'S', fed: 0.18, k: 0.06, health: 412, prev: { base: 8750 }, cur: { base: 8750, bonus: 2625 }, event: 'Q3 bonus at 30% of monthly salary' },
  { id: 'wendell', name: 'Wendell Banks', title: 'Warehouse Associate', dept: 'warehouse', pay: 'H', rate: 21, hrs: [[168, 0], [88, 0]], fed: 0.08, k: 0.03, health: 186, prev: { base: 3528 }, cur: { base: 1848, payout: 840 }, event: 'Final pay — last day Thu, Oct 15; 40 h PTO paid out', kind: 'term' },
  { id: 'aaliyah', name: 'Aaliyah Grant', title: 'Warehouse Associate', dept: 'warehouse', pay: 'H', rate: 21, hrs: [null, [120, 0]], fed: 0.08, k: 0, health: 0, prev: null, cur: { base: 2520 }, event: 'New hire — started Mon, Oct 12 (15 workdays)', kind: 'new' },
  { id: 'nikolai', name: 'Nikolai Petrov', title: 'Dispatcher', dept: 'dispatch', pay: 'H', rate: 28, hrs: [[168, 4], [176, 5]], fed: 0.11, k: 0.04, health: 186, prev: { base: 4704, ot: 168 }, cur: { base: 4928, ot: 210 } },
  { id: 'chiara', name: 'Chiara Bellini', title: 'Customer Service Rep', dept: 'dispatch', pay: 'H', rate: 22, hrs: [[168, 0], [176, 0]], fed: 0.09, k: 0.03, health: 186, prev: { base: 3696 }, cur: { base: 3872 } },
];
const r2 = (n) => Math.round(n * 100) / 100;
const sum = (o) => (o ? r2(Object.values(o).reduce((a, b) => a + b, 0)) : 0);
function calc(e, which) {
  const lines = which === 'prev' ? e.prev : e.cur;
  if (!lines) return null;
  const gross = sum(lines);
  const fed = r2(gross * e.fed), state = r2(gross * STATE_TAX), fica = r2(gross * FICA), k401 = r2(gross * e.k), health = e.health;
  const net = r2(gross - fed - state - fica - k401 - health);
  const erTax = r2(gross * FICA), match = r2(gross * Math.min(e.k, MATCH_CAP));
  return { gross, fed, state, fica, k401, health, net, erTax, match, cost: r2(gross + erTax + match) };
}
E.forEach((e) => { e.P = calc(e, 'prev'); e.C = calc(e, 'cur'); e.delta = r2(e.C.gross - (e.P ? e.P.gross : 0)); e.pct = e.P ? e.delta / e.P.gross : Infinity; });
const byId = Object.fromEntries(E.map((e) => [e.id, e]));

const S = {
  thresh: 0.10, filter: 'all', q: '', dept: null,
  sort: 'pct', dir: -1,
  sel: 'imani',
  reviewed: new Map([['felipe', 'Bonus approved by Delia — memo of Sep 28.'], ['aaliyah', 'Offer letter and I-9 on file; rate matches.'], ['wendell', 'Final pay checked against state timing rules.']]),
  notes: new Map(),
  run: 'review',
  pane: 'list',
};

const money = (n, cents = true) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: cents ? 2 : 0, maximumFractionDigits: cents ? 2 : 0 });
const signed = (n, cents = true) => (n > 0 ? '+' : n < 0 ? '−' : '±') + money(Math.abs(n), cents);
const pctTxt = (p) => (p === Infinity ? 'New' : (p > 0 ? '+' : p < 0 ? '−' : '±') + Math.abs(p * 100).toFixed(1) + '%');
const flagged = (e) => e.kind === 'new' || e.kind === 'term' || Math.abs(e.pct) >= S.thresh - 1e-9;
const ini = (e) => e.name.split(' ').map((w) => w[0]).slice(0, 2).join('');
const av = (e) => `<span class="ahr-payroll__av" style="--h:${DEPT[e.dept].h}" aria-hidden="true">${esc(ini(e))}</span>`;
const pendingFlags = () => E.filter((e) => flagged(e) && !S.reviewed.has(e.id));
function reason(e) {
  if (e.event) return e.event;
  const keys = new Set([...Object.keys(e.prev || {}), ...Object.keys(e.cur)]);
  let best = null;
  keys.forEach((k) => { const d = (e.cur[k] || 0) - ((e.prev && e.prev[k]) || 0); if (!best || Math.abs(d) > Math.abs(best.d)) best = { k, d }; });
  if (!best || Math.abs(best.d) < 0.005) return 'No change from September';
  let s = `${LINES[best.k][0]} ${signed(best.d, false)}`;
  if (best.k === 'ot' && e.hrs && e.hrs[0]) s += ` (${e.hrs[1][1]} h vs ${e.hrs[0][1]} h)`;
  if (best.k === 'base' && e.pay === 'H') s += ' — 22 workdays in October vs 21 in September';
  return s;
}

/* ---------------- totals ---------------- */
function totals(list) {
  const t = { prev: 0, cur: 0, net: 0, pnet: 0, cost: 0, pcost: 0, er: 0 };
  list.forEach((e) => { t.prev += e.P ? e.P.gross : 0; t.cur += e.C.gross; t.net += e.C.net; t.pnet += e.P ? e.P.net : 0; t.cost += e.C.cost; t.pcost += e.P ? e.P.cost : 0; t.er += e.C.erTax + e.C.match; });
  Object.keys(t).forEach((k) => { t[k] = r2(t[k]); });
  return t;
}

/* ---------------- render: header ---------------- */
function renderHead() {
  const steps = [['Draft', 'done'], ['Review', S.run === 'review' ? 'now' : 'done'], ['Approve', S.run === 'approving' ? 'now' : S.run === 'submitted' ? 'done' : ''], ['Submit', S.run === 'submitted' ? 'done' : '']];
  $('.ahr-payroll__steps').innerHTML = steps.map(([l, s], i) => `<li data-s="${s}"${s === 'now' ? ' aria-current="step"' : ''}><i>${s === 'done' ? ic('check') : i + 1}</i><span>${l}</span></li>`).join('');
  const left = pendingFlags().length, cta = $('.ahr-payroll__cta');
  if (S.run === 'review') {
    cta.innerHTML = `<button type="button" class="ahr-payroll__btn is-primary" data-act="approve" ${left ? `aria-disabled="true" title="${left} flagged ${left === 1 ? 'employee needs' : 'employees need'} review before the run can be approved"` : ''}>${ic(left ? 'lock' : 'send')}${left ? `${left} flag${left === 1 ? '' : 's'} to review` : 'Approve &amp; submit'}</button>`;
  } else if (S.run === 'approving') {
    cta.innerHTML = `<div class="ahr-payroll__progress" role="progressbar" aria-label="Submitting ACH file"><span><b>Sending ACH file</b><em></em></span><i></i></div>`;
  } else {
    cta.innerHTML = `<span class="ahr-payroll__done">${ic('bank')}<span><b>Submitted</b> · ACH <code>TGL-20261030</code></span></span><button type="button" class="ahr-payroll__btn" data-act="reopen">${ic('undo')}Reopen run</button>`;
  }
  root.dataset.run = S.run;
}

/* ---------------- render: KPIs ---------------- */
function renderKpis() {
  const t = totals(E), flags = E.filter(flagged), done = flags.filter((e) => S.reviewed.has(e.id)).length;
  const dg = r2(t.cur - t.prev), dn = r2(t.net - t.pnet), dc = r2(t.cost - t.pcost);
  const cents = (n) => { const s = money(n); return `${s.slice(0, -3)}<sup>${s.slice(-3)}</sup>`; };
  const deltaTxt = (d, base) => `<small><span class="${d >= 0 ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${signed(d, false)} (${pctTxt(d / base)})</span> vs Sep</small>`;
  const dd = Object.keys(DEPT).map((k) => { const l = E.filter((e) => e.dept === k); return { k, d: r2(l.reduce((a, e) => a + e.delta, 0)), n: l.length }; });
  const max = Math.max(...dd.map((x) => Math.abs(x.d)));
  $('.ahr-payroll__kpis').innerHTML = `
    <div class="ahr-payroll__kpi"><span>Gross pay</span><b>${cents(t.cur)}</b>${deltaTxt(dg, t.prev)}</div>
    <div class="ahr-payroll__kpi"><span>Net pay</span><b>${cents(t.net)}</b>${deltaTxt(dn, t.pnet)}</div>
    <div class="ahr-payroll__kpi"><span>Total cost</span><b>${cents(t.cost)}</b><small>incl. ${money(t.er, false)} employer tax &amp; 401(k)</small></div>
    <div class="ahr-payroll__kpi"><span>Review</span><b>${done}<sup>/${flags.length}</sup></b><small>flags at ≥${Math.round(S.thresh * 100)}% · ${E.length} people</small><i class="ahr-payroll__ring" style="--ahr-payroll-ring:${flags.length ? (done / flags.length) * 100 : 100}%" aria-hidden="true"></i></div>
    <div class="ahr-payroll__depts" role="group" aria-label="Change in gross by department — filter"><span>Δ gross by department</span>${dd.map((x, i) => {
      const w = (Math.abs(x.d) / max) * 50, pos = x.d >= 0;
      return `<button type="button" data-dept="${x.k}" aria-pressed="${S.dept === x.k}" aria-label="${DEPT[x.k].name}: ${signed(x.d, false)} across ${x.n} people"><span>${DEPT[x.k].name}</span><span class="ahr-payroll__track"><i style="${pos ? 'left:50%' : 'right:50%'};width:${w}%;background:var(--ahr-payroll-${pos ? 'up' : 'down'});--o:${pos ? '0%' : '100%'};--i:${i}"></i></span><em class="${pos ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${signed(x.d, false)}</em></button>`;
    }).join('')}</div>`;
}

/* ---------------- render: toolbar ---------------- */
function renderToolbar() {
  const flags = E.filter(flagged), un = pendingFlags();
  $('.ahr-payroll__filter').innerHTML = [['all', 'Everyone', E.length], ['flagged', 'Flagged', flags.length], ['open', 'To review', un.length]]
    .map(([k, l, n]) => `<button type="button" role="tab" data-filter="${k}" aria-selected="${S.filter === k}">${l}<span>${n}</span></button>`).join('');
  $('.ahr-payroll__thresh').innerHTML = `<em>Flag over</em>` + [0.05, 0.1, 0.15, 0.25].map((t) => `<button type="button" role="radio" data-thresh="${t}" aria-checked="${Math.abs(S.thresh - t) < 1e-9}">${Math.round(t * 100)}%</button>`).join('');
}

/* ---------------- render: table ---------------- */
function rows() {
  const q = S.q.trim().toLowerCase();
  let list = E.filter((e) => (S.filter === 'all' || (S.filter === 'flagged' ? flagged(e) : flagged(e) && !S.reviewed.has(e.id))) && (!S.dept || e.dept === S.dept) && (!q || e.name.toLowerCase().includes(q) || e.title.toLowerCase().includes(q)));
  const key = { name: (e) => e.name, prev: (e) => (e.P ? e.P.gross : -1), cur: (e) => e.C.gross, delta: (e) => e.delta, pct: (e) => Math.abs(e.pct) }[S.sort];
  list.sort((a, b) => { const x = key(a), y = key(b); return (x < y ? -1 : x > y ? 1 : 0) * S.dir || a.name.localeCompare(b.name); });
  return list;
}
const COLS = [['name', 'Employee', ''], ['dept', 'Dept', 'ahr-payroll__c-dept'], ['hrs', 'Hours', 'ahr-payroll__c-hrs'], ['prev', 'Sep gross', 'ahr-payroll__c-prev'], ['cur', 'Oct gross', ''], ['delta', 'Change', 'ahr-payroll__c-delta'], ['pct', 'Δ %', ''], ['st', '<span class="ahr-payroll__sr">Status</span>', '']];
const SORTABLE = new Set(['name', 'prev', 'cur', 'delta', 'pct']);
function renderTable() {
  const list = rows(), tb = $('.ahr-payroll__table tbody');
  $('.ahr-payroll__table thead tr').innerHTML = COLS.map(([k, l, c]) => {
    const sorted = S.sort === k;
    const inner = SORTABLE.has(k) ? `<button type="button" data-sort="${k}">${l}${ic('sort')}</button>` : l;
    return `<th scope="col" class="${c}"${sorted ? ` aria-sort="${S.dir > 0 ? 'ascending' : 'descending'}"` : ''}>${inner}</th>`;
  }).join('');
  const before = new Map($$('tr[data-key]', tb).map((tr) => [tr.dataset.key, tr.getBoundingClientRect().top]));
  tb.innerHTML = list.length ? list.map((e) => {
    const f = flagged(e), rv = S.reviewed.has(e.id);
    const hrs = e.pay === 'S' ? 'Salary' : `${e.hrs[1][0]} h${e.hrs[1][1] ? ` <em>+${e.hrs[1][1]} OT</em>` : ''}`;
    const st = f ? (rv ? `<span class="ahr-payroll__state is-ok" title="Reviewed">${ic('check')}</span>` : `<span class="ahr-payroll__state is-todo" title="Needs review">${ic('flag')}</span>`) : `<span class="ahr-payroll__state is-clear" title="Within threshold">${ic('dot')}</span>`;
    return `<tr data-key="${e.id}" aria-selected="${S.sel === e.id}">
      <td><button type="button" class="ahr-payroll__who" data-row="${e.id}">${av(e)}<span><b>${esc(e.name)}</b><small>${esc(e.title)}</small></span></button></td>
      <td class="ahr-payroll__dept ahr-payroll__c-dept">${DEPT[e.dept].name}</td>
      <td class="ahr-payroll__hrs ahr-payroll__c-hrs">${hrs}</td>
      <td class="ahr-payroll__c-prev">${e.P ? money(e.P.gross) : '—'}</td>
      <td><b>${money(e.C.gross)}</b></td>
      <td class="ahr-payroll__c-delta ${e.delta >= 0 ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${signed(e.delta)}</td>
      <td><span class="ahr-payroll__pct${f ? ' is-flag' : ''}${e.delta < 0 ? ' is-down' : ''}${!f ? (e.delta >= 0 ? ' ahr-payroll__up' : ' ahr-payroll__down') : ''}">${pctTxt(e.pct)}</span></td>
      <td>${st}</td></tr>`;
  }).join('') : `<tr class="ahr-payroll__empty"><td colspan="8">Nobody matches these filters. <button type="button" class="ahr-payroll__btn" data-act="clear" style="margin-left:8px">Clear filters</button></td></tr>`;
  if (!RM.matches) {
    $$('tr[data-key]', tb).forEach((tr) => {
      const b = before.get(tr.dataset.key); if (b == null) return;
      const dy = b - tr.getBoundingClientRect().top;
      if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 480, easing: SPRING });
    });
  }
  const t = totals(list), filtered = list.length !== E.length;
  $('.ahr-payroll__table tfoot').innerHTML = `<tr><td>${filtered ? `${list.length} of ${E.length} shown` : `Total · ${E.length} people`}</td><td class="ahr-payroll__c-dept"></td><td class="ahr-payroll__c-hrs"></td><td class="ahr-payroll__c-prev">${money(t.prev)}</td><td>${money(t.cur)}</td><td class="ahr-payroll__c-delta ${t.cur - t.prev >= 0 ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${signed(r2(t.cur - t.prev))}</td><td>${t.prev ? pctTxt((t.cur - t.prev) / t.prev) : ''}</td><td></td></tr>`;
}

/* ---------------- render: detail ---------------- */
function waterfall(e) {
  const keys = Object.keys(LINES).filter((k) => Math.abs((e.cur[k] || 0) - ((e.prev && e.prev[k]) || 0)) > 0.004);
  const steps = [{ l: 'Sep', v: e.P ? e.P.gross : 0, total: true }];
  let run = steps[0].v;
  keys.forEach((k) => { const d = (e.cur[k] || 0) - ((e.prev && e.prev[k]) || 0); steps.push({ l: LINES[k][1], from: run, to: run + d, d }); run += d; });
  steps.push({ l: 'Oct', v: e.C.gross, total: true, end: true });
  const W = 320, H = 150, top = 16, base = H - 22, n = steps.length, cw = W / n, bw = Math.min(34, cw * 0.62);
  const hi = Math.max(...steps.map((s) => (s.total ? s.v : Math.max(s.from, s.to)))) * 1.08 || 1;
  const y = (v) => base - (v / hi) * (base - top);
  const k = (v) => (Math.abs(v) >= 1000 ? (v / 1000).toFixed(Math.abs(v) >= 10000 ? 1 : 2).replace(/\.?0+$/, '') + 'k' : Math.round(v).toString());
  let g = `<line x1="0" x2="${W}" y1="${base}" y2="${base}"/>`;
  steps.forEach((s, i) => {
