      g += `<text class="is-v" x="${cx}" y="${y(s.v) - 5}" text-anchor="middle">${s.v ? '$' + k(s.v) : '$0'}</text>`;
    } else {
      const a = y(Math.max(s.from, s.to)), b = y(Math.min(s.from, s.to));
      g += `<rect class="${s.d >= 0 ? 'is-pos' : 'is-neg'}" x="${x}" y="${a}" width="${bw}" height="${Math.max(1.5, b - a)}" rx="2" style="--i:${i}"/>`;
      g += `<text class="is-v" x="${cx}" y="${a - 5}" text-anchor="middle">${s.d >= 0 ? '+' : '−'}${k(Math.abs(s.d))}</text>`;
      if (i < n - 1) g += `<line x1="${cx + bw / 2}" x2="${cx + cw - bw / 2}" y1="${y(s.to)}" y2="${y(s.to)}"/>`;
    }
    g += `<text x="${cx}" y="${H - 6}" text-anchor="middle">${s.l}</text>`;
  });
  return `<figure class="ahr-payroll__wf"><figcaption><span>Sep → Oct gross</span><span>${signed(e.delta, false)}</span></figcaption><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gross pay moved from ${money(e.P ? e.P.gross : 0)} to ${money(e.C.gross)}: ${steps.slice(1, -1).map((s) => s.l + ' ' + signed(s.d, false)).join(', ')}">${g}</svg></figure>`;
