function renderDetail() {
  const e = byId[S.sel], list = rows(), i = list.findIndex((x) => x.id === e.id);
  const f = flagged(e), rv = S.reviewed.has(e.id), locked = S.run !== 'review';
  const keys = Object.keys(LINES).filter((k) => (e.cur[k] || (e.prev && e.prev[k])));
  const c = e.C;
  const parts = [['Net pay', c.net, 'var(--ahr-payroll-up)'], ['Federal', c.fed, 'oklch(0.7 0.09 250)'], ['State', c.state, 'oklch(0.66 0.08 210)'], ['FICA', c.fica, 'oklch(0.62 0.07 280)'], ['401(k)', c.k401, 'var(--ahr-payroll-accent)'], ['Health', c.health, 'oklch(0.68 0.1 340)']].filter((p) => p[1] > 0);
  const note = S.reviewed.get(e.id) || S.notes.get(e.id) || '';
  let btn;
  if (!f) btn = `<button type="button" class="ahr-payroll__btn" disabled title="Change is within the ${Math.round(S.thresh * 100)}% threshold">${ic('check')}No review needed</button>`;
  else if (locked) btn = `<button type="button" class="ahr-payroll__btn" aria-pressed="${rv}" aria-disabled="true" title="The run is ${S.run === 'submitted' ? 'submitted' : 'being submitted'} — reopen it to change reviews">${ic(rv ? 'check' : 'lock')}${rv ? 'Reviewed' : 'Not reviewed'}</button>`;
  else btn = `<button type="button" class="ahr-payroll__btn" data-act="review" aria-pressed="${rv}">${ic('check')}${rv ? 'Reviewed — undo' : 'Mark reviewed'} <kbd>R</kbd></button>`;
