  if (panel.dataset.for !== e.id) { panel.scrollTop = 0; panel.dataset.for = e.id; }
  panel.innerHTML = `<div class="ahr-payroll__dv">
    <header class="ahr-payroll__dhead"><button type="button" class="ahr-payroll__back" data-act="back" aria-label="Back to the register">${ic('left')}</button>${av(e)}<div><h3>${esc(e.name)}</h3><p>${esc(e.title)} · ${DEPT[e.dept].name} · ${e.pay === 'S' ? 'Salaried' : '$' + e.rate.toFixed(2) + '/h'}</p></div>
      <nav aria-label="Step through employees"><button type="button" data-act="prev" aria-label="Previous employee" ${i <= 0 ? 'disabled title="This is the first row"' : ''}>${ic('up')}</button><button type="button" data-act="next" aria-label="Next employee" ${i < 0 || i >= list.length - 1 ? 'disabled title="This is the last row"' : ''}>${ic('down')}</button></nav></header>
    <div class="ahr-payroll__why${f && !rv ? ' is-flag' : ''}"><b class="${e.delta >= 0 ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${pctTxt(e.pct)}</b><span>${f ? (rv ? 'Flag reviewed' : e.kind === 'new' ? 'New hire — first pay' : e.kind === 'term' ? 'Final pay' : `Over the ${Math.round(S.thresh * 100)}% threshold`) : 'Within threshold'}</span><small>${esc(reason(e))}</small></div>
    ${waterfall(e)}
    <table class="ahr-payroll__lines"><thead><tr><th scope="col">Earnings</th><th scope="col">Sep</th><th scope="col">Oct</th><th scope="col">Change</th></tr></thead><tbody>
      ${keys.map((k) => { const a = (e.prev && e.prev[k]) || 0, b = e.cur[k] || 0; return `<tr><td>${LINES[k][0]}</td><td>${e.prev ? money(a) : '—'}</td><td>${money(b)}</td><td class="${b - a >= 0 ? 'ahr-payroll__up' : 'ahr-payroll__down'}">${signed(r2(b - a))}</td></tr>`; }).join('')}
      <tr class="is-sum"><td>Gross</td><td>${e.P ? money(e.P.gross) : '—'}</td><td>${money(c.gross)}</td><td>${signed(e.delta)}</td></tr></tbody></table>
    <div class="ahr-payroll__net"><header><span>October gross ${money(c.gross)} →</span><b>${money(c.net)} net</b></header>
      <div class="ahr-payroll__stack" role="img" aria-label="${parts.map((p) => p[0] + ' ' + money(p[1])).join(', ')}">${parts.map((p, j) => `<i style="--n:${p[1]};--c:${p[2]};--i:${j}"></i>`).join('')}</div>
