}
let runT = 0;
function approve() {
  if (S.run !== 'review' || pendingFlags().length) return;
  S.run = 'approving'; S.pane = 'list'; render();
  clearTimeout(runT);
  runT = setTimeout(() => { if (!root.isConnected) return; S.run = 'submitted'; render(); toast(`Submitted ${money(totals(E).net)} net pay for ${E.length} people`); }, RM.matches ? 300 : 1900);
}

root.addEventListener('click', (ev) => {
  const t = ev.target;
  const sortB = t.closest('[data-sort]');
  if (sortB) { const k = sortB.dataset.sort; if (S.sort === k) S.dir = -S.dir; else { S.sort = k; S.dir = k === 'name' ? 1 : -1; } render(); return; }
  const row = t.closest('[data-row]') || (t.closest('tbody tr[data-key]') && !t.closest('button') ? t.closest('tbody tr[data-key]') : null);
  if (row) { select(row.dataset.row || row.dataset.key, true); return; }
  const f = t.closest('[data-filter]');
  if (f) { S.filter = f.dataset.filter; render(); return; }
  const th = t.closest('[data-thresh]');
  if (th) { S.thresh = parseFloat(th.dataset.thresh); render(); return; }
  const d = t.closest('[data-dept]');
  if (d) { S.dept = S.dept === d.dataset.dept ? null : d.dataset.dept; render(); return; }
