/* Hiring pipeline. Re-theme with --ahr-hiring-paper, -ink, -accent (a highlighter) and -deep. */
.ahr-hiring {
  --ahr-hiring-paper: oklch(0.967 0.013 100);
  --ahr-hiring-ink: oklch(0.23 0.028 265);
  --ahr-hiring-accent: oklch(0.89 0.18 124);
  --ahr-hiring-deep: oklch(0.46 0.13 140);

  --ahr-hiring-card: oklch(0.995 0.004 100);
  --ahr-hiring-muted: color-mix(in oklch, var(--ahr-hiring-ink) 60%, var(--ahr-hiring-paper));
  --ahr-hiring-faint: color-mix(in oklch, var(--ahr-hiring-ink) 38%, var(--ahr-hiring-paper));
  --ahr-hiring-rule: color-mix(in oklch, var(--ahr-hiring-ink) 10%, transparent);
  --ahr-hiring-rule2: color-mix(in oklch, var(--ahr-hiring-ink) 17%, transparent);
  --ahr-hiring-hover: color-mix(in oklch, var(--ahr-hiring-ink) 5%, transparent);
  --ahr-hiring-well: color-mix(in oklch, var(--ahr-hiring-ink) 4%, var(--ahr-hiring-paper));
  --ahr-hiring-warn: oklch(0.7 0.14 70);
  --ahr-hiring-bad: oklch(0.58 0.18 28);
  --ahr-hiring-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-hiring-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-hiring-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-hiring-paper);
  color: var(--ahr-hiring-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--ahr-hiring-deep);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2);
}
:where(.ahr-hiring) *, :where(.ahr-hiring) *::before, :where(.ahr-hiring) *::after { box-sizing: border-box; }
:where(.ahr-hiring) :is(button, input, select) { font: inherit; color: inherit; }
:where(.ahr-hiring) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-hiring) button:disabled { cursor: not-allowed; opacity: .45; }
:where(.ahr-hiring) :is(p, h2, h3, ul, ol, dl, dd) { margin: 0; padding: 0; }
:where(.ahr-hiring) :is(ul, ol) { list-style: none; }
:where(.ahr-hiring) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-hiring) :focus-visible { outline: 2px solid var(--ahr-hiring-ink); outline-offset: 2px; }
:where(.ahr-hiring) kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-hiring-muted);
  background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2), 0 1px 0 var(--ahr-hiring-rule2);
}

.ahr-hiring__app { height: 100%; display: grid; grid-template-rows: auto auto auto minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }

/* ---------- header ---------- */
.ahr-hiring__head { display: flex; align-items: center; gap: 16px; padding: 14px 18px 10px; }
.ahr-hiring__brand {
  display: flex; align-items: center; gap: 10px; flex: none;
  & > svg { width: 32px; height: 32px; padding: 6px; border-radius: 10px; color: var(--ahr-hiring-ink); background: var(--ahr-hiring-accent); stroke-width: 2; }
  & b { display: block; font-size: 14px; font-weight: 750; letter-spacing: -0.015em; }
  & span { display: block; font-size: 11px; color: var(--ahr-hiring-muted); }
}
.ahr-hiring__roles {
  display: flex; gap: 4px; min-width: 0; overflow-x: auto; scrollbar-width: none; margin-right: auto;
  & button { display: inline-flex; align-items: center; gap: 7px; flex: none; height: 32px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 600; color: var(--ahr-hiring-muted); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-hover); }
  & button[aria-selected="true"] { color: var(--ahr-hiring-paper); background: var(--ahr-hiring-ink); }
  & button span { min-width: 20px; height: 18px; padding: 0 5px; display: inline-grid; place-items: center; border-radius: 6px; font-size: 10.5px; font-variant-numeric: tabular-nums; background: var(--ahr-hiring-hover); }
  & button[aria-selected="true"] span { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-accent); }
}
.ahr-hiring__find {
  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 8px 0 10px; border-radius: 10px; flex: 0 1 230px; min-width: 0;
  background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2);
  & svg { width: 15px; height: 15px; color: var(--ahr-hiring-faint); }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px; }
  & input::placeholder { color: var(--ahr-hiring-faint); }
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
  &:has(input:not(:placeholder-shown)) kbd { visibility: hidden; }
}

/* ---------- funnel ---------- */
.ahr-hiring__funnel { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; padding: 0 18px 10px; }
.ahr-hiring__step {
  position: relative; display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 0 8px; padding: 9px 11px 10px; border-radius: 11px; text-align: left;
  background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule);
  transition: box-shadow .2s, translate .25s var(--ahr-hiring-ease);
  & span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-hiring-faint); }
  & b { grid-row: 2; font-size: 20px; font-weight: 750; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  & em { grid-row: 2; font-style: normal; font-size: 11px; font-weight: 650; color: var(--ahr-hiring-deep); font-variant-numeric: tabular-nums; text-align: right; }
  & i { grid-column: 1 / -1; height: 5px; margin-top: 7px; border-radius: 3px; background: var(--ahr-hiring-well); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); border-radius: inherit; background: linear-gradient(90deg, var(--ahr-hiring-deep), var(--ahr-hiring-accent)); transition: width .6s var(--ahr-hiring-spring); }
  &:hover { box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); translate: 0 -1px; }
  &.is-hot { box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
}
.ahr-hiring__step + .ahr-hiring__step::before { content: ""; position: absolute; left: -6px; top: 50%; width: 6px; height: 1px; background: var(--ahr-hiring-rule2); }

/* ---------- filter bar ---------- */
.ahr-hiring__bar { display: flex; align-items: center; gap: 10px; padding: 0 18px 10px; }
.ahr-hiring__sources {
  display: flex; gap: 5px; min-width: 0; overflow-x: auto; scrollbar-width: none;
  & button { display: inline-flex; align-items: center; gap: 6px; flex: none; height: 26px; padding: 0 10px 0 8px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--ahr-hiring-muted); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); transition: background-color .15s, color .15s; }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.65 0.12 var(--s)); }
  & button:hover { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-hover); }
  & button[aria-pressed="true"] { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
}
.ahr-hiring__keys { display: flex; gap: 12px; margin-left: auto; font-size: 11px; color: var(--ahr-hiring-faint); white-space: nowrap; & span { display: inline-flex; align-items: center; gap: 3px; } }
.ahr-hiring__rej { height: 30px; padding: 0 11px; border-radius: 9px; font-size: 12px; font-weight: 600; color: var(--ahr-hiring-muted); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); white-space: nowrap;
  &:hover { background: var(--ahr-hiring-hover); }
  &[aria-pressed="true"] { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-well); box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
}
.ahr-hiring__add {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 12px 0 9px; border-radius: 9px; font-size: 12px; font-weight: 700; white-space: nowrap;
  color: var(--ahr-hiring-ink); background: var(--ahr-hiring-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-hiring-deep) 35%, transparent);
  transition: translate .2s var(--ahr-hiring-ease), box-shadow .2s;
  & svg { width: 15px; height: 15px; stroke-width: 2.3; }
  &:hover { translate: 0 -1px; box-shadow: inset 0 0 0 1px var(--ahr-hiring-deep), 0 8px 16px -10px var(--ahr-hiring-deep); }
}

/* ---------- board ---------- */
.ahr-hiring__board {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(208px, 1fr); gap: 10px; min-height: 0;
  padding: 0 18px 16px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity;
  scrollbar-width: thin; scrollbar-color: var(--ahr-hiring-rule2) transparent;
}
.ahr-hiring__col {
  display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; border-radius: 14px; background: var(--ahr-hiring-well); scroll-snap-align: start;
  box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule);
  transition: box-shadow .2s, background-color .2s;
  &.is-over { background: color-mix(in oklch, var(--ahr-hiring-accent) 22%, var(--ahr-hiring-well)); box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-deep); }
  &.is-flash { animation: ahr-hiring-flash .9s var(--ahr-hiring-ease); }
  &[data-stage="rejected"] { background: color-mix(in oklch, var(--ahr-hiring-ink) 7%, var(--ahr-hiring-paper)); }
  &[data-stage="rejected"] .ahr-hiring__card { opacity: .78; }
}
.ahr-hiring__colhead {
  display: flex; align-items: center; gap: 7px; padding: 10px 12px 8px;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 22%, transparent); }
  & h3 { font-size: 12px; font-weight: 700; letter-spacing: .02em; }
  & span { font-size: 11.5px; font-weight: 650; color: var(--ahr-hiring-faint); font-variant-numeric: tabular-nums; }
  & small { margin-left: auto; font-size: 10.5px; color: var(--ahr-hiring-faint); }
}
.ahr-hiring__list {
  display: flex; flex-direction: column; gap: 8px; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 2px 8px 12px;
  scrollbar-width: none;
  & > li { flex: none; }
}
.ahr-hiring__empty { display: grid; place-items: center; min-height: 72px; border-radius: 10px; border: 1.5px dashed var(--ahr-hiring-rule2); font-size: 11.5px; color: var(--ahr-hiring-faint); text-align: center; padding: 10px; }
.ahr-hiring__card {
  position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 2px 9px; width: 100%; padding: 10px 11px 10px 10px; border-radius: 11px; text-align: left;
  background: var(--ahr-hiring-card); box-shadow: 0 0 0 1px var(--ahr-hiring-rule), 0 1px 2px var(--ahr-hiring-rule);
  touch-action: none; user-select: none;
  transition: box-shadow .2s var(--ahr-hiring-ease), translate .2s var(--ahr-hiring-ease);
  &:hover { translate: 0 -1px; box-shadow: 0 0 0 1px var(--ahr-hiring-rule2), 0 10px 18px -12px color-mix(in oklch, var(--ahr-hiring-ink) 45%, transparent); }
  &:focus-visible { outline: 2px solid var(--ahr-hiring-ink); outline-offset: 2px; }
  &.is-open { box-shadow: 0 0 0 2px var(--ahr-hiring-ink); }
  &.is-new { animation: ahr-hiring-pop .6s var(--ahr-hiring-spring) both; }
  &.is-lifted { background: transparent; box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-deep); outline: none; }
  &.is-lifted > * { visibility: hidden; }
  &.is-lifted::after { content: ""; position: absolute; inset: 4px; border-radius: 8px; background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--ahr-hiring-accent) 40%, transparent) 0 6px, transparent 6px 12px); }
  & b { display: block; font-size: 13px; font-weight: 650; letter-spacing: -0.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.5px; color: var(--ahr-hiring-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-hiring__ghost {
  position: absolute; z-index: 50; left: 0; top: 0; margin: 0; pointer-events: none; will-change: transform;
  box-shadow: 0 0 0 1px var(--ahr-hiring-rule2), 0 24px 40px -16px color-mix(in oklch, var(--ahr-hiring-ink) 55%, transparent) !important;
  transition: none;
}
.ahr-hiring__av { grid-row: span 2; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font-size: 10.5px; font-weight: 700; color: oklch(0.34 0.07 var(--h)); background: oklch(0.92 0.05 var(--h)); }
.ahr-hiring__meta { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 5px; margin-top: 7px; }
.ahr-hiring__chip { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 6px; font-size: 10.5px; font-weight: 650; color: var(--ahr-hiring-muted); background: var(--ahr-hiring-well);
  & i { width: 6px; height: 6px; border-radius: 50%; background: oklch(0.65 0.12 var(--s)); }
}
.ahr-hiring__age { margin-left: auto; font-size: 10.5px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--ahr-hiring-faint);
  &.is-warn { color: var(--ahr-hiring-warn); }
  &.is-bad { color: var(--ahr-hiring-bad); }
}
.ahr-hiring__score { display: inline-flex; gap: 2px; margin-right: 2px; & i { width: 4px; height: 10px; border-radius: 1px; background: var(--ahr-hiring-rule2); } & i.is-on { background: var(--ahr-hiring-deep); } & i.is-half { background: linear-gradient(to top, var(--ahr-hiring-deep) 50%, var(--ahr-hiring-rule2) 50%); } }
.ahr-hiring__next { grid-column: 1 / -1; display: flex; align-items: center; gap: 5px; margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--ahr-hiring-rule2); font-size: 11px; color: var(--ahr-hiring-muted);
  & svg { width: 12px; height: 12px; }
}
@supports (animation-timeline: view()) {
  .ahr-hiring__list > li { animation: ahr-hiring-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}
.ahr-hiring__form {
  display: grid; gap: 7px; padding: 10px; border-radius: 11px; background: var(--ahr-hiring-card); box-shadow: 0 0 0 1.5px var(--ahr-hiring-ink);
  animation: ahr-hiring-pop .45s var(--ahr-hiring-spring) both;
  & input, & select { width: 100%; height: 30px; border: 0; border-radius: 7px; padding: 0 9px; font-size: 12.5px; background: var(--ahr-hiring-well); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); }
  & :is(input, select):focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
  & [aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-bad); }
  & p { font-size: 11px; color: var(--ahr-hiring-bad); font-weight: 600; }
  & div { display: flex; gap: 6px; justify-content: flex-end; }
  & button { height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 650; }
  & button[type="submit"] { color: var(--ahr-hiring-paper); background: var(--ahr-hiring-ink); }
  & button.is-ghost { color: var(--ahr-hiring-muted); }
  & button.is-ghost:hover { background: var(--ahr-hiring-hover); }
}

/* ---------- drawer ---------- */
.ahr-hiring__drawer {
  position: absolute; z-index: 30; top: 10px; right: 10px; bottom: 10px; width: min(392px, calc(100% - 20px));
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto; border-radius: 16px; background: var(--ahr-hiring-card); overflow: hidden;
  box-shadow: 0 0 0 1px var(--ahr-hiring-rule2), 0 30px 70px -24px color-mix(in oklch, var(--ahr-hiring-ink) 55%, transparent);
  transition: transform .45s var(--ahr-hiring-spring), opacity .25s var(--ahr-hiring-ease);
  @starting-style { transform: translateX(40px); opacity: 0; }
  &[hidden] { display: none; }
}
.ahr-hiring__dhead {
  display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; gap: 2px 12px; align-items: center; padding: 16px 16px 12px; border-bottom: 1px solid var(--ahr-hiring-rule);
  & .ahr-hiring__av { width: 44px; height: 44px; font-size: 14px; }
  & h3 { font-size: 16px; font-weight: 750; letter-spacing: -0.015em; }
  & p { font-size: 12px; color: var(--ahr-hiring-muted); }
  & > button { grid-row: span 2; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--ahr-hiring-muted); }
  & > button:hover { background: var(--ahr-hiring-hover); color: var(--ahr-hiring-ink); }
}
.ahr-hiring__dbody { overflow: auto; overscroll-behavior: contain; padding: 14px 16px 16px; display: grid; align-content: start; grid-auto-rows: max-content; gap: 16px; scrollbar-width: thin; scrollbar-color: var(--ahr-hiring-rule2) transparent; }
.ahr-hiring__h { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ahr-hiring-faint); margin-bottom: 7px; }
.ahr-hiring__stages {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 3px; padding: 3px; border-radius: 10px; background: var(--ahr-hiring-well);
  & button { height: 28px; border-radius: 7px; font-size: 11px; font-weight: 650; color: var(--ahr-hiring-muted); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--ahr-hiring-ink); }
  & button[aria-checked="true"] { color: var(--ahr-hiring-ink); background: var(--ahr-hiring-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-hiring-deep) 40%, transparent); }
  & button.is-past { color: var(--ahr-hiring-deep); }
}
.ahr-hiring__facts {
  display: grid; grid-template-columns: 1fr 1fr; gap: 1px; border-radius: 11px; overflow: hidden; background: var(--ahr-hiring-rule); box-shadow: 0 0 0 1px var(--ahr-hiring-rule);
  & div { padding: 8px 10px; background: var(--ahr-hiring-card); }
  & dt { font-size: 10.5px; color: var(--ahr-hiring-faint); font-weight: 600; }
  & dd { font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-hiring__sc {
  display: grid; gap: 8px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; align-items: center; font-size: 12px; }
  & li > span:last-child { font-weight: 700; font-variant-numeric: tabular-nums; }
  & li i { grid-column: 1 / -1; height: 6px; border-radius: 3px; background: var(--ahr-hiring-well); overflow: hidden; }
  & li i::before { content: ""; display: block; height: 100%; width: calc(var(--v) / 4 * 100%); border-radius: inherit; background: var(--ahr-hiring-deep); transform-origin: 0 50%; animation: ahr-hiring-grow .7s var(--ahr-hiring-ease) calc(var(--i) * 70ms) both; }
  & small { color: var(--ahr-hiring-faint); font-size: 11px; }
}
.ahr-hiring__timeline {
  position: relative; display: grid; gap: 10px; padding-left: 16px;
  &::before { content: ""; position: absolute; left: 4px; top: 6px; bottom: 6px; width: 1.5px; background: var(--ahr-hiring-rule2); }
  & li { position: relative; font-size: 12px; text-wrap: pretty; }
  & li::before { content: ""; position: absolute; left: -16px; top: 5px; width: 9px; height: 9px; border-radius: 50%; background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 2px var(--ahr-hiring-faint); }
  & li:first-child::before { box-shadow: inset 0 0 0 2px var(--ahr-hiring-deep); background: var(--ahr-hiring-accent); }
  & time { display: block; font-size: 11px; color: var(--ahr-hiring-faint); font-variant-numeric: tabular-nums; }
}
.ahr-hiring__dfoot {
  display: flex; flex-wrap: wrap; gap: 6px; padding: 12px 16px; border-top: 1px solid var(--ahr-hiring-rule); background: var(--ahr-hiring-paper);
  & > button { display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); }
  & > button:hover:not(:disabled) { background: var(--ahr-hiring-hover); }
  & > button svg { width: 15px; height: 15px; }
  & .is-go { flex: 1; justify-content: center; color: var(--ahr-hiring-paper); background: var(--ahr-hiring-ink); box-shadow: none; }
  & .is-go:hover:not(:disabled) { background: color-mix(in oklch, var(--ahr-hiring-ink) 85%, var(--ahr-hiring-deep)) !important; }
  & .is-bad { color: var(--ahr-hiring-bad); }
}
.ahr-hiring__pick {
  flex-basis: 100%; display: grid; gap: 6px; padding: 10px; border-radius: 11px; background: var(--ahr-hiring-card); box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2);
  animation: ahr-hiring-pop .4s var(--ahr-hiring-spring) both;
  & p { font-size: 12px; font-weight: 650; }
  & div { display: flex; flex-wrap: wrap; gap: 5px; }
  & div button { height: 28px; padding: 0 10px; border-radius: 99px; font-size: 11.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule2); }
  & div button:hover { box-shadow: inset 0 0 0 1.5px var(--ahr-hiring-ink); }
  & div button.is-cancel { box-shadow: none; color: var(--ahr-hiring-muted); }
}
.ahr-hiring__live { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.ahr-hiring__toast {
  position: absolute; z-index: 60; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 10px; max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px; border-radius: 11px; font-size: 12.5px; font-weight: 550; color: var(--ahr-hiring-paper); background: var(--ahr-hiring-ink);
  box-shadow: 0 18px 36px -16px color-mix(in oklch, var(--ahr-hiring-ink) 70%, transparent);
  transition: opacity .2s var(--ahr-hiring-ease), transform .35s var(--ahr-hiring-spring);
  @starting-style { opacity: 0; transform: translateY(10px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(10px); }
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font-weight: 700; color: var(--ahr-hiring-accent); }
  & button:hover { background: color-mix(in oklch, var(--ahr-hiring-paper) 12%, transparent); }
}

@keyframes ahr-hiring-pop { from { opacity: 0; transform: scale(.94) translateY(-6px); } }
@keyframes ahr-hiring-rise { from { opacity: 0; translate: 0 12px; } }
@keyframes ahr-hiring-grow { from { transform: scaleX(0); } }
@keyframes ahr-hiring-flash { 0% { box-shadow: inset 0 0 0 0 transparent; } 30% { box-shadow: inset 0 0 0 2px var(--ahr-hiring-deep); } 100% { box-shadow: inset 0 0 0 1px var(--ahr-hiring-rule); } }

/* ---------- container queries ---------- */
@container (max-width: 1080px) { .ahr-hiring__keys { display: none; } .ahr-hiring__brand span { display: none; } }
@container (max-width: 959px) {
  .ahr-hiring__head { flex-wrap: wrap; gap: 10px; }
  .ahr-hiring__roles { order: 3; flex: 1 1 100%; margin-right: 0; }
  .ahr-hiring__find { margin-left: auto; }
  .ahr-hiring__funnel { grid-template-columns: repeat(5, minmax(96px, 1fr)); overflow-x: auto; scrollbar-width: none; }
  .ahr-hiring__board { grid-auto-columns: minmax(220px, 46%); }
}
@container (max-width: 759px) {
  .ahr-hiring__head { padding: 12px 12px 8px; }
  .ahr-hiring__funnel, .ahr-hiring__bar { padding-left: 12px; padding-right: 12px; }
  .ahr-hiring__step b { font-size: 17px; }
  .ahr-hiring__bar { flex-wrap: wrap; }
  .ahr-hiring__sources { flex: 1 1 100%; order: 3; }
  .ahr-hiring__board { grid-auto-columns: 86%; padding: 0 12px 12px; scroll-snap-type: x mandatory; }
  .ahr-hiring__drawer { inset: 0; width: auto; border-radius: 0; }
}
@container (max-width: 420px) {
  .ahr-hiring__brand div { display: none; }
  .ahr-hiring__find { flex: 1 1 auto; }
  .ahr-hiring__step em { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-hiring *, .ahr-hiring *::before, .ahr-hiring *::after { animation: none !important; transition-duration: .01s !important; }
}

