    case 'advance': if (c && SI[c.stage] < 4) moveTo(c.id, STAGES[SI[c.stage] + 1].k, 0); break;
    case 'schedule': S.pick = S.pick === 'slot' ? null : 'slot'; renderDrawer(); break;
    case 'reject': S.pick = S.pick === 'reject' ? null : 'reject'; renderDrawer(); break;
    case 'nopick': S.pick = null; renderDrawer(); break;
    case 'restore': if (c) moveTo(c.id, c.max, 0); break;
    case 'rejected': S.showRej = !S.showRej; render(); if (S.showRej) { const col = $('.ahr-hiring__col[data-stage="rejected"]'); if (col) col.scrollIntoView({ inline: 'end', block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' }); } break;
    case 'add': S.adding = 'focus'; S.addErr = ''; render(); { const col = $('.ahr-hiring__col[data-stage="applied"]'); if (col) col.scrollIntoView({ inline: 'start', block: 'nearest' }); } break;
    case 'noadd': S.adding = false; S.addErr = ''; render(); break;
    case 'undo': if (undo.length) { C = undo.pop(); if (S.open && !byId(S.open)) S.open = null; render(); toast('Undone'); } break;
  }
});
root.addEventListener('submit', (e) => {
  const f = e.target.closest('.ahr-hiring__form'); if (!f) return;
  const field = (n) => f.querySelector(`[name="${n}"]`);
  const name = field('name').value.trim(), co = field('co').value.trim(), src = field('src').value;
  if (name.split(/\s+/).length < 2) { S.addErr = 'Enter a first and last name.'; S.adding = 'focus'; render(); const i = $('.ahr-hiring__form input[name="name"]'); if (i) i.value = name; return; }
  undo.push(snap());
  const [title, company] = co.includes(' at ') ? co.split(' at ') : co.includes(',') ? co.split(',').map((s) => s.trim()) : [co || 'Candidate', '—'];
  const c = { id: 'c' + seq++, role: S.role, name, title: title || 'Candidate', co: company || '—', src, stage: 'applied', score: 0, days: 0, city: 'Location pending', next: 'Review application', max: 'applied', order: -1, reason: '' };
  C.push(c);
  colList('applied').forEach((x, i) => { x.order = i; });
  S.adding = false; S.addErr = ''; S.newId = c.id;
  render();
  toast(`Added ${name} to ${roleOf(S.role).short}`, true);
});
root.addEventListener('input', (e) => { if (e.target.matches('.ahr-hiring__find input')) { S.q = e.target.value; renderBoard(); } });
root.addEventListener('keydown', (e) => {
  const inField = e.target.closest('input, select, textarea');
  if (e.key === 'Escape') {
    if (drag && drag.on) { endDrag(e, true); return; }
    if (S.pick) { S.pick = null; renderDrawer(); return; }
    if (S.adding) { S.adding = false; render(); return; }
    if (S.open) { const id = S.open; S.open = null; render(); focusCard(id); return; }
    if (inField) e.target.blur();
    return;
  }
  if (inField) return;
  if (e.key === '/') { e.preventDefault(); $('.ahr-hiring__find input').focus(); return; }
  const card = e.target.closest('.ahr-hiring__card[data-id]');
  if (!card) { if (e.key.toLowerCase() === 'n') { e.preventDefault(); S.adding = 'focus'; render(); } return; }
  const id = card.dataset.id, c = byId(id);
  const cols = $$('.ahr-hiring__col', board), col = card.closest('.ahr-hiring__col'), ci = cols.indexOf(col);
  const cards = $$('.ahr-hiring__card[data-id]', col), i = cards.indexOf(card);
  if (e.shiftKey && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')) {
    e.preventDefault();
    if (c.stage === 'rejected') return;
    const ni = SI[c.stage] + (e.key === 'ArrowRight' ? 1 : -1);
    if (ni < 0 || ni > 4) return;
    moveTo(id, STAGES[ni].k, 0); focusCard(id);
  } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault(); const n = cards[i + (e.key === 'ArrowDown' ? 1 : -1)]; if (n) { n.focus(); n.scrollIntoView({ block: 'nearest' }); }
  } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
    e.preventDefault();
    for (let k = ci + (e.key === 'ArrowRight' ? 1 : -1); k >= 0 && k < cols.length; k += e.key === 'ArrowRight' ? 1 : -1) {
      const cc = $$('.ahr-hiring__card[data-id]', cols[k]); if (cc.length) { const n = cc[Math.min(i, cc.length - 1)]; n.focus(); n.scrollIntoView({ block: 'nearest', inline: 'nearest' }); break; }
    }
  } else if (e.key.toLowerCase() === 'x') { e.preventDefault(); reject(id, 'Not moving forward'); const n = cards[i + 1] || cards[i - 1]; if (n && n.isConnected) n.focus(); else { const nn = $(`.ahr-hiring__col[data-stage="${col.dataset.stage}"] .ahr-hiring__card`); if (nn) nn.focus(); } }
});

render();

