/* Performance review. Re-theme with --ahr-review-paper, -ink, -accent (manager) and -self. */
@property --ahr-review-pct { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@property --ahr-review-s { syntax: "<integer>"; inherits: true; initial-value: 0; }

.ahr-review {
  --ahr-review-paper: oklch(0.968 0.014 75);
  --ahr-review-ink: oklch(0.26 0.03 35);
  --ahr-review-accent: oklch(0.5 0.15 27);
  --ahr-review-self: oklch(0.56 0.08 232);

  --ahr-review-card: oklch(0.99 0.006 75);
  --ahr-review-muted: color-mix(in oklch, var(--ahr-review-ink) 62%, var(--ahr-review-paper));
  --ahr-review-faint: color-mix(in oklch, var(--ahr-review-ink) 40%, var(--ahr-review-paper));
  --ahr-review-rule: color-mix(in oklch, var(--ahr-review-ink) 10%, transparent);
  --ahr-review-rule2: color-mix(in oklch, var(--ahr-review-ink) 17%, transparent);
  --ahr-review-hover: color-mix(in oklch, var(--ahr-review-ink) 5%, transparent);
  --ahr-review-tint: color-mix(in oklch, var(--ahr-review-accent) 9%, var(--ahr-review-card));
  --ahr-review-ok: oklch(0.55 0.11 150);
  --ahr-review-bad: oklch(0.55 0.18 28);
  --ahr-review-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-review-spring: linear(0, 0.1 5%, 0.38 12%, 0.78 21%, 1 29%, 1.06 36%, 1.05 44%, 1.02 54%, 1 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-review-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-review-paper);
  color: var(--ahr-review-ink);
  font: 400 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--ahr-review-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--ahr-review-rule2);
}
:where(.ahr-review) *, :where(.ahr-review) *::before, :where(.ahr-review) *::after { box-sizing: border-box; }
:where(.ahr-review) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.ahr-review) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-review) button:disabled { cursor: not-allowed; opacity: .45; }
:where(.ahr-review) :is(p, h2, h3, h4, ul, ol, fieldset, legend, figure, q) { margin: 0; padding: 0; }
:where(.ahr-review) :is(ul, ol) { list-style: none; }
:where(.ahr-review) fieldset { border: 0; min-width: 0; }
:where(.ahr-review) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-review) :focus-visible { outline: 2px solid var(--ahr-review-accent); outline-offset: 2px; }
:where(.ahr-review) kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-review-muted);
  background: var(--ahr-review-card); box-shadow: inset 0 0 0 1px var(--ahr-review-rule2), 0 1px 0 var(--ahr-review-rule2);
}
.ahr-review__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.ahr-review__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head head" "nav main rail";
  grid-template-columns: clamp(190px, 18cqi, 220px) minmax(0, 1fr) clamp(260px, 26cqi, 300px);
  grid-template-rows: auto minmax(0, 1fr);
  timeline-scope: --ahr-review-main;
}

/* ---------- header ---------- */
.ahr-review__head { grid-area: head; display: flex; align-items: center; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--ahr-review-rule); }
.ahr-review__face { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; flex: none; font-weight: 750; font-size: 14px; color: var(--ahr-review-card); background: linear-gradient(140deg, var(--ahr-review-accent), color-mix(in oklch, var(--ahr-review-accent) 60%, var(--ahr-review-ink))); }
.ahr-review__who { min-width: 0; margin-right: auto;
  & h2 { font-size: clamp(16px, 1.7cqi, 19px); font-weight: 750; letter-spacing: -0.02em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--ahr-review-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ahr-review__cycle { font-size: 11.5px; font-weight: 600; color: var(--ahr-review-muted); padding: 4px 9px; border-radius: 99px; background: var(--ahr-review-hover); white-space: nowrap; }
.ahr-review__saved { font-size: 11.5px; color: var(--ahr-review-faint); white-space: nowrap; font-variant-numeric: tabular-nums; min-width: 112px; text-align: right; }
.ahr-review__switch {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 11px 0 8px; border-radius: 9px; font-size: 12.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); white-space: nowrap;
  & i { position: relative; width: 28px; height: 16px; border-radius: 8px; background: var(--ahr-review-rule2); transition: background-color .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--ahr-review-card); box-shadow: 0 1px 2px rgb(0 0 0 / .25); transition: translate .35s var(--ahr-review-spring); }
  &[aria-checked="true"] i { background: var(--ahr-review-self); }
  &[aria-checked="true"] i::after { translate: 12px 0; }
  &:hover { background: var(--ahr-review-hover); }
}
.ahr-review__submit {
  display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 9px 0 14px; border-radius: 9px; font-size: 12.5px; font-weight: 700; white-space: nowrap;
  color: var(--ahr-review-card); background: var(--ahr-review-accent); box-shadow: 0 8px 16px -10px var(--ahr-review-accent);
  transition: background-color .15s, translate .2s var(--ahr-review-ease);
  & kbd { color: inherit; background: color-mix(in oklch, var(--ahr-review-card) 20%, transparent); box-shadow: none; }
  &:hover { background: color-mix(in oklch, var(--ahr-review-accent) 86%, black); translate: 0 -1px; }
}
.ahr-review[data-state="submitted"] .ahr-review__submit { color: var(--ahr-review-ink); background: var(--ahr-review-card); box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); }

/* ---------- nav ---------- */
.ahr-review__nav { grid-area: nav; position: relative; padding: 16px 12px; border-right: 1px solid var(--ahr-review-rule); display: grid; align-content: start; gap: 4px; overflow: auto; }
.ahr-review__navbtn {
  display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; padding: 8px 9px; border-radius: 10px; text-align: left;
  transition: background-color .15s;
  & span { font-weight: 600; font-size: 12.5px; }
  & small { font-size: 11px; color: var(--ahr-review-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--ahr-review-hover); }
  &[aria-current="true"] { background: var(--ahr-review-card); box-shadow: 0 0 0 1px var(--ahr-review-rule2), 0 2px 6px -3px var(--ahr-review-rule2); }
}
.ahr-review__ring {
  position: relative; width: 26px; height: 26px; border-radius: 50%;
  background: conic-gradient(var(--ahr-review-accent) var(--ahr-review-pct), var(--ahr-review-rule2) 0);
  transition: --ahr-review-pct .7s var(--ahr-review-ease);
  &::after { content: ""; position: absolute; inset: 3px; border-radius: 50%; background: var(--ahr-review-paper); }
  & svg { position: absolute; inset: 6px; z-index: 1; width: 14px; height: 14px; color: var(--ahr-review-ok); stroke-width: 2.6; opacity: 0; scale: .4; transition: opacity .25s, scale .4s var(--ahr-review-spring); }
  &.is-done { background: var(--ahr-review-ok); }
  &.is-done::after { background: color-mix(in oklch, var(--ahr-review-ok) 14%, var(--ahr-review-paper)); }
  &.is-done svg { opacity: 1; scale: 1; }
}
.ahr-review__navbtn[aria-current="true"] .ahr-review__ring::after { background: var(--ahr-review-card); }
.ahr-review__track { margin: 14px 9px 0; height: 3px; border-radius: 2px; background: var(--ahr-review-rule); overflow: hidden; }
.ahr-review__track i { display: block; height: 100%; background: var(--ahr-review-accent); transform-origin: 0 50%; transform: scaleX(var(--p, 0)); transition: transform .2s linear; }
@supports (animation-timeline: scroll()) {
  .ahr-review__track i { animation: ahr-review-track linear both; animation-timeline: --ahr-review-main; transition: none; }
}
.ahr-review__keys { margin: 14px 9px 0; display: grid; gap: 6px; font-size: 11px; color: var(--ahr-review-faint); & span { display: flex; align-items: center; gap: 4px; } }

/* ---------- main ---------- */
.ahr-review__main {
  grid-area: main; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 18px clamp(14px, 2.4cqi, 28px) 40px; scroll-behavior: smooth;
  scroll-timeline: --ahr-review-main block;
  scrollbar-width: thin; scrollbar-color: var(--ahr-review-rule2) transparent;
}
.ahr-review__sec { display: grid; gap: 12px; padding-bottom: 26px; scroll-margin-top: 10px;
  & > header { display: flex; align-items: baseline; gap: 10px; }
  & > header h3 { font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--ahr-review-accent); }
  & > header p { font-size: 12px; color: var(--ahr-review-muted); text-wrap: pretty; }
}
fieldset.ahr-review__form { display: contents; }
.ahr-review__comp {
  display: grid; gap: 10px; padding: 14px 16px 16px; border-radius: 14px; background: var(--ahr-review-card);
  box-shadow: 0 0 0 1px var(--ahr-review-rule), 0 1px 2px var(--ahr-review-rule);
  transition: box-shadow .25s var(--ahr-review-ease);
  &:focus-within { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--ahr-review-accent) 55%, transparent), 0 10px 26px -18px var(--ahr-review-accent); }
  &.is-err { box-shadow: 0 0 0 1.5px var(--ahr-review-bad); }
  &.is-flash { animation: ahr-review-flash 1s var(--ahr-review-ease); }
  & > header { display: flex; align-items: center; gap: 8px; }
  & h4 { font-size: 14.5px; font-weight: 700; letter-spacing: -0.01em; }
  & .ahr-review__desc { font-size: 12.5px; color: var(--ahr-review-muted); text-wrap: pretty; }
}
.ahr-review__w { font-size: 11px; font-weight: 650; color: var(--ahr-review-faint); font-variant-numeric: tabular-nums; padding: 1px 6px; border-radius: 5px; background: var(--ahr-review-hover); }
.ahr-review__gap { margin-left: auto; font-size: 11px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--ahr-review-faint);
  &.is-up { color: var(--ahr-review-ok); } &.is-down { color: var(--ahr-review-bad); }
}
.ahr-review[data-self="off"] .ahr-review__gap { visibility: hidden; }
.ahr-review__selfq {
  display: grid; grid-template-columns: auto 1fr; gap: 10px; align-items: start; padding: 9px 11px; border-radius: 10px; font-size: 12px;
  background: color-mix(in oklch, var(--ahr-review-self) 8%, var(--ahr-review-card)); box-shadow: inset 2px 0 0 var(--ahr-review-self);
  & b { color: var(--ahr-review-self); font-size: 11.5px; white-space: nowrap; }
  & q { color: color-mix(in oklch, var(--ahr-review-ink) 80%, var(--ahr-review-paper)); text-wrap: pretty; }
}
.ahr-review[data-self="off"] .ahr-review__selfq { display: none; }
.ahr-review__scale {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; padding: 4px; border-radius: 12px; background: var(--ahr-review-paper); box-shadow: inset 0 0 0 1px var(--ahr-review-rule);
  & label { position: relative; display: grid; justify-items: center; gap: 0; padding: 7px 4px 6px; border-radius: 9px; cursor: pointer; transition: background-color .2s, color .2s, box-shadow .2s; }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & label span { font-size: 15px; font-weight: 750; font-variant-numeric: tabular-nums; line-height: 1.2; }
  & label small { font-size: 10px; font-weight: 600; color: var(--ahr-review-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
  & label:hover { background: var(--ahr-review-hover); }
  & label:has(input:checked) { color: var(--ahr-review-card); background: var(--ahr-review-accent); box-shadow: 0 6px 14px -8px var(--ahr-review-accent); }
  & label:has(input:checked) small { color: color-mix(in oklch, var(--ahr-review-card) 80%, transparent); }
  & label:has(input:checked) span { animation: ahr-review-pop .45s var(--ahr-review-spring); }
  & label:has(input:focus-visible) { outline: 2px solid var(--ahr-review-ink); outline-offset: 2px; }
  & label.is-self::after { content: ""; position: absolute; top: -3px; left: 50%; translate: -50% 0; width: 8px; height: 8px; border-radius: 50%; background: var(--ahr-review-self); box-shadow: 0 0 0 2px var(--ahr-review-card); }
}
.ahr-review[data-self="off"] .ahr-review__scale label.is-self::after { display: none; }
.ahr-review__anchor {
  display: grid; grid-template-columns: auto 1fr; gap: 3px 10px; align-items: baseline; min-height: 40px; font-size: 12.5px;
  & b { font-size: 12px; font-weight: 700; color: var(--ahr-review-accent); white-space: nowrap; }
  & p { color: color-mix(in oklch, var(--ahr-review-ink) 85%, var(--ahr-review-paper)); text-wrap: pretty; animation: ahr-review-in .35s var(--ahr-review-ease) both; }
  &.is-empty b { color: var(--ahr-review-faint); }
}
.ahr-review__field {
  display: grid; gap: 5px;
  & textarea { width: 100%; min-height: 64px; resize: vertical; border: 0; border-radius: 10px; padding: 9px 11px; font-size: 12.5px; line-height: 1.5; background: var(--ahr-review-paper); box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); transition: box-shadow .2s; }
  & textarea:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--ahr-review-accent), 0 0 0 4px color-mix(in oklch, var(--ahr-review-accent) 12%, transparent); }
  & textarea[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ahr-review-bad); }
  & textarea:read-only { opacity: .75; }
  & footer { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--ahr-review-faint); font-variant-numeric: tabular-nums; }
  & footer .is-need { color: var(--ahr-review-bad); font-weight: 600; }
  & footer .is-met { color: var(--ahr-review-ok); font-weight: 600; }
  & footer i { flex: 1; height: 3px; border-radius: 2px; background: var(--ahr-review-rule); overflow: hidden; }
  & footer i::before { content: ""; display: block; height: 100%; width: min(100%, calc(var(--f) * 100%)); background: var(--ahr-review-accent); transition: width .3s var(--ahr-review-ease); }
  & footer i.is-ok::before { background: var(--ahr-review-ok); }
  & > label { font-size: 12px; font-weight: 650; }
}
.ahr-review__prompts { display: flex; flex-wrap: wrap; gap: 5px;
  & button { height: 26px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 560; color: var(--ahr-review-muted); box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); }
  & button:hover:not(:disabled) { color: var(--ahr-review-ink); background: var(--ahr-review-hover); }
}
.ahr-review__goal {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 14px; align-items: center; padding: 13px 15px; border-radius: 13px; background: var(--ahr-review-card); box-shadow: 0 0 0 1px var(--ahr-review-rule);
  & h4 { font-size: 13.5px; font-weight: 650; text-wrap: pretty; }
  & .ahr-review__pctv { font-size: 18px; font-weight: 750; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  & input[type="range"] { grid-column: 1 / -1; width: 100%; margin: 0; }
  & p { grid-column: 1 / -1; font-size: 12px; color: var(--ahr-review-muted); }
}
.ahr-review__status {
  grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 4px;
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--ahr-review-muted); box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); transition: background-color .15s, color .15s; }
  & button:hover:not(:disabled) { color: var(--ahr-review-ink); }
  & button[aria-checked="true"] { color: var(--ahr-review-card); background: var(--c); box-shadow: none; }
}
.ahr-review__sum { display: grid; gap: 14px; padding: 16px; border-radius: 14px; background: var(--ahr-review-card); box-shadow: 0 0 0 1px var(--ahr-review-rule); }
.ahr-review__table {
  width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { font-size: 10.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-review-faint); text-align: right; padding: 0 0 6px; }
  & th:first-child, & td:first-child { text-align: left; }
  & td { padding: 6px 0; text-align: right; border-top: 1px solid var(--ahr-review-rule); }
  & tfoot td { font-weight: 750; border-top: 1.5px solid var(--ahr-review-rule2); }
  & .is-na { color: var(--ahr-review-faint); }
}
.ahr-review__promo {
  display: flex; align-items: center; gap: 12px; padding: 11px 12px; border-radius: 11px; background: var(--ahr-review-paper);
  & div { flex: 1; } & b { display: block; font-size: 12.5px; } & small { font-size: 11.5px; color: var(--ahr-review-muted); }
}
.ahr-review__errs {
  display: grid; gap: 6px; padding: 12px; border-radius: 11px; background: color-mix(in oklch, var(--ahr-review-bad) 8%, var(--ahr-review-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-review-bad) 35%, transparent);
  animation: ahr-review-in .35s var(--ahr-review-ease) both;
  & > b { font-size: 12.5px; color: var(--ahr-review-bad); }
  & button { display: flex; align-items: center; gap: 6px; width: 100%; padding: 4px 6px; border-radius: 7px; text-align: left; font-size: 12px; }
  & button:hover { background: color-mix(in oklch, var(--ahr-review-bad) 10%, transparent); }
  & button svg { width: 14px; height: 14px; color: var(--ahr-review-bad); }
}
.ahr-review__done {
  display: grid; grid-template-columns: auto 1fr auto; gap: 4px 12px; align-items: center; padding: 14px; border-radius: 12px;
  background: color-mix(in oklch, var(--ahr-review-ok) 10%, var(--ahr-review-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ahr-review-ok) 40%, transparent);
  animation: ahr-review-in .45s var(--ahr-review-spring) both;
  & svg { width: 26px; height: 26px; color: var(--ahr-review-ok); grid-row: span 2; }
  & b { font-size: 13.5px; } & small { font-size: 12px; color: var(--ahr-review-muted); grid-column: 2; }
  & button { grid-row: 1 / span 2; grid-column: 3; height: 32px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ahr-review-rule2); }
  & button:hover { background: var(--ahr-review-hover); }
}
.ahr-review__go { justify-self: end; height: 36px; padding: 0 16px; border-radius: 10px; font-size: 13px; font-weight: 700; color: var(--ahr-review-card); background: var(--ahr-review-accent); }
.ahr-review__go:hover { background: color-mix(in oklch, var(--ahr-review-accent) 86%, black); }

/* ---------- rail ---------- */
.ahr-review__rail { grid-area: rail; min-height: 0; overflow: auto; padding: 16px 16px 20px; border-left: 1px solid var(--ahr-review-rule); display: grid; align-content: start; gap: 14px; }
.ahr-review__score {
  display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 2px 12px; padding: 14px; border-radius: 14px; background: var(--ahr-review-card); box-shadow: 0 0 0 1px var(--ahr-review-rule);
  & .ahr-review__big {
    grid-row: span 2; font-size: 38px; font-weight: 800; letter-spacing: -0.04em; line-height: 1; font-variant-numeric: tabular-nums; color: var(--ahr-review-accent);
    transition: --ahr-review-s .9s cubic-bezier(.16, 1, .3, 1);
    @starting-style { --ahr-review-s: 0; }
  }
  & .ahr-review__big.is-math { counter-reset: ahr-review-w round(down, calc(var(--ahr-review-s) / 100), 1) ahr-review-f mod(var(--ahr-review-s), 100); }
  & .ahr-review__big.is-math::after { content: counter(ahr-review-w) "." counter(ahr-review-f, decimal-leading-zero); }
  & b { font-size: 13.5px; font-weight: 700; }
  & small { font-size: 11.5px; color: var(--ahr-review-muted); text-wrap: pretty; }
}
.ahr-review__radar {
  padding: 10px 6px 4px; border-radius: 14px; background: var(--ahr-review-card); box-shadow: 0 0 0 1px var(--ahr-review-rule);
  & svg { display: block; width: 100%; height: auto; overflow: visible; }
  & .ahr-review__grid { fill: none; stroke: var(--ahr-review-rule2); stroke-width: 1; }
  & .ahr-review__axis { stroke: var(--ahr-review-rule2); stroke-width: 1; }
  & .ahr-review__p-self { fill: color-mix(in oklch, var(--ahr-review-self) 12%, transparent); stroke: var(--ahr-review-self); stroke-width: 1.6; stroke-dasharray: 4 3; transition: opacity .3s; }
  & .ahr-review__p-mgr { fill: color-mix(in oklch, var(--ahr-review-accent) 20%, transparent); stroke: var(--ahr-review-accent); stroke-width: 2; }
  & circle { fill: var(--ahr-review-accent); stroke: var(--ahr-review-card); stroke-width: 1.5; }
  & circle.is-empty { fill: var(--ahr-review-card); stroke: var(--ahr-review-accent); stroke-dasharray: 2 2; }
  & text { fill: var(--ahr-review-muted); font-size: 10.5px; font-weight: 600; stroke: none; }
  & text b, & tspan { font-weight: 750; fill: var(--ahr-review-ink); }
  & figcaption { display: flex; justify-content: center; gap: 14px; padding: 6px 0 4px; font-size: 11px; color: var(--ahr-review-muted); }
  & figcaption span { display: inline-flex; align-items: center; gap: 6px; }
  & figcaption i { width: 14px; height: 0; border-top: 2px solid var(--ahr-review-accent); }
  & figcaption i.is-self { border-top: 2px dashed var(--ahr-review-self); }
}
.ahr-review[data-self="off"] .ahr-review__p-self, .ahr-review[data-self="off"] .ahr-review__radar figcaption .is-selfkey { opacity: 0; }
.ahr-review__calib { padding: 12px 14px; border-radius: 12px; background: var(--ahr-review-hover); font-size: 11.5px; color: var(--ahr-review-muted); text-wrap: pretty;
  & b { color: var(--ahr-review-ink); }
  & ul { display: flex; height: 26px; align-items: flex-end; gap: 3px; margin-top: 8px; }
  & li { flex: 1; height: calc(var(--v) * 100%); border-radius: 3px 3px 0 0; background: var(--ahr-review-rule2); position: relative; }
  & li.is-here { background: var(--ahr-review-accent); }
}
.ahr-review__inline { display: none; }

/* ---------- toast ---------- */
.ahr-review__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 11px;
  font-size: 12.5px; font-weight: 550; color: var(--ahr-review-card); background: var(--ahr-review-ink); box-shadow: 0 16px 30px -14px color-mix(in oklch, var(--ahr-review-ink) 70%, transparent);
  transition: opacity .2s var(--ahr-review-ease), transform .35s var(--ahr-review-spring);
  @starting-style { opacity: 0; transform: translateY(10px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(10px); }
}

.ahr-review__sec.is-flash > header h3 { animation: ahr-review-mark 1s var(--ahr-review-ease); }
.ahr-review__field.is-flash textarea { animation: ahr-review-flash 1s var(--ahr-review-ease); }
@keyframes ahr-review-mark { 0%, 100% { background: transparent; } 30% { background: color-mix(in oklch, var(--ahr-review-accent) 18%, transparent); } }
@keyframes ahr-review-pop { 0% { scale: .6; } 60% { scale: 1.15; } 100% { scale: 1; } }
@keyframes ahr-review-in { from { opacity: 0; translate: 0 4px; } }
@keyframes ahr-review-flash { 0%, 100% { box-shadow: 0 0 0 1px var(--ahr-review-rule); } 30% { box-shadow: 0 0 0 3px color-mix(in oklch, var(--ahr-review-accent) 45%, transparent); } }
@keyframes ahr-review-track { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* ---------- container queries ---------- */
@container (max-width: 1100px) {
  .ahr-review__cycle { display: none; }
}
@container (max-width: 959px) {
  .ahr-review__app { grid-template-areas: "head" "nav" "main"; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); }
  .ahr-review__rail { display: none; }
  .ahr-review__inline { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; }
  .ahr-review__nav { display: flex; gap: 4px; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--ahr-review-rule); overflow-x: auto; scrollbar-width: none; }
  .ahr-review__navbtn { width: auto; flex: none; grid-template-columns: 22px auto auto; padding: 6px 10px 6px 7px; }
  .ahr-review__ring { width: 22px; height: 22px; & svg { inset: 4px; } }
  .ahr-review__track, .ahr-review__keys { display: none; }
  .ahr-review__saved { display: none; }
}
@container (max-width: 640px) {
  .ahr-review__head { flex-wrap: wrap; padding: 12px; gap: 10px; }
  .ahr-review__who { flex: 1 1 calc(100% - 56px); }
  .ahr-review__switch { margin-left: auto; }
  .ahr-review__inline { grid-template-columns: minmax(0, 1fr); }
  .ahr-review__scale label small { display: none; }
  .ahr-review__main { padding: 14px 12px 32px; }
}
@container (max-width: 420px) {
  .ahr-review__who p { white-space: normal; }
  .ahr-review__submit kbd { display: none; }
  .ahr-review__navbtn small { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-review *, .ahr-review *::before, .ahr-review *::after { animation: none !important; transition-duration: .01s !important; }
  .ahr-review .ahr-review__main { scroll-behavior: auto; }
  .ahr-review .ahr-review__big { transition: none; }
}
.ahr-review__inline .ahr-review__radar svg { max-width: 320px; margin: 0 auto; }

