// Performance review form. Ratings, notes and goals live in `S`; the radar, score, nav rings,
// summary table and validation all derive from it.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
root.addEventListener('submit', (e) => e.preventDefault());

const ICON = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  warn: '<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4.5M12 17.2v.1"/>',
  done: '<circle cx="12" cy="12" r="9"/><path d="m8 12.4 2.7 2.7L16.3 9.5"/>',
  arrow: '<path d="M5 12h13M13 6l6 6-6 6"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;
const LEVELS = ['Below expectations', 'Partially meets', 'Meets', 'Exceeds', 'Outstanding'];
const SHORT = ['Below', 'Partial', 'Meets', 'Exceeds', 'Outstanding'];
const COMP = [
  { k: 'craft', short: 'Craft', name: 'Technical craft', w: 25, desc: 'Code quality, architecture and the judgement behind technical trade-offs.', self: 4, selfNote: 'Led the design-token migration — wrote the RFC and the codemods.', anchors: [
    'Work regularly needs rework; edge cases are caught by others.',
    'Solid on familiar ground; needs guidance on new architecture.',
    'Ships clean, tested code and makes sound trade-offs independently.',
    'Raises the bar for the team: patterns, reviews and tooling others adopt.',
    'Sets technical direction across teams; the go-to for the hardest problems.'] },
  { k: 'delivery', short: 'Delivery', name: 'Delivery', w: 25, desc: 'Scoping, predictability and getting the important things over the line.', self: 4, selfNote: 'Shipped checkout v3 two weeks early despite the August scope change.', anchors: [
    'Commitments slip without warning; work stalls when blocked.',
    'Delivers small, well-defined tasks; larger scopes drift.',
    'Delivers what was agreed, flags risk early and re-plans calmly.',
    'Lands ambiguous, multi-sprint work and de-risks it for others.',
    'Delivers outcomes that change the roadmap; others plan around their estimates.'] },
  { k: 'collab', short: 'Collab.', name: 'Collaboration', w: 20, desc: 'How they work with design, product and engineers on other teams.', self: 4, selfNote: 'Paired weekly with design on the component library.', anchors: [
    'Works in isolation; friction with partners goes unaddressed.',
    'Cooperative within the team; cross-team work needs a broker.',
    'A reliable partner who shares context and asks for input early.',
    'Makes other teams faster; seeks out disagreement and resolves it.',
    'Shapes how whole groups work together; a multiplier across the org.'] },
  { k: 'owner', short: 'Ownership', name: 'Ownership', w: 15, desc: 'Following through, owning incidents and leaving systems better than found.', self: 3, selfNote: 'Led two incident post-mortems and closed every follow-up.', anchors: [
    'Problems are handed off rather than owned.',
    'Owns assigned work; rarely looks beyond it.',
    'Owns outcomes end to end, including the unglamorous parts.',
    'Spots and fixes problems no one assigned; follows through on incidents.',
    'Treats the platform as their own; others trust them with anything.'] },
  { k: 'comm', short: 'Comms', name: 'Communication', w: 15, desc: 'Clarity in writing and meetings; keeping stakeholders informed.', self: 4, selfNote: 'Started the fortnightly frontend notes — 120 subscribers.', anchors: [
    'Updates are rare or unclear; stakeholders are surprised.',
    'Clear when asked; rarely volunteers context.',
    'Writes and speaks clearly; keeps the right people informed.',
    'Their docs and updates become the reference others link to.',
    'Changes minds across the company through writing and presence.'] },
];
const GOALS = [
  { k: 'g1', name: 'Ship the design-token pipeline to all three apps', pct: 100, status: 'done', note: 'Live in web, iOS and Android since Aug 18.' },
  { k: 'g2', name: 'Cut checkout LCP from 3.1 s to under 2.0 s', pct: 73, status: 'risk', note: 'Now 2.3 s at p75 — 0.8 of the 1.1 s target; image CDN work slipped to November.' },
  { k: 'g3', name: 'Mentor two engineers through their first on-call', pct: 50, status: 'track', note: 'Rina finished her rotation; Tobias starts on Oct 12.' },
];
const STATUS = { track: ['On track', 'oklch(0.55 0.11 150)'], risk: ['At risk', 'oklch(0.66 0.14 70)'], done: ['Done', 'oklch(0.5 0.08 232)'], missed: ['Missed', 'oklch(0.55 0.18 28)'] };
const CALIB = [2, 7, 21, 12, 4]; // Platform org, 46 engineers this cycle
const PROMPTS = ['Next half, I’d like Felix to', 'One pattern to work on is', 'A stretch opportunity would be'];
const MIN_WORDS = 25, OUTLIER_WORDS = 15;

const S = {
  r: { craft: 4, delivery: 5, collab: 3, owner: 4, comm: null },
  n: { craft: '', delivery: '', collab: 'Strong with design; the payments team found the August API handoff abrupt.', owner: '', comm: '' },
  goals: Object.fromEntries(GOALS.map((g) => [g.k, { pct: g.pct, status: g.status }])),
  strengths: 'Felix turned the token migration into a model other teams now copy. His RFC was the clearest',
  growth: '',
  promo: false,
  self: true,
  state: 'draft',
  errors: null,
  sec: 'comp',
};
const words = (s) => (s.trim() ? s.trim().split(/\s+/).length : 0);

/* ---------------- derived ---------------- */
function overall() {
  let pts = 0, w = 0;
  COMP.forEach((c) => { if (S.r[c.k]) { pts += (c.w * S.r[c.k]) / 100; w += c.w / 100; } });
  return { pts, w, v: w ? pts / w : 0, rated: COMP.filter((c) => S.r[c.k]).length };
}
const goalAvg = () => Math.round(GOALS.reduce((a, g) => a + S.goals[g.k].pct, 0) / GOALS.length);
const needsNote = (k) => [1, 2, 5].includes(S.r[k]);
function validate() {
  const out = [];
  COMP.forEach((c) => {
    if (!S.r[c.k]) out.push({ go: c.k, text: `Rate ${c.name}` });
    else if (needsNote(c.k) && words(S.n[c.k]) < OUTLIER_WORDS) out.push({ go: c.k, text: `${c.name}: a ${S.r[c.k]} needs ${OUTLIER_WORDS}+ words of evidence (${words(S.n[c.k])} so far)` });
  });
  if (words(S.strengths) < MIN_WORDS) out.push({ go: 'strengths', text: `Strengths: ${MIN_WORDS}+ words (${words(S.strengths)} so far)` });
  if (words(S.growth) < MIN_WORDS) out.push({ go: 'growth', text: `Growth areas: ${MIN_WORDS}+ words (${words(S.growth)} so far)` });
  return out;
}

/* ---------------- static skeleton ---------------- */
const main = $('.ahr-review__main');
function compHTML(c, i) {
  const name = `ahr-review-${c.k}-${UID}`;
  return `<article class="ahr-review__comp" data-k="${c.k}" id="ahr-review-${c.k}-${UID}" tabindex="-1">
    <header><h4>${esc(c.name)}</h4><span class="ahr-review__w">${c.w}%</span><span class="ahr-review__gap"></span></header>
    <p class="ahr-review__desc">${esc(c.desc)}</p>
    <div class="ahr-review__selfq"><b>Felix · ${c.self}</b><q>${esc(c.selfNote)}</q></div>
    <fieldset class="ahr-review__scale"><legend class="ahr-review__sr">${esc(c.name)} rating</legend>
      ${LEVELS.map((l, j) => `<label class="${c.self === j + 1 ? 'is-self' : ''}" title="${l}${c.self === j + 1 ? ' — Felix’s self-rating' : ''}"><input type="radio" name="${name}" value="${j + 1}" data-rate="${c.k}"><span>${j + 1}</span><small>${SHORT[j]}</small></label>`).join('')}
    </fieldset>
    <div class="ahr-review__anchor" aria-live="polite"></div>
    <div class="ahr-review__field"><textarea data-note="${c.k}" aria-label="${esc(c.name)} evidence" placeholder="Evidence: what did you see, and what was the impact?"></textarea><footer></footer></div>
  </article>`;
}
function goalHTML(g) {
  return `<div class="ahr-review__goal" data-g="${g.k}"><h4>${esc(g.name)}</h4><span class="ahr-review__pctv"></span>
    <input type="range" min="0" max="100" step="1" value="${S.goals[g.k].pct}" data-gpct="${g.k}" aria-label="${esc(g.name)} progress">
    <div class="ahr-review__status" role="radiogroup" aria-label="${esc(g.name)} status"></div>
    <p>${esc(g.note)}</p></div>`;
}
main.innerHTML = `<fieldset class="ahr-review__form">
  <section class="ahr-review__sec" data-sec="comp"><header><h3>Competencies</h3><p>Rate against the Senior Engineer bar. 1, 2 and 5 need written evidence.</p></header>${COMP.map(compHTML).join('')}</section>
  <section class="ahr-review__sec" data-sec="goals"><header><h3>Goals</h3><p>H2 goals agreed on Jul 6.</p></header>${GOALS.map(goalHTML).join('')}</section>
  <section class="ahr-review__sec" data-sec="feedback"><header><h3>Feedback</h3><p>Felix sees this section after calibration.</p></header>
    <div class="ahr-review__field" id="ahr-review-strengths-${UID}"><label for="ahr-review-s-${UID}">Strengths</label><textarea id="ahr-review-s-${UID}" data-fb="strengths" rows="3"></textarea><footer></footer></div>
    <div class="ahr-review__field" id="ahr-review-growth-${UID}"><label for="ahr-review-g-${UID}">Growth areas</label><textarea id="ahr-review-g-${UID}" data-fb="growth" rows="3" placeholder="What should Felix focus on next half?"></textarea><div class="ahr-review__prompts">${PROMPTS.map((p, i) => `<button type="button" data-prompt="${i}">${esc(p)}…</button>`).join('')}</div><footer></footer></div>
  </section>
  <section class="ahr-review__sec" data-sec="summary"><header><h3>Summary</h3><p>Weighted score, nomination and submission.</p></header>
    <div class="ahr-review__inline"></div>
    <div class="ahr-review__sum"></div>
  </section></fieldset>`;
COMP.forEach((c) => { $(`[data-note="${c.k}"]`).value = S.n[c.k]; });
$('[data-fb="strengths"]').value = S.strengths;

/* ---------------- updates ---------------- */
function updateComp(k) {
  const c = COMP.find((x) => x.k === k), card = $(`.ahr-review__comp[data-k="${k}"]`), v = S.r[k];
  $$('input[data-rate]', card).forEach((inp) => { inp.checked = +inp.value === v; });
  const an = $('.ahr-review__anchor', card);
  an.classList.toggle('is-empty', !v);
  an.innerHTML = v ? `<b>${v} · ${LEVELS[v - 1]}</b><p>${esc(c.anchors[v - 1])}</p>` : `<b>Not rated</b><p>Pick a level — the behavioural anchor for it appears here. Keys <kbd>1</kbd>–<kbd>5</kbd> work too.</p>`;
  const gap = $('.ahr-review__gap', card), d = v ? v - c.self : null;
  gap.className = 'ahr-review__gap' + (d > 0 ? ' is-up' : d < 0 ? ' is-down' : '');
  gap.innerHTML = d == null ? `Felix rated ${c.self}` : d === 0 ? 'Matches self-rating' : `${d > 0 ? '+' : '−'}${Math.abs(d)} vs self`;
  const n = words(S.n[k]), need = needsNote(k);
  $('.ahr-review__field footer', card).innerHTML = need
    ? `<span class="${n >= OUTLIER_WORDS ? 'is-met' : 'is-need'}">${n}/${OUTLIER_WORDS} words${n >= OUTLIER_WORDS ? ' ✓' : ' required for a ' + v}</span><i class="${n >= OUTLIER_WORDS ? 'is-ok' : ''}" style="--f:${n / OUTLIER_WORDS}"></i>`
    : `<span>${n} word${n === 1 ? '' : 's'} · optional</span>`;
  $('textarea', card).setAttribute('aria-invalid', String(!!(S.errors && need && n < OUTLIER_WORDS)));
  card.classList.toggle('is-err', !!(S.errors && (!v || (need && n < OUTLIER_WORDS))));
}
function updateGoal(k) {
  const el = $(`.ahr-review__goal[data-g="${k}"]`), g = S.goals[k];
  $('.ahr-review__pctv', el).textContent = g.pct + '%';
  $('input', el).value = g.pct;
  $('.ahr-review__status', el).innerHTML = Object.entries(STATUS).map(([sk, [l, c]]) => `<button type="button" role="radio" data-gs="${k}:${sk}" aria-checked="${g.status === sk}" style="--c:${c}">${l}</button>`).join('');
}
function updateFeedback() {
  ['strengths', 'growth'].forEach((f) => {
    const n = words(S[f]), wrap = $(`[data-fb="${f}"]`).closest('.ahr-review__field');
    $('footer', wrap).innerHTML = `<span class="${n >= MIN_WORDS ? 'is-met' : S.errors ? 'is-need' : ''}">${n}/${MIN_WORDS} words${n >= MIN_WORDS ? ' ✓' : ''}</span><i class="${n >= MIN_WORDS ? 'is-ok' : ''}" style="--f:${n / MIN_WORDS}"></i>`;
    $(`[data-fb="${f}"]`).setAttribute('aria-invalid', String(!!(S.errors && n < MIN_WORDS)));
  });
}
function radarSVG() {
  const W = 270, H = 232, cx = W / 2, cy = 116, R = 78;
  const ang = (i) => -Math.PI / 2 + (i * 2 * Math.PI) / COMP.length;
  const pt = (i, v) => [cx + Math.cos(ang(i)) * (v / 5) * R, cy + Math.sin(ang(i)) * (v / 5) * R];
  let g = '';
  for (let l = 1; l <= 5; l++) g += `<polygon class="ahr-review__grid" points="${COMP.map((_, i) => pt(i, l).map((n) => n.toFixed(1)).join(',')).join(' ')}"/>`;
  COMP.forEach((c, i) => {
    const [x, y] = pt(i, 5), [lx, ly] = pt(i, 6.3);
    g += `<line class="ahr-review__axis" x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;
    const anchor = Math.abs(lx - cx) < 4 ? 'middle' : lx > cx ? 'start' : 'end';
    g += `<text x="${lx.toFixed(1)}" y="${(ly + 3).toFixed(1)}" text-anchor="${anchor}">${esc(c.short)} <tspan data-rv="${c.k}">${S.r[c.k] || '–'}</tspan></text>`;
  });
  g += `<polygon class="ahr-review__p-self" points="${COMP.map((c, i) => pt(i, c.self).map((n) => n.toFixed(1)).join(',')).join(' ')}"/>`;
  g += `<polygon class="ahr-review__p-mgr" points=""/>`;
  COMP.forEach((c) => { g += `<circle r="3.5" data-dot="${c.k}"/>`; });
