css:
/* Onboarding journeys. Re-theme with --ahr-onboard-bg, -ink, -accent, -ok and -late. */
@property --ahr-onboard-p { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@property --ahr-onboard-pos { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.ahr-onboard {
  --ahr-onboard-bg: oklch(0.21 0.026 172);
  --ahr-onboard-ink: oklch(0.95 0.014 150);
  --ahr-onboard-accent: oklch(0.83 0.11 62);
  --ahr-onboard-ok: oklch(0.8 0.12 160);
  --ahr-onboard-late: oklch(0.72 0.15 30);

  --ahr-onboard-panel: color-mix(in oklch, var(--ahr-onboard-ink) 4%, var(--ahr-onboard-bg));
  --ahr-onboard-raise: color-mix(in oklch, var(--ahr-onboard-ink) 8%, var(--ahr-onboard-bg));
  --ahr-onboard-muted: color-mix(in oklch, var(--ahr-onboard-ink) 62%, var(--ahr-onboard-bg));
  --ahr-onboard-faint: color-mix(in oklch, var(--ahr-onboard-ink) 40%, var(--ahr-onboard-bg));
  --ahr-onboard-rule: color-mix(in oklch, var(--ahr-onboard-ink) 9%, transparent);
  --ahr-onboard-rule2: color-mix(in oklch, var(--ahr-onboard-ink) 16%, transparent);
  --ahr-onboard-hover: color-mix(in oklch, var(--ahr-onboard-ink) 5%, transparent);
  --ahr-onboard-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-onboard-spring: linear(0, 0.1 5%, 0.38 12%, 0.78 21%, 1 29%, 1.06 36%, 1.05 44%, 1.02 54%, 1 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-onboard-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: radial-gradient(120% 60% at 100% 0%, color-mix(in oklch, var(--ahr-onboard-accent) 7%, transparent), transparent 60%), var(--ahr-onboard-bg);
  color: var(--ahr-onboard-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--ahr-onboard-accent);
  outline: none;
}
:where(.ahr-onboard) *, :where(.ahr-onboard) *::before, :where(.ahr-onboard) *::after { box-sizing: border-box; }
:where(.ahr-onboard) :is(button, input, select) { font: inherit; color: inherit; }
:where(.ahr-onboard) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-onboard) button:disabled { cursor: not-allowed; opacity: .45; }
:where(.ahr-onboard) :is(p, h2, h3, ul, ol) { margin: 0; padding: 0; }
:where(.ahr-onboard) :is(ul, ol) { list-style: none; }
:where(.ahr-onboard) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-onboard) :focus-visible { outline: 2px solid var(--ahr-onboard-accent); outline-offset: 2px; }
:where(.ahr-onboard) kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-onboard-muted); background: var(--ahr-onboard-raise); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2);
}

.ahr-onboard__app { height: 100%; display: grid; grid-template-columns: clamp(250px, 25cqi, 290px) minmax(0, 1fr); grid-template-areas: "hires main"; }

/* ---------- hires ---------- */
.ahr-onboard__hires { grid-area: hires; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; border-right: 1px solid var(--ahr-onboard-rule); background: color-mix(in oklch, black 12%, transparent); }
.ahr-onboard__brand { display: flex; align-items: center; gap: 10px; padding: 16px 16px 12px;
  & > svg { width: 32px; height: 32px; padding: 6px; border-radius: 10px; color: var(--ahr-onboard-bg); background: var(--ahr-onboard-accent); stroke-width: 2; }
  & b { display: block; font-size: 14px; font-weight: 720; letter-spacing: -0.01em; }
  & span { display: block; font-size: 11px; color: var(--ahr-onboard-muted); }
}
.ahr-onboard__hirelist { overflow: auto; padding: 4px 10px 12px; display: grid; align-content: start; gap: 4px; outline: none; scrollbar-width: none; }
.ahr-onboard__hire {
  position: relative; display: grid; grid-template-columns: 36px minmax(0, 1fr) auto; gap: 1px 10px; align-items: center; padding: 10px; border-radius: 12px; cursor: pointer;
  transition: background-color .15s;
  animation: ahr-onboard-in .45s var(--ahr-onboard-ease) calc(var(--i) * 50ms) both;
  &:hover { background: var(--ahr-onboard-hover); }
  &[aria-selected="true"] { background: var(--ahr-onboard-raise); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: -10px; top: 14px; bottom: 14px; width: 3px; border-radius: 0 3px 3px 0; background: var(--ahr-onboard-accent); }
  &.is-focus { box-shadow: inset 0 0 0 2px var(--ahr-onboard-accent); }
  & b { display: block; font-size: 13px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.5px; color: var(--ahr-onboard-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { grid-column: 2 / -1; display: flex; align-items: center; gap: 8px; font-style: normal; font-size: 11px; color: var(--ahr-onboard-faint); font-variant-numeric: tabular-nums; margin-top: 5px; }
  & em i { flex: 1; height: 4px; border-radius: 2px; background: var(--ahr-onboard-rule); overflow: hidden; }
  & em i::before { content: ""; display: block; height: 100%; width: var(--w); border-radius: inherit; background: var(--ahr-onboard-ok); transition: width .5s var(--ahr-onboard-ease); }
}
.ahr-onboard__av { grid-row: span 2; display: grid; place-items: center; width: 36px; height: 36px; border-radius: 11px; font-size: 12px; font-weight: 700; color: oklch(0.9 0.05 var(--h)); background: oklch(0.36 0.06 var(--h)); }
.ahr-onboard__late { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 6px; border-radius: 10px; font-size: 10.5px; font-weight: 750; color: var(--ahr-onboard-bg); background: var(--ahr-onboard-late); font-variant-numeric: tabular-nums; }
.ahr-onboard__soon { font-size: 10.5px; font-weight: 650; color: var(--ahr-onboard-accent); white-space: nowrap; }
.ahr-onboard__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 10px 16px 14px; font-size: 11px; color: var(--ahr-onboard-faint); border-top: 1px solid var(--ahr-onboard-rule); & span { display: inline-flex; align-items: center; gap: 3px; } }

/* ---------- main ---------- */
.ahr-onboard__main { grid-area: main; display: grid; grid-template-rows: auto auto auto minmax(0, 1fr); min-width: 0; min-height: 0; }
.ahr-onboard__hero {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 4px 14px; padding: 16px 20px 2px;
  & .ahr-onboard__back { display: none; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--ahr-onboard-muted); }
  & .ahr-onboard__back:hover { background: var(--ahr-onboard-hover); color: var(--ahr-onboard-ink); }
  & h2 { font-size: clamp(17px, 2cqi, 21px); font-weight: 750; letter-spacing: -0.02em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--ahr-onboard-muted); text-wrap: pretty; }
  & p b { color: var(--ahr-onboard-ink); font-weight: 600; }
}
.ahr-onboard__ring {
  position: relative; display: grid; place-items: center; width: 56px; height: 56px; border-radius: 50%;
  background: conic-gradient(var(--ahr-onboard-ok) var(--ahr-onboard-p), var(--ahr-onboard-raise) 0);
  transition: --ahr-onboard-p .9s var(--ahr-onboard-ease);
  @starting-style { --ahr-onboard-p: 0%; }
  &::before { content: ""; position: absolute; inset: 5px; border-radius: 50%; background: var(--ahr-onboard-bg); }
  & span { position: relative; font-size: 14px; font-weight: 750; font-variant-numeric: tabular-nums; letter-spacing: -0.02em; }
}
.ahr-onboard__heroacts { display: flex; gap: 6px; align-items: center; }
.ahr-onboard__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 650; white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); transition: background-color .15s, translate .2s var(--ahr-onboard-ease);
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled) { background: var(--ahr-onboard-hover); }
  &.is-hot { color: var(--ahr-onboard-bg); background: var(--ahr-onboard-accent); box-shadow: none; }
  &.is-hot:hover:not(:disabled) { background: color-mix(in oklch, var(--ahr-onboard-accent) 88%, white); translate: 0 -1px; }
}

/* ---------- journey rail ---------- */
.ahr-onboard__rail { position: relative; padding: 30px 28px 14px; }
.ahr-onboard__track {
  position: relative; display: grid; grid-template-columns: repeat(6, 1fr);
  &::before { content: ""; position: absolute; left: calc(100% / 12); right: calc(100% / 12); top: 15px; height: 2px; border-radius: 1px; background: var(--ahr-onboard-rule2); }
  &::after { content: ""; position: absolute; left: calc(100% / 12); top: 15px; height: 2px; border-radius: 1px; width: calc(var(--ahr-onboard-pos) * 5 / 6); background: linear-gradient(90deg, var(--ahr-onboard-ok), var(--ahr-onboard-accent)); transition: --ahr-onboard-pos 1s var(--ahr-onboard-ease); }
  --ahr-onboard-pos: 0%;
  transition: --ahr-onboard-pos 1s var(--ahr-onboard-ease);
}
.ahr-onboard__node {
  position: relative; z-index: 1; display: grid; justify-items: center; gap: 4px; padding: 0 2px; border-radius: 10px; text-align: center;
  & .ahr-onboard__dot {
    position: relative; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
    background: conic-gradient(var(--c, var(--ahr-onboard-ok)) var(--ahr-onboard-p), var(--ahr-onboard-raise) 0);
    transition: --ahr-onboard-p .8s var(--ahr-onboard-ease), scale .35s var(--ahr-onboard-spring);
    @starting-style { --ahr-onboard-p: 0%; }
  }
  & .ahr-onboard__dot::before { content: ""; position: absolute; inset: 3.5px; border-radius: 50%; background: var(--ahr-onboard-bg); }
  & .ahr-onboard__dot svg, & .ahr-onboard__dot b { position: relative; width: 14px; height: 14px; font-size: 10.5px; font-weight: 750; font-variant-numeric: tabular-nums; }
  & .ahr-onboard__dot svg { color: var(--ahr-onboard-ok); stroke-width: 2.6; }
  & span { font-size: 11.5px; font-weight: 650; }
  & small { font-size: 10.5px; color: var(--ahr-onboard-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
  &:hover .ahr-onboard__dot { scale: 1.08; }
  &[aria-current="true"] .ahr-onboard__dot { box-shadow: 0 0 0 4px color-mix(in oklch, var(--ahr-onboard-accent) 22%, transparent); }
  &[aria-current="true"] span { color: var(--ahr-onboard-accent); }
  &.is-late { --c: var(--ahr-onboard-late); }
  &[aria-pressed="true"] { background: var(--ahr-onboard-hover); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); }
}
.ahr-onboard__here {
  position: absolute; z-index: 2; top: 4px; left: calc(28px + (100% - 56px) / 12 + (100% - 56px) * 5 / 6 * var(--x)); translate: -50% 0;
  display: grid; justify-items: center; pointer-events: none; transition: left .9s var(--ahr-onboard-spring);
  & i { width: 2px; height: 22px; border-radius: 1px; background: var(--ahr-onboard-accent); box-shadow: 0 0 10px var(--ahr-onboard-accent); }
  & b { padding: 2px 6px; border-radius: 6px; font-size: 10px; font-weight: 750; letter-spacing: .03em; color: var(--ahr-onboard-bg); background: var(--ahr-onboard-accent); white-space: nowrap; }
}

/* ---------- filters ---------- */
.ahr-onboard__filters { display: flex; align-items: center; gap: 6px; padding: 0 20px 10px; flex-wrap: wrap; }
.ahr-onboard__chip {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--ahr-onboard-muted);
  box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); transition: background-color .15s, color .15s;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & span { font-size: 10.5px; color: var(--ahr-onboard-faint); font-variant-numeric: tabular-nums; }
  &:hover { color: var(--ahr-onboard-ink); background: var(--ahr-onboard-hover); }
  &[aria-pressed="true"] { color: var(--ahr-onboard-ink); background: var(--ahr-onboard-raise); box-shadow: inset 0 0 0 1.5px var(--c, var(--ahr-onboard-ink)); }
}
.ahr-onboard__switch {
  margin-left: auto; display: inline-flex; align-items: center; gap: 8px; height: 28px; padding: 0 4px 0 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--ahr-onboard-muted);
  & i { position: relative; width: 28px; height: 16px; border-radius: 8px; background: var(--ahr-onboard-rule2); transition: background-color .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--ahr-onboard-ink); transition: translate .35s var(--ahr-onboard-spring); }
  &[aria-checked="true"] { color: var(--ahr-onboard-ink); }
  &[aria-checked="true"] i { background: var(--ahr-onboard-ok); }
  &[aria-checked="true"] i::after { translate: 12px 0; background: var(--ahr-onboard-bg); }
  &:hover { background: var(--ahr-onboard-hover); }
}

/* ---------- tasks ---------- */
.ahr-onboard__tasks { position: relative; min-height: 0; overflow: auto; overscroll-behavior: contain; margin: 0 12px 12px; border-radius: 14px; background: var(--ahr-onboard-panel); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule); scrollbar-width: thin; scrollbar-color: var(--ahr-onboard-rule2) transparent; }
.ahr-onboard__progress { position: sticky; top: 0; z-index: 4; display: block; height: 2px; margin-bottom: -2px; background: var(--ahr-onboard-accent); transform-origin: 0 50%; transform: scaleX(0); opacity: 0; }
@supports (animation-timeline: scroll()) {
  .ahr-onboard__progress { opacity: 1; animation: ahr-onboard-progress linear both; animation-timeline: scroll(nearest block); }
}
.ahr-onboard__phase {
  position: sticky; top: 0; z-index: 3; display: flex; align-items: center; gap: 10px; padding: 10px 14px 8px;
  background: color-mix(in oklch, var(--ahr-onboard-panel) 92%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--ahr-onboard-rule);
  & h3 { font-size: 11px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; }
  & small { font-size: 11px; color: var(--ahr-onboard-faint); font-variant-numeric: tabular-nums; }
  & em { margin-left: auto; font-style: normal; font-size: 11px; font-weight: 650; color: var(--ahr-onboard-muted); font-variant-numeric: tabular-nums; }
  & button { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 650; color: var(--ahr-onboard-accent); }
  & button:hover { background: var(--ahr-onboard-hover); }
  & button svg { width: 13px; height: 13px; stroke-width: 2.2; }
  &.is-flash h3 { animation: ahr-onboard-flash .9s var(--ahr-onboard-ease); }
}
.ahr-onboard__list { padding: 4px 6px 8px; }
.ahr-onboard__task {
  display: grid; grid-template-columns: 26px minmax(0, 1fr) auto auto auto; align-items: center; gap: 10px; min-height: 46px; padding: 6px 8px; border-radius: 10px;
  transition: background-color .15s;
  &:hover { background: var(--ahr-onboard-hover); }
  &.is-cursor { background: var(--ahr-onboard-raise); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); }
  & .ahr-onboard__title { min-width: 0; }
  & .ahr-onboard__title b { display: block; font-size: 13px; font-weight: 560; transition: color .25s; }
  & .ahr-onboard__title small { display: block; font-size: 11px; color: var(--ahr-onboard-faint); }
  &.is-done .ahr-onboard__title b { color: var(--ahr-onboard-faint); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--ahr-onboard-ink) 30%, transparent); }
  &.is-new { animation: ahr-onboard-in .5s var(--ahr-onboard-spring) both; }
}
@supports (animation-timeline: view()) {
  .ahr-onboard__task { animation: ahr-onboard-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
.ahr-onboard__check {
  display: grid; place-items: center; width: 22px; height: 22px; border-radius: 7px; box-shadow: inset 0 0 0 1.5px var(--ahr-onboard-rule2); transition: background-color .2s, box-shadow .2s;
  & svg { width: 14px; height: 14px; stroke-width: 2.8; color: var(--ahr-onboard-bg); stroke-dasharray: 24; stroke-dashoffset: 24; transition: stroke-dashoffset .35s var(--ahr-onboard-ease) .05s; }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--ahr-onboard-ok); }
  &[aria-checked="true"] { background: var(--ahr-onboard-ok); box-shadow: none; }
  &[aria-checked="true"] svg { stroke-dashoffset: 0; }
}
.ahr-onboard__owner {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 8px 0 7px; border-radius: 8px; font-size: 11.5px; font-weight: 600; white-space: nowrap; max-width: 170px;
  box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); transition: background-color .15s;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); flex: none; }
  & span { overflow: hidden; text-overflow: ellipsis; }
  & svg { width: 12px; height: 12px; color: var(--ahr-onboard-faint); }
  &:hover { background: var(--ahr-onboard-hover); }
  &[aria-expanded="true"] { background: var(--ahr-onboard-raise); box-shadow: inset 0 0 0 1.5px var(--ahr-onboard-accent); }
}
.ahr-onboard__due { min-width: 92px; text-align: right; font-size: 11.5px; color: var(--ahr-onboard-muted); font-variant-numeric: tabular-nums; white-space: nowrap;
  & b { display: block; font-size: 10.5px; font-weight: 700; }
  &.is-late b { color: var(--ahr-onboard-late); }
  &.is-soon b { color: var(--ahr-onboard-accent); }
  &.is-done b { color: var(--ahr-onboard-ok); }
}
.ahr-onboard__nudge { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--ahr-onboard-late);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--ahr-onboard-late) 14%, transparent); }
  &.is-sent { color: var(--ahr-onboard-ok); }
  & svg { width: 16px; height: 16px; }
}
.ahr-onboard__spacer { width: 28px; }
.ahr-onboard__add {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 6px; padding: 6px 8px 8px; animation: ahr-onboard-in .35s var(--ahr-onboard-spring) both;
  & input, & select { height: 32px; border: 0; border-radius: 8px; padding: 0 10px; font-size: 12.5px; background: var(--ahr-onboard-bg); box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2); }
  & input:focus-visible, & select:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--ahr-onboard-accent); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ahr-onboard-late); }
  & button { height: 32px; padding: 0 12px; border-radius: 8px; font-size: 12px; font-weight: 700; color: var(--ahr-onboard-bg); background: var(--ahr-onboard-accent); }
}
.ahr-onboard__empty { padding: 16px; text-align: center; font-size: 12px; color: var(--ahr-onboard-faint); }

/* ---------- menu & toast ---------- */
.ahr-onboard__menu {
  position: absolute; z-index: 40; min-width: 210px; padding: 5px; border-radius: 12px; background: color-mix(in oklch, var(--ahr-onboard-ink) 9%, var(--ahr-onboard-bg));
  box-shadow: inset 0 0 0 1px var(--ahr-onboard-rule2), 0 20px 40px -14px rgb(0 0 0 / .7);
  transform-origin: 100% 0; transition: opacity .15s var(--ahr-onboard-ease), transform .25s var(--ahr-onboard-spring);
  @starting-style { opacity: 0; transform: scale(.95) translateY(-4px); }
  &[hidden] { display: none; }
  & p { padding: 6px 8px 4px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ahr-onboard-faint); }
  & button { display: grid; grid-template-columns: 10px 1fr auto; align-items: center; gap: 9px; width: 100%; padding: 7px 8px; border-radius: 8px; text-align: left; font-size: 12.5px; }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & button small { color: var(--ahr-onboard-faint); font-size: 11px; }
  & button:is(:hover, :focus-visible) { background: var(--ahr-onboard-hover); outline: none; }
  & button[aria-checked="true"] { color: var(--ahr-onboard-accent); }
}
.ahr-onboard__toast {
  position: absolute; z-index: 50; left: 50%; bottom: 18px; translate: -50% 0; display: flex; align-items: center; gap: 10px; max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px; border-radius: 11px; font-size: 12.5px; font-weight: 550; color: var(--ahr-onboard-bg); background: var(--ahr-onboard-ink); box-shadow: 0 18px 36px -16px rgb(0 0 0 / .7);
  transition: opacity .2s var(--ahr-onboard-ease), transform .35s var(--ahr-onboard-spring);
  @starting-style { opacity: 0; transform: translateY(10px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(10px); }
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font-weight: 700; color: color-mix(in oklch, var(--ahr-onboard-accent) 50%, black); }
  & button:hover { background: color-mix(in oklch, var(--ahr-onboard-bg) 10%, transparent); }
}

@keyframes ahr-onboard-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-onboard-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes ahr-onboard-progress { to { transform: scaleX(1); } }
@keyframes ahr-onboard-flash { 0%, 100% { color: inherit; } 30% { color: var(--ahr-onboard-accent); } }

/* ---------- container queries ---------- */
@container (max-width: 1040px) {
  .ahr-onboard__owner { max-width: 120px; }
  .ahr-onboard__node small { display: none; }
}
@container (max-width: 879px) {
  .ahr-onboard__app { grid-template-columns: 220px minmax(0, 1fr); }
  .ahr-onboard__hero { grid-template-columns: auto minmax(0, 1fr); }
  .ahr-onboard__heroacts { grid-column: 1 / -1; }
  .ahr-onboard__task { grid-template-columns: 26px minmax(0, 1fr) auto auto; }
  .ahr-onboard__task .ahr-onboard__due { grid-column: 2; grid-row: 2; text-align: left; min-width: 0; & b { display: inline; margin-right: 6px; } }
}
@container (max-width: 759px) {
  .ahr-onboard__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "pane"; }
  .ahr-onboard__hires, .ahr-onboard__main { grid-area: pane; border: 0; }
  .ahr-onboard[data-view="list"] .ahr-onboard__main, .ahr-onboard[data-view="plan"] .ahr-onboard__hires { display: none; }
  .ahr-onboard__hero { padding: 12px 14px 4px; grid-template-columns: auto auto minmax(0, 1fr); & .ahr-onboard__back { display: grid; } }
  .ahr-onboard__rail { padding: 30px 16px 10px; }
  .ahr-onboard__here { left: calc(16px + (100% - 32px) / 12 + (100% - 32px) * 5 / 6 * var(--x)); }
  .ahr-onboard__node span { font-size: 10px; }
  .ahr-onboard__filters { padding: 0 12px 8px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  .ahr-onboard__chip { flex: none; }
  .ahr-onboard__tasks { margin: 0 8px 8px; }
}
@container (max-width: 440px) {
  .ahr-onboard__node .ahr-onboard__dot { width: 26px; height: 26px; }
  .ahr-onboard__track::before, .ahr-onboard__track::after { top: 12px; }
  .ahr-onboard__node span { display: none; }
  .ahr-onboard__owner span { display: none; }
  .ahr-onboard__hero .ahr-onboard__ring { width: 46px; height: 46px; }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-onboard *, .ahr-onboard *::before, .ahr-onboard *::after { animation: none !important; transition-duration: .01s !important; }
  .ahr-onboard .ahr-onboard__progress { display: none; }
}

