// Onboarding journeys. Each hire has one plan (template tasks + their own additions); the hire list,
// journey rail, rings, filters and task list are all derived from it relative to today.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
root.addEventListener('submit', (e) => e.preventDefault());

const ICON = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  bell: '<path d="M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15z"/><path d="M10 20.5a2.2 2.2 0 0 0 4 0"/>',
  sent: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  back: '<path d="m15 18-6-6 6-6"/>',
  copy: '<rect x="8.5" y="8.5" width="11" height="11" rx="2"/><path d="M15.5 8.5V6A1.5 1.5 0 0 0 14 4.5H6A1.5 1.5 0 0 0 4.5 6v8A1.5 1.5 0 0 0 6 15.5h2.5"/>',
  flag: '<path d="M5 21V4"/><path d="M5 4h11l-2 4 2 4H5"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

const TODAY = '2026-10-02';
const dt = (s) => new Date(s + 'T12:00:00Z');
const iso = (d) => d.toISOString().slice(0, 10);
const addD = (s, n) => iso(new Date(dt(s).getTime() + n * 864e5));
const diff = (a, b) => Math.round((dt(a) - dt(b)) / 864e5);
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const fmt = (s, wd = true) => { const d = dt(s); return `${wd ? DOW[d.getUTCDay()] + ', ' : ''}${MON[d.getUTCMonth()]} ${d.getUTCDate()}`; };

const PHASES = [
  { k: 'pre', name: 'Pre-boarding', from: -14, to: -1 },
  { k: 'd1', name: 'Day 1', from: 0, to: 0 },
  { k: 'w1', name: 'Week 1', from: 1, to: 6 },
  { k: 'm1', name: 'Days 8–30', from: 7, to: 29 },
  { k: 'm2', name: 'Days 31–60', from: 30, to: 59 },
  { k: 'm3', name: 'Days 61–90', from: 60, to: 89 },
];
const OWN = {
  hr: { name: 'People Ops', c: 'oklch(0.76 0.1 355)' },
  it: { name: 'IT', c: 'oklch(0.76 0.09 240)' },
  mgr: { name: 'Manager', c: 'oklch(0.83 0.11 62)' },
  buddy: { name: 'Buddy', c: 'oklch(0.8 0.11 150)' },
  self: { name: 'New hire', c: 'oklch(0.86 0.08 100)' },
};
// id, title, owner, due (days from the start date; 0 is day 1)
const TPL = [
  ['t1', 'Send offer packet and policy handbook', 'hr', -14],
  ['t2', 'Order and ship the laptop', 'it', -10],
  ['t3', 'Assign an onboarding buddy', 'mgr', -7],
  ['t4', 'Create accounts: email, Teamline, EHR sandbox', 'it', -3],
  ['t5', 'Send the welcome email and day-1 agenda', 'mgr', -2],
  ['t6', 'Benefits enrolment walkthrough', 'hr', 0],
  ['t7', 'Security and HIPAA training', 'self', 0],
  ['t8', 'Team lunch', 'buddy', 0],
  ['t9', 'Set up a weekly 1:1', 'mgr', 0],
  ['t10', 'Complete I-9 verification', 'hr', 2],
  ['t11', 'Shadow three member-support sessions', 'buddy', 4],
  ['t12', 'Read the clinical escalation runbook', 'self', 4],
  ['t13', 'Agree 30-day goals', 'mgr', 13],
  ['t14', 'Ship a first solo task', 'self', 24],
  ['t15', '30-day check-in survey', 'hr', 29],
  ['t16', 'Present one process improvement', 'self', 54],
  ['t17', '60-day check-in', 'mgr', 59],
  ['t18', 'Onboarding feedback survey', 'hr', 87],
  ['t19', '90-day review and confirmation', 'mgr', 89],
];
const upto = (n, except = []) => TPL.slice(0, n).map((t) => t[0]).filter((id) => !except.includes(id));
const HIRES = [
  { id: 'ines', name: 'Inès Laurent', role: 'Clinical Operations Analyst', team: 'Clinical Ops', start: '2026-10-05', mgr: 'Dana Whitlock', buddy: 'Theo Grant', loc: 'Boston, MA', h: 25, done: ['t1', 't2'] },
  { id: 'kofi', name: 'Kofi Boateng', role: 'Senior Data Engineer', team: 'Data Platform', start: '2026-09-21', mgr: 'Sanjay Rao', buddy: 'Lea Moritz', loc: 'Remote · Toronto', h: 200, done: upto(12, ['t11']) },
  { id: 'mei', name: 'Mei-Ling Zhou', role: 'Nurse Practitioner, Telehealth', team: 'Care Delivery', start: '2026-08-31', mgr: 'Dr. Alana Brooks', buddy: 'Marcus Bell', loc: 'Remote · Portland', h: 330, done: upto(15, ['t14']) },
  { id: 'ruben', name: 'Ruben Castillo', role: 'Member Support Specialist', team: 'Member Support', start: '2026-10-19', mgr: 'Gwen Ito', buddy: 'Sam Okoro', loc: 'Phoenix, AZ', h: 60, done: ['t1'] },
