/* Shift roster. Re-theme with --ahr-roster-bg, -ink, -accent and -bad; role hues are --ahr-roster-bake/-bar/-floor. */
.ahr-roster {
  --ahr-roster-bg: oklch(0.2 0.018 55);
  --ahr-roster-ink: oklch(0.94 0.02 80);
  --ahr-roster-accent: oklch(0.78 0.11 195);
  --ahr-roster-bad: oklch(0.7 0.17 28);
  --ahr-roster-bake: oklch(0.8 0.12 78);
  --ahr-roster-bar: oklch(0.75 0.09 250);
  --ahr-roster-floor: oklch(0.78 0.1 155);

  --ahr-roster-panel: color-mix(in oklch, var(--ahr-roster-ink) 4%, var(--ahr-roster-bg));
  --ahr-roster-raise: color-mix(in oklch, var(--ahr-roster-ink) 8%, var(--ahr-roster-bg));
  --ahr-roster-muted: color-mix(in oklch, var(--ahr-roster-ink) 62%, var(--ahr-roster-bg));
  --ahr-roster-faint: color-mix(in oklch, var(--ahr-roster-ink) 40%, var(--ahr-roster-bg));
  --ahr-roster-rule: color-mix(in oklch, var(--ahr-roster-ink) 8%, transparent);
