}
.ahr-roster__issuesbtn { display: none; }

/* ---------- day tabs (narrow only) ---------- */
.ahr-roster__days { grid-area: days; display: none; gap: 4px; padding: 8px 12px; overflow-x: auto; scrollbar-width: none; border-bottom: 1px solid var(--ahr-roster-rule);
