  & .ahr-roster__av { grid-row: span 2; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; font-size: 10.5px; font-weight: 700; color: oklch(0.9 0.05 var(--h)); background: oklch(0.34 0.05 var(--h)); }
  & b { font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ahr-roster__hrs { display: flex; align-items: center; gap: 6px; font-size: 10.5px; color: var(--ahr-roster-faint); font-variant-numeric: tabular-nums; }
  & .ahr-roster__hrs i { flex: 1; height: 4px; border-radius: 2px; background: var(--ahr-roster-rule2); overflow: hidden; }
  & .ahr-roster__hrs i::before { content: ""; display: block; height: 100%; width: min(100%, calc(var(--f) * 100%)); border-radius: inherit; background: var(--ahr-roster-accent); transition: width .5s var(--ahr-roster-ease); }
  &.is-over .ahr-roster__hrs { color: var(--ahr-roster-bad); }
  &.is-over .ahr-roster__hrs i::before { background: var(--ahr-roster-bad); }
  & .ahr-roster__roles { display: inline-flex; gap: 3px; }
  & .ahr-roster__roles i { width: 6px; height: 6px; border-radius: 2px; background: var(--c); }
}
.ahr-roster__who.is-open { & b { color: var(--ahr-roster-muted); } }
.ahr-roster__cell {
  display: flex; flex-direction: column; gap: 4px; padding: 5px; min-width: 0; transition: background-color .15s;
  &.is-off { background: repeating-linear-gradient(-45deg, var(--ahr-roster-rule) 0 1px, transparent 1px 7px); }
  &.is-off::before { content: "Unavailable"; font-size: 10px; color: var(--ahr-roster-faint); padding: 2px 3px; }
  &.is-off:has(.ahr-roster__shift)::before { content: none; }
  &.is-drop { background: color-mix(in oklch, var(--ahr-roster-accent) 14%, transparent); box-shadow: inset 0 0 0 1.5px var(--ahr-roster-accent); }
  &.is-dim { opacity: .35; }
  &.is-openrow { background: color-mix(in oklch, var(--ahr-roster-ink) 2.5%, transparent); }
}
.ahr-roster__shift {
  --c: var(--ahr-roster-floor);
  position: relative; display: grid; width: 100%; padding: 5px 7px 5px 9px; border-radius: 8px; text-align: left; touch-action: none; user-select: none;
  background: color-mix(in oklch, var(--c) 16%, var(--ahr-roster-bg)); box-shadow: inset 2.5px 0 0 var(--c);
  transition: box-shadow .2s, translate .2s var(--ahr-roster-ease), background-color .2s;
  & b { font-size: 11.5px; font-weight: 650; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; white-space: nowrap; }
  & small { font-size: 10.5px; color: color-mix(in oklch, var(--c) 70%, var(--ahr-roster-ink)); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:hover { translate: 0 -1px; background: color-mix(in oklch, var(--c) 24%, var(--ahr-roster-bg)); }
