.ahr-roster__ghost { position: absolute; z-index: 60; left: 0; top: 0; margin: 0; pointer-events: none; box-shadow: inset 2.5px 0 0 var(--c), 0 18px 32px -12px rgb(0 0 0 / .8) !important; transition: none; }
.ahr-roster__cost {
