  &.is-over b, &.is-over small { color: var(--ahr-roster-bad); }
  &.is-over i::before { background: var(--ahr-roster-bad); }
  &.is-label { left: 0; z-index: 3; color: var(--ahr-roster-muted); }
}

/* ---------- issues ---------- */
.ahr-roster__issues { grid-area: issues; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 14px 14px 18px; border-left: 1px solid var(--ahr-roster-rule); background: var(--ahr-roster-panel); display: grid; align-content: start; grid-auto-rows: max-content; gap: 10px; scrollbar-width: thin; scrollbar-color: var(--ahr-roster-rule2) transparent; }
.ahr-roster__sh { display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; color: var(--ahr-roster-faint);
  & span { margin-left: auto; letter-spacing: 0; text-transform: none; font-weight: 650; }
  & button { display: none; }
}
.ahr-roster__issue {
  display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 2px 9px; padding: 10px; border-radius: 11px; background: var(--ahr-roster-raise); box-shadow: inset 0 0 0 1px var(--ahr-roster-rule);
  animation: ahr-roster-in .4s var(--ahr-roster-ease) calc(var(--i) * 45ms) both;
  & > svg { grid-row: span 2; width: 18px; height: 18px; color: var(--ahr-roster-bad); margin-top: 1px; }
  & b { font-size: 12.5px; font-weight: 650; }
  & p { font-size: 11.5px; color: var(--ahr-roster-muted); text-wrap: pretty; }
  & div { grid-column: 2; display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }
  & div button { height: 26px; padding: 0 9px; border-radius: 7px; font-size: 11.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ahr-roster-rule2); }
