}
.ahr-roster__sum { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; border-radius: 11px; overflow: hidden; background: var(--ahr-roster-rule); box-shadow: 0 0 0 1px var(--ahr-roster-rule);
  & div { padding: 9px 10px; background: var(--ahr-roster-bg); }
  & span { display: block; font-size: 10.5px; color: var(--ahr-roster-faint); font-weight: 600; }
