  & header { display: flex; align-items: center; gap: 8px; padding: 6px 6px 8px; border-bottom: 1px solid var(--ahr-roster-rule); margin-bottom: 4px; }
  & header b { font-size: 12.5px; } & header small { display: block; font-size: 11px; color: var(--ahr-roster-muted); }
