  & ul button:is(:hover, :focus-visible) { background: var(--ahr-roster-hover); outline: none; }
  & ul button svg { width: 14px; height: 14px; }
  & ul button small { font-size: 11px; color: var(--ahr-roster-muted); text-align: right; white-space: nowrap; }
