  & footer { display: flex; gap: 6px; padding: 6px 4px 2px; border-top: 1px solid var(--ahr-roster-rule); margin-top: 4px; }
  & footer button { flex: 1; height: 28px; border-radius: 7px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ahr-roster-rule2); }
  & footer button:hover:not(:disabled) { background: var(--ahr-roster-hover); }
}
.ahr-roster__toast {
