@keyframes ahr-roster-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-roster-pop { 0% { scale: .9; } 60% { scale: 1.04; } 100% { scale: 1; } }
@keyframes ahr-roster-flash { 0%, 100% { box-shadow: inset 2.5px 0 0 var(--c), 0 0 0 0 transparent; } 25%, 70% { box-shadow: inset 2.5px 0 0 var(--c), 0 0 0 4px color-mix(in oklch, var(--ahr-roster-accent) 70%, transparent); } }
@keyframes ahr-roster-shake { 0%, 100% { translate: 0 0; } 25% { translate: -4px 0; } 75% { translate: 4px 0; } }

/* ---------- container: medium — issues become a drawer ---------- */
@container (max-width: 1060px) {
