  .ahr-roster[data-day="6"] [data-d]:not([data-d="6"]) { display: none; }
}
@container (max-width: 420px) {
  .ahr-roster__btn[data-act="autofill"] span { display: none; }
  .ahr-roster__who .ahr-roster__av { display: none; }
  .ahr-roster__who { grid-template-columns: minmax(0, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-roster *, .ahr-roster *::before, .ahr-roster *::after { animation: none !important; transition-duration: .01s !important; }
