/* ---------------- rule engine ---------------- */
function hoursOf(list) { const h = {}; STAFF.forEach((p) => { h[p.id] = 0; }); list.forEach((s) => { if (s.who) h[s.who] += dur(s); }); return h; }
// Would giving `shift` to `pid` break a rule? Checks training, availability, overlap, rest and hours.
function evalAssign(shift, pid, list = SH) {
  const p = P[pid], t = T[shift.t];
  if (!p.roles.includes(t.role)) return { ok: false, why: `Not trained on ${ROLE[t.role].name.toLowerCase()}` };
  if (p.off.includes(shift.day)) return { ok: false, why: `Unavailable ${DAYS[shift.day].d}` };
  const mine = list.filter((s) => s.who === pid && s.id !== shift.id);
  const a0 = shift.day * 24 + t.s, a1 = shift.day * 24 + t.e;
  for (const s of mine) {
    const b0 = s.day * 24 + T[s.t].s, b1 = s.day * 24 + T[s.t].e;
    if (a0 < b1 && b0 < a1) return { ok: false, why: `Overlaps ${T[s.t].name.toLowerCase()}` };
    const gap = a0 >= b1 ? a0 - b1 : b0 - a1;
    if (gap < MIN_REST) return { ok: false, why: `Only ${fmtH(gap)} h rest` };
  }
  const after = mine.reduce((n, s) => n + dur(s), 0) + dur(shift);
  if (after > p.max) return { ok: false, why: `${fmtH(after)} h > ${p.max} h`, after };
  return { ok: true, why: `${fmtH(after)} of ${p.max} h`, after };
}
function candidates(shift, list = SH) {
  return STAFF.filter((p) => p.id !== shift.who).map((p) => ({ p, r: evalAssign(shift, p.id, list) })).filter((c) => c.r.ok).sort((a, b) => a.r.after / a.p.max - b.r.after / b.p.max);
}
function analyze() {
  const out = [], bad = new Set(), hrs = hoursOf(SH);
  STAFF.forEach((p) => {
    const mine = SH.filter((s) => s.who === p.id).sort((a, b) => a.day * 24 + T[a.t].s - (b.day * 24 + T[b.t].s));
    mine.forEach((s) => {
      if (p.off.includes(s.day)) out.push({ kind: 'avail', title: `${first(p.id)} is unavailable ${DAYS[s.day].d}`, detail: `${T[s.t].name} ${hhmm(T[s.t].s)}–${hhmm(T[s.t].e)} · availability set in their profile`, shifts: [s.id], fix: s });
      if (!p.roles.includes(T[s.t].role)) out.push({ kind: 'train', title: `${first(p.id)} isn’t trained on ${ROLE[T[s.t].role].name.toLowerCase()}`, detail: `${DAYS[s.day].d} ${T[s.t].name} needs a ${ROLE[T[s.t].role].name.toLowerCase()}-trained person`, shifts: [s.id], fix: s });
    });
    for (let i = 1; i < mine.length; i++) {
      const a = mine[i - 1], b = mine[i];
      const aEnd = a.day * 24 + T[a.t].e, bStart = b.day * 24 + T[b.t].s;
      if (bStart < aEnd) out.push({ kind: 'double', title: `${first(p.id)} is double-booked ${DAYS[b.day].d}`, detail: `${T[a.t].name} and ${T[b.t].name} overlap`, shifts: [a.id, b.id], fix: b });
      else if (bStart - aEnd < MIN_REST) out.push({ kind: 'rest', title: `${first(p.id)} gets ${fmtH(bStart - aEnd)} h rest`, detail: `${DAYS[a.day].d} ${T[a.t].name.toLowerCase()} ends ${hhmm(T[a.t].e)}, ${DAYS[b.day].d} ${T[b.t].name.toLowerCase()} starts ${hhmm(T[b.t].s)} · minimum is ${MIN_REST} h`, shifts: [a.id, b.id], fix: b });
    }
    if (hrs[p.id] > p.max) {
      // suggest moving the shift whose reassignment is cleanest, latest in the week first
      let mv = null;
      for (const s of mine.slice().reverse()) { const c = candidates(s); if (c.length) { mv = s; break; } }
      out.push({ kind: p.max >= 40 ? 'ot' : 'contract', title: p.max >= 40 ? `${first(p.id)} is in overtime: ${fmtH(hrs[p.id])} h` : `${first(p.id)} is over contract: ${fmtH(hrs[p.id])} of ${p.max} h`, detail: p.max >= 40 ? `${fmtH(hrs[p.id] - 40)} h at 1.5× adds ${money((hrs[p.id] - 40) * p.rate * 0.5)} premium` : 'Part-time contract hours are capped', shifts: mine.map((s) => s.id), fix: mv, move: true });
    }
