  out.forEach((o) => { if (o.kind === 'ot' || o.kind === 'contract') return; o.shifts.forEach((id) => bad.add(id)); });
  out.forEach((o) => { if ((o.kind === 'ot' || o.kind === 'contract') && o.fix) bad.add(o.fix.id); });
  const open = SH.filter((s) => !s.who).sort((a, b) => a.day - b.day || T[a.t].s - T[b.t].s);
  return { issues: out, bad, open, hrs };
}
function cost(list = SH) {
  const day = DAYS.map(() => 0);
  list.forEach((s) => { if (s.who) day[s.day] += dur(s) * P[s.who].rate; });
  const hrs = hoursOf(list), ot = STAFF.reduce((n, p) => n + Math.max(0, hrs[p.id] - 40) * p.rate * 0.5, 0);
  return { day, ot, total: day.reduce((a, b) => a + b, 0) + ot };
}

