    h += DAYS.map((d, i) => `<div class="ahr-roster__cell${p.off.includes(i) ? ' is-off' : ''}" data-d="${i}" data-drop="${p.id}">${SH.filter((s) => s.day === i && s.who === p.id).sort((a, b) => T[a.t].s - T[b.t].s).map(chip).join('')}</div>`).join('');
  });
  h += `<div class="ahr-roster__cost is-label"><b>Labour</b><small>${money(c.total)} incl. ${money(c.ot)} OT</small></div>`;
  h += DAYS.map((d, i) => `<div class="ahr-roster__cost${c.day[i] > BUDGET[i] ? ' is-over' : ''}" data-d="${i}" title="${d.long}: ${money(c.day[i])} of a ${money(BUDGET[i])} budget"><b>${money(c.day[i])}</b><small>of ${money(BUDGET[i])}</small><i style="--f:${c.day[i] / BUDGET[i]}"></i></div>`).join('');
  grid.innerHTML = h;
  if (!RM.matches) $$('[data-shift]', grid).forEach((el) => {
    const b = before.get(el.dataset.shift); if (!b) return;
    const a = el.getBoundingClientRect(), dx = b.left - a.left, dy = b.top - a.top;
