css:
/* Engagement pulse heatmap. Re-theme with --ahr-pulse-paper, -ink, -pos, -neg (the diverging scale) and -mid. */
.ahr-pulse {
  --ahr-pulse-paper: oklch(0.985 0.004 95);
  --ahr-pulse-ink: oklch(0.22 0.02 250);
  --ahr-pulse-pos: oklch(0.52 0.11 178);
  --ahr-pulse-neg: oklch(0.6 0.16 34);
  --ahr-pulse-mid: oklch(0.965 0.01 95);

  --ahr-pulse-card: oklch(1 0 0);
  --ahr-pulse-muted: color-mix(in oklch, var(--ahr-pulse-ink) 60%, var(--ahr-pulse-paper));
  --ahr-pulse-faint: color-mix(in oklch, var(--ahr-pulse-ink) 38%, var(--ahr-pulse-paper));
  --ahr-pulse-rule: color-mix(in oklch, var(--ahr-pulse-ink) 9%, transparent);
  --ahr-pulse-rule2: color-mix(in oklch, var(--ahr-pulse-ink) 16%, transparent);
  --ahr-pulse-hover: color-mix(in oklch, var(--ahr-pulse-ink) 5%, transparent);
  --ahr-pulse-ease: cubic-bezier(.2, .8, .2, 1);
  --ahr-pulse-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--ahr-pulse-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--ahr-pulse-paper);
  color: var(--ahr-pulse-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--ahr-pulse-pos);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--ahr-pulse-rule2);
}
:where(.ahr-pulse) *, :where(.ahr-pulse) *::before, :where(.ahr-pulse) *::after { box-sizing: border-box; }
:where(.ahr-pulse) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.ahr-pulse) button:disabled { cursor: not-allowed; }
:where(.ahr-pulse) :is(p, h2, h3, ul, ol, figure, blockquote) { margin: 0; padding: 0; }
:where(.ahr-pulse) :is(ul, ol) { list-style: none; }
:where(.ahr-pulse) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.ahr-pulse) :focus-visible { outline: 2px solid var(--ahr-pulse-ink); outline-offset: 2px; }
:where(.ahr-pulse) kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--ahr-pulse-muted); background: var(--ahr-pulse-card); box-shadow: inset 0 0 0 1px var(--ahr-pulse-rule2), 0 1px 0 var(--ahr-pulse-rule2); }

.ahr-pulse__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "bar bar" "main detail";
  grid-template-columns: minmax(0, 1fr) clamp(280px, 28cqi, 330px);
  grid-template-rows: auto auto minmax(0, 1fr);
}

/* ---------- header ---------- */
.ahr-pulse__head { grid-area: head; display: flex; align-items: center; gap: 18px; padding: 16px 18px 12px; }
.ahr-pulse__title { display: flex; align-items: center; gap: 12px; min-width: 0; margin-right: auto;
  & h2 { font-size: clamp(16px, 1.7cqi, 19px); font-weight: 760; letter-spacing: -0.02em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--ahr-pulse-muted); }
}
.ahr-pulse__logo { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 11px; flex: none; color: var(--ahr-pulse-card); background: linear-gradient(135deg, var(--ahr-pulse-neg), color-mix(in oklch, var(--ahr-pulse-neg) 30%, var(--ahr-pulse-pos)) 50%, var(--ahr-pulse-pos)); & svg { stroke-width: 2.2; } }
.ahr-pulse__kpis { display: flex; gap: 2px; padding: 3px; border-radius: 13px; background: var(--ahr-pulse-card); box-shadow: 0 0 0 1px var(--ahr-pulse-rule); }
.ahr-pulse__kpi { display: grid; gap: 0; padding: 6px 14px; border-radius: 10px; min-width: 96px;
  & span { font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ahr-pulse-faint); white-space: nowrap; }
  & b { font-size: 19px; font-weight: 780; letter-spacing: -0.025em; font-variant-numeric: tabular-nums; }
  & small { font-size: 11px; color: var(--ahr-pulse-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & + .ahr-pulse__kpi { box-shadow: -1px 0 0 var(--ahr-pulse-rule); border-radius: 0; }
}
.ahr-pulse__up { color: var(--ahr-pulse-pos); } .ahr-pulse__down { color: var(--ahr-pulse-neg); }

/* ---------- bar ---------- */
.ahr-pulse__bar { grid-area: bar; display: flex; align-items: center; gap: 12px; padding: 0 18px 12px; }
.ahr-pulse__lens {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--ahr-pulse-hover);
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--ahr-pulse-muted); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--ahr-pulse-ink); }
  & button[aria-checked="true"] { color: var(--ahr-pulse-ink); background: var(--ahr-pulse-card); box-shadow: 0 1px 2px var(--ahr-pulse-rule2), 0 0 0 1px var(--ahr-pulse-rule); }
}
.ahr-pulse__switch {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 11px 0 8px; border-radius: 9px; font-size: 12px; font-weight: 600; color: var(--ahr-pulse-muted);
  & i { position: relative; width: 28px; height: 16px; border-radius: 8px; background: var(--ahr-pulse-rule2); transition: background-color .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--ahr-pulse-card); box-shadow: 0 1px 2px rgb(0 0 0 / .25); transition: translate .35s var(--ahr-pulse-spring); }
  &[aria-checked="true"] { color: var(--ahr-pulse-ink); }
  &[aria-checked="true"] i { background: var(--ahr-pulse-ink); }
  &[aria-checked="true"] i::after { translate: 12px 0; }
  &:hover { background: var(--ahr-pulse-hover); }
}
.ahr-pulse__legend { margin-left: auto; display: grid; grid-template-columns: auto 160px auto; align-items: center; gap: 8px; font-size: 11px; color: var(--ahr-pulse-muted); font-variant-numeric: tabular-nums;
  & i { height: 8px; border-radius: 4px; background: linear-gradient(90deg, var(--ahr-pulse-neg), var(--ahr-pulse-mid), var(--ahr-pulse-pos)); box-shadow: inset 0 0 0 1px var(--ahr-pulse-rule); }
  & em { grid-column: 1 / -1; font-style: normal; font-size: 10.5px; color: var(--ahr-pulse-faint); text-align: center; }
}

/* ---------- heatmap ---------- */
.ahr-pulse__main { grid-area: main; display: grid; grid-template-rows: minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.ahr-pulse__scroll { overflow: auto; overscroll-behavior: contain; padding: 0 18px 4px; scrollbar-width: thin; scrollbar-color: var(--ahr-pulse-rule2) transparent; }
.ahr-pulse__heat {
  display: grid; grid-template-columns: minmax(170px, 1.6fr) repeat(9, minmax(58px, 1fr)); gap: 3px;
  min-width: min-content;
}
.ahr-pulse__row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; gap: 3px; position: relative; }
.ahr-pulse__hrow { position: sticky; top: 0; z-index: 4; background: var(--ahr-pulse-paper); padding-bottom: 3px; }
.ahr-pulse__colh {
  display: grid; align-items: end; justify-items: center; min-height: 52px; padding: 4px 2px;
  & button { display: grid; justify-items: center; gap: 2px; width: 100%; padding: 4px 2px 5px; border-radius: 8px; font-size: 11px; font-weight: 650; line-height: 1.15; text-align: center; color: var(--ahr-pulse-muted); text-wrap: balance; }
  & button small { font-size: 9.5px; font-weight: 600; color: var(--ahr-pulse-faint); font-variant-numeric: tabular-nums; }
  & button:hover { color: var(--ahr-pulse-ink); background: var(--ahr-pulse-hover); }
  & button svg { width: 10px; height: 10px; stroke-width: 2.6; opacity: 0; transition: rotate .3s var(--ahr-pulse-spring), opacity .2s; }
  &[aria-sort] button { color: var(--ahr-pulse-ink); }
  &[aria-sort] button svg { opacity: 1; }
  &[aria-sort="ascending"] button svg { rotate: 180deg; }
  &:first-child { justify-items: start; }
  &:first-child button { justify-items: start; text-align: left; padding-left: 8px; }
}
.ahr-pulse__colh.is-hot button { color: var(--ahr-pulse-ink); background: var(--ahr-pulse-hover); }
.ahr-pulse__team {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 0 8px; padding: 6px 8px; border-radius: 9px; min-height: 42px;
  position: sticky; left: 0; z-index: 2; background: var(--ahr-pulse-paper);
  & b { font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-column: 1; font-size: 10.5px; color: var(--ahr-pulse-faint); font-variant-numeric: tabular-nums; }
  & em { grid-row: 1 / span 2; grid-column: 2; font-style: normal; font-size: 10px; font-weight: 700; color: var(--ahr-pulse-faint); font-variant-numeric: tabular-nums; }
  & i { grid-column: 1 / -1; height: 3px; margin-top: 3px; border-radius: 2px; background: var(--ahr-pulse-rule); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: calc(var(--rr) * 100%); background: var(--ahr-pulse-muted); }
}
.ahr-pulse__row.is-company .ahr-pulse__team b { font-weight: 780; }
.ahr-pulse__row.is-company { padding-bottom: 5px; margin-bottom: 3px; border-bottom: 1px dashed var(--ahr-pulse-rule2); }
.ahr-pulse__row.is-hot .ahr-pulse__team { box-shadow: inset 2px 0 0 var(--ahr-pulse-ink); }
.ahr-pulse__cell {
  --p: 0%; --n: 0%;
  position: relative; display: grid; place-items: center; width: 100%; min-height: 42px; border-radius: 8px;
  font-size: 13px; font-weight: 680; font-variant-numeric: tabular-nums; letter-spacing: -0.01em;
  background: color-mix(in oklch, var(--ahr-pulse-neg) var(--n), color-mix(in oklch, var(--ahr-pulse-pos) var(--p), var(--ahr-pulse-mid)));
  color: var(--ahr-pulse-ink);
  transition: background-color .45s var(--ahr-pulse-ease) calc(var(--c, 0) * 28ms), color .3s, box-shadow .2s, scale .25s var(--ahr-pulse-spring);
  &.is-dark { color: var(--ahr-pulse-card); }
  &:hover { scale: 1.06; z-index: 1; box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--ahr-pulse-ink) 50%, transparent); }
  &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--ahr-pulse-paper), 0 0 0 4px var(--ahr-pulse-ink); z-index: 2; }
  &:focus-visible { outline: 2px solid var(--ahr-pulse-ink); outline-offset: 2px; }
  &:disabled { background: repeating-linear-gradient(-45deg, var(--ahr-pulse-rule) 0 2px, transparent 2px 7px), var(--ahr-pulse-mid); color: var(--ahr-pulse-faint); font-size: 11px; font-weight: 600; scale: 1; box-shadow: none; }
  & sup { font-size: 9px; font-weight: 700; margin-left: 1px; opacity: .8; }
}
.ahr-pulse[data-bench="on"] .ahr-pulse__cell.is-below { box-shadow: inset 0 0 0 2px var(--ahr-pulse-ink); }
.ahr-pulse[data-bench="on"] .ahr-pulse__cell.is-below[aria-selected="true"] { box-shadow: inset 0 0 0 2px var(--ahr-pulse-ink), 0 0 0 2px var(--ahr-pulse-paper), 0 0 0 4px var(--ahr-pulse-ink); }
.ahr-pulse__eng .ahr-pulse__cell { border-radius: 8px 8px 8px 8px; font-weight: 800; }
.ahr-pulse__keys { display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 8px 18px 12px; font-size: 11px; color: var(--ahr-pulse-faint); & span { display: inline-flex; align-items: center; gap: 3px; } }
@supports (animation-timeline: view()) {
  .ahr-pulse__row:not(.ahr-pulse__hrow) { animation: ahr-pulse-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}

/* ---------- detail ---------- */
.ahr-pulse__detail { grid-area: detail; min-height: 0; overflow: auto; overscroll-behavior: contain; margin: 0 18px 16px 0; border-radius: 16px; background: var(--ahr-pulse-card); box-shadow: 0 0 0 1px var(--ahr-pulse-rule), 0 1px 3px var(--ahr-pulse-rule); scrollbar-width: thin; scrollbar-color: var(--ahr-pulse-rule2) transparent; }
.ahr-pulse__dv { display: grid; gap: 16px; padding: 16px; animation: ahr-pulse-in .4s var(--ahr-pulse-ease) both; }
.ahr-pulse__dhead {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px;
  & p { font-size: 11px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--ahr-pulse-faint); }
  & h3 { font-size: 16px; font-weight: 760; letter-spacing: -0.015em; text-wrap: balance; }
  & q { grid-column: 1 / -1; font-size: 12px; color: var(--ahr-pulse-muted); text-wrap: pretty; margin-top: 4px; }
  & > button { grid-row: 1 / span 2; grid-column: 2; display: none; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--ahr-pulse-muted); }
  & > button:hover { background: var(--ahr-pulse-hover); }
}
.ahr-pulse__big {
  display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px 10px;
  & b { font-size: 40px; font-weight: 800; letter-spacing: -0.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & b small { font-size: 18px; letter-spacing: 0; }
  & span { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; background: var(--ahr-pulse-hover); }
  & em { flex-basis: 100%; font-style: normal; font-size: 11.5px; color: var(--ahr-pulse-muted); }
}
.ahr-pulse__dist {
  display: grid; gap: 8px;
  & .ahr-pulse__stack { display: flex; height: 26px; border-radius: 7px; overflow: hidden; gap: 2px; }
  & .ahr-pulse__stack i { flex: var(--n) 0 0; display: grid; place-items: center; font-style: normal; font-size: 10.5px; font-weight: 700; color: var(--ahr-pulse-ink); background: var(--c); transform-origin: 0 50%; animation: ahr-pulse-grow .6s var(--ahr-pulse-ease) calc(var(--i) * 60ms) both; overflow: hidden; }
  & .ahr-pulse__stack i.is-dark { color: var(--ahr-pulse-card); }
  & ul { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; font-size: 10.5px; color: var(--ahr-pulse-muted); text-align: center; font-variant-numeric: tabular-nums; }
  & li b { display: block; font-size: 12px; color: var(--ahr-pulse-ink); }
}
.ahr-pulse__h { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ahr-pulse-faint); margin-bottom: 6px; display: flex; justify-content: space-between; & span { letter-spacing: 0; text-transform: none; font-weight: 600; } }
.ahr-pulse__trend {
  & svg { display: block; width: 100%; height: auto; overflow: visible; }
  & .is-team { fill: none; stroke: var(--ahr-pulse-ink); stroke-width: 2; stroke-dasharray: 400; stroke-dashoffset: 400; animation: ahr-pulse-draw 1s var(--ahr-pulse-ease) .1s forwards; }
  & .is-co { fill: none; stroke: var(--ahr-pulse-faint); stroke-width: 1.5; stroke-dasharray: 3 4; }
  & .is-bench { stroke: var(--ahr-pulse-pos); stroke-width: 1; stroke-dasharray: 1 3; opacity: .8; }
  & circle { fill: var(--ahr-pulse-card); stroke: var(--ahr-pulse-ink); stroke-width: 2; }
  & text { fill: var(--ahr-pulse-muted); stroke: none; font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums; }
  & text.is-v { fill: var(--ahr-pulse-ink); font-weight: 750; }
}
.ahr-pulse__drivers { display: grid; gap: 6px;
  & li { display: grid; grid-template-columns: 96px minmax(0, 1fr) 34px; align-items: center; gap: 8px; font-size: 11.5px; }
  & li i { height: 8px; border-radius: 4px; background: var(--ahr-pulse-mid); position: relative; overflow: hidden; }
  & li i::before { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--w); border-radius: inherit; background: var(--c); transform-origin: 0 50%; animation: ahr-pulse-grow .6s var(--ahr-pulse-ease) calc(var(--i) * 50ms) both; }
  & li i::after { content: ""; position: absolute; top: -2px; bottom: -2px; left: var(--b); width: 1.5px; background: var(--ahr-pulse-ink); opacity: .5; }
  & li b { text-align: right; font-variant-numeric: tabular-nums; }
}
.ahr-pulse__comments { display: grid; gap: 8px;
  & blockquote { position: relative; padding: 9px 11px 9px 13px; border-radius: 10px; font-size: 12.5px; text-wrap: pretty; background: var(--ahr-pulse-mid); }
  & blockquote::before { content: ""; position: absolute; left: 0; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c); }
  & cite { display: block; margin-top: 3px; font-size: 10.5px; font-style: normal; color: var(--ahr-pulse-faint); }
  & p { font-size: 12px; color: var(--ahr-pulse-muted); }
}
.ahr-pulse__actions { display: grid; gap: 8px;
  & .ahr-pulse__make { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; border-radius: 9px; font-size: 12.5px; font-weight: 700; color: var(--ahr-pulse-card); background: var(--ahr-pulse-ink); transition: translate .2s var(--ahr-pulse-ease), background-color .15s; }
  & .ahr-pulse__make:hover:not(:disabled) { translate: 0 -1px; background: color-mix(in oklch, var(--ahr-pulse-ink) 85%, var(--ahr-pulse-pos)); }
  & .ahr-pulse__make:disabled { color: var(--ahr-pulse-muted); background: var(--ahr-pulse-hover); }
  & .ahr-pulse__make svg { width: 15px; height: 15px; }
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; align-items: center; padding: 8px 6px 8px 10px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--ahr-pulse-rule); animation: ahr-pulse-in .4s var(--ahr-pulse-spring) both; }
  & li b { font-size: 12px; font-weight: 650; }
  & li small { font-size: 11px; color: var(--ahr-pulse-muted); }
  & li button { grid-row: 1 / span 2; grid-column: 2; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; color: var(--ahr-pulse-muted); }
  & li button:hover { background: var(--ahr-pulse-hover); color: var(--ahr-pulse-neg); }
  & li button svg { width: 15px; height: 15px; }
}
.ahr-pulse__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 10px; max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px; border-radius: 11px; font-size: 12.5px; font-weight: 550; color: var(--ahr-pulse-card); background: var(--ahr-pulse-ink); box-shadow: 0 16px 30px -14px color-mix(in oklch, var(--ahr-pulse-ink) 70%, transparent);
  transition: opacity .2s var(--ahr-pulse-ease), transform .35s var(--ahr-pulse-spring);
  @starting-style { opacity: 0; transform: translateY(10px); }
  &:empty { visibility: hidden; opacity: 0; transform: translateY(10px); }
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font-weight: 700; color: color-mix(in oklch, var(--ahr-pulse-pos) 40%, white); }
  & button:hover { background: color-mix(in oklch, var(--ahr-pulse-card) 12%, transparent); }
}

@keyframes ahr-pulse-in { from { opacity: 0; translate: 0 6px; } }
@keyframes ahr-pulse-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes ahr-pulse-grow { from { transform: scaleX(0); } }
@keyframes ahr-pulse-draw { to { stroke-dashoffset: 0; } }

/* ---------- container queries ---------- */
@container (max-width: 1100px) {
  .ahr-pulse__head { flex-wrap: wrap; gap: 10px; }
  .ahr-pulse__title { flex: 1 1 100%; }
  .ahr-pulse__kpis { flex: 1 1 100%; }
  .ahr-pulse__kpi { flex: 1; }
}
@container (max-width: 959px) {
  .ahr-pulse__app { grid-template-areas: "head" "bar" "main"; grid-template-columns: minmax(0, 1fr); }
  .ahr-pulse__detail {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 10px; width: min(360px, calc(100% - 20px)); margin: 0;
    box-shadow: 0 0 0 1px var(--ahr-pulse-rule2), 0 30px 60px -20px color-mix(in oklch, var(--ahr-pulse-ink) 45%, transparent);
    transform: translateX(calc(100% + 20px)); visibility: hidden; transition: transform .45s var(--ahr-pulse-spring), visibility 0s .45s;
  }
  .ahr-pulse[data-sheet="open"] .ahr-pulse__detail { transform: none; visibility: visible; transition: transform .45s var(--ahr-pulse-spring), visibility 0s; }
  .ahr-pulse__dhead > button { display: grid; }
}
@container (max-width: 759px) {
  .ahr-pulse__head, .ahr-pulse__bar { padding-left: 12px; padding-right: 12px; }
  .ahr-pulse__kpis { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
  .ahr-pulse__kpi { min-width: 0; padding: 6px 10px; & + .ahr-pulse__kpi { box-shadow: none; } & small { white-space: normal; } }
  .ahr-pulse__colh button { font-size: 10px; & small { display: none; } }
  .ahr-pulse__bar { flex-wrap: wrap; }
  .ahr-pulse__legend { margin-left: 0; flex: 1 1 100%; grid-template-columns: auto minmax(0, 1fr) auto; }
  .ahr-pulse__scroll { padding: 0 12px 4px; }
  .ahr-pulse__heat { grid-template-columns: 128px repeat(9, 54px); }
  .ahr-pulse__detail { inset: 0; width: auto; border-radius: 0; }
  .ahr-pulse__keys { display: none; }
}
@container (max-width: 420px) {
  .ahr-pulse__title p { display: none; }
  .ahr-pulse__switch { font-size: 11.5px; }
  .ahr-pulse__heat { grid-template-columns: 108px repeat(9, 50px); }
}

@media (prefers-reduced-motion: reduce) {
  .ahr-pulse *, .ahr-pulse *::before, .ahr-pulse *::after { animation: none !important; transition-duration: .01s !important; transition-delay: 0s !important; }
  .ahr-pulse .ahr-pulse__trend .is-team { stroke-dashoffset: 0; }
}

