// Engagement pulse. Every cell is built from a five-point response distribution, so the
// favourability %, the drill-down bars, the company row and the KPIs all agree.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1)';

const ICON = {
  sort: '<path d="m6 9 6 6 6-6"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  x: '<path d="M7 7l10 10M17 7 7 17"/>',
  close: '<path d="M6 6l12 12M18 6 6 18"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

const DRIVERS = [
  { k: 'recog', name: 'Recognition', bench: 60, q: 'I receive appropriate recognition when I do good work.' },
  { k: 'growth', name: 'Growth', bench: 57, q: 'I can see a path to grow my career at Aldergrove.' },
  { k: 'mgr', name: 'Manager', bench: 70, q: 'My manager genuinely cares about my wellbeing.' },
  { k: 'load', name: 'Workload', bench: 55, q: 'I can get my work done in a normal working week.' },
  { k: 'belong', name: 'Belonging', bench: 68, q: 'I feel like I belong on my team.' },
  { k: 'tools', name: 'Tools', bench: 62, q: 'I have the tools and equipment to do my job well.' },
  { k: 'strat', name: 'Strategy', bench: 60, q: 'I understand where Aldergrove is heading this year.' },
  { k: 'well', name: 'Wellbeing', bench: 62, q: 'The pace of work here is sustainable for me.' },
];
// favourable % this pulse and change since Q2, per driver in the order above
const TEAMS = [
  { k: 'pnw', name: 'Retail · Pacific NW', n: 88, hc: 104, lead: 'Corinne Haslam', fav: [66, 58, 78, 52, 74, 61, 59, 63], d: [5, 1, -2, -8, 2, -1, 3, -4] },
  { k: 'mtn', name: 'Retail · Mountain', n: 61, hc: 79, lead: 'Ezekiel Brandt', fav: [54, 49, 63, 41, 66, 55, 52, 50], d: [7, -3, -1, -11, 0, 2, -4, -6] },
  { k: 'dc', name: 'Distribution Center', n: 104, hc: 131, lead: 'Ramon Ibarra', fav: [48, 44, 60, 36, 58, 47, 45, 42], d: [9, 0, 2, -13, -2, -5, 1, -7] },
  { k: 'cc', name: 'Customer Care', n: 52, hc: 58, lead: 'Nadia Petrosyan', fav: [62, 55, 81, 47, 77, 52, 64, 58], d: [4, -2, 3, -6, 1, 0, 2, -3] },
  { k: 'ecom', name: 'E-commerce', n: 34, hc: 37, lead: 'Jasper Okoye', fav: [73, 70, 84, 61, 80, 79, 72, 71], d: [2, 3, 1, -2, 0, 6, 1, 0] },
  { k: 'merch', name: 'Merchandising', n: 22, hc: 26, lead: 'Ingrid Falk', fav: [68, 64, 76, 57, 73, 70, 66, 64], d: [3, -1, 2, -4, 1, 1, -2, -1] },
  { k: 'mkt', name: 'Marketing', n: 19, hc: 21, lead: 'Teo Marchetti', fav: [77, 68, 86, 54, 82, 75, 71, 66], d: [1, 2, 0, -3, 2, -1, 4, -2] },
  { k: 'fin', name: 'Finance', n: 13, hc: 15, lead: 'Oluwaseun Adeyemi', fav: [69, 62, 79, 64, 71, 73, 75, 70], d: [6, 0, -5, 7, 0, 3, 8, 0] },
  { k: 'pc', name: 'People & Culture', n: 6, hc: 7, lead: 'Maeve Duggan', fav: [83, 75, 88, 60, 89, 77, 81, 74], d: [0, 2, 1, -2, 0, 1, 3, 0] },
  { k: 'lead', name: 'Leadership', n: 4, hc: 5, lead: 'Ana Szabo', fav: [80, 70, 85, 50, 85, 75, 90, 62], d: [1, 0, 0, -1, 0, 2, 1, -2] },
];
const MIN_N = 5;
const SCALE = ['Strongly disagree', 'Disagree', 'Neutral', 'Agree', 'Strongly agree'];
const SCOLOR = ['var(--ahr-pulse-neg)', 'color-mix(in oklch, var(--ahr-pulse-neg) 45%, var(--ahr-pulse-mid))', 'color-mix(in oklch, var(--ahr-pulse-ink) 10%, var(--ahr-pulse-mid))', 'color-mix(in oklch, var(--ahr-pulse-pos) 50%, var(--ahr-pulse-mid))', 'var(--ahr-pulse-pos)'];
const COMMENTS = [
  ['dc', 'load', -1, 'Pick targets went up 12% in August but staffing didn’t.'],
  ['dc', 'load', -1, 'Peak prep started in September this year — we were not told why.'],
  ['dc', 'tools', -1, 'Scanners drop connection in aisles 30–42 every single shift.'],
  ['dc', 'recog', 1, 'The shout-out board in the break room actually feels genuine now.'],
  ['mtn', 'load', -1, 'Weekend coverage keeps landing on the same four people.'],
  ['mtn', 'strat', -1, 'I heard about the store remodel from a customer first.'],
  ['mtn', 'growth', -1, 'Assistant manager roles get filled from outside every time.'],
  ['mtn', 'recog', 1, 'Corinne’s team visit and the thank-you notes meant a lot.'],
  ['pnw', 'belong', 1, 'New-hire buddies made my first month so much easier.'],
  ['pnw', 'load', -1, 'Truck days and inventory counts in the same week is too much.'],
  ['cc', 'growth', -1, 'I’d love a path from tier 1 to tier 2 that isn’t just tenure.'],
  ['cc', 'well', -1, 'Back-to-back escalations with no buffer is exhausting.'],
  ['cc', 'mgr', 1, 'Nadia blocks our calendars for real breaks — it shows.'],
  ['ecom', 'tools', 1, 'The new CMS cut our publish time in half.'],
  ['ecom', 'mgr', 1, 'My lead protects focus time and pushes back on random asks.'],
  ['mkt', 'recog', 0, 'Campaign wins get celebrated; the boring fixes don’t.'],
  ['fin', 'strat', 1, 'The quarterly all-hands numbers finally make sense to me.'],
  ['merch', 'load', -1, 'Line reviews and vendor visits stacked into the same fortnight.'],
];

/* ---------------- build distributions ---------------- */
function dist(n, f) {
  const F = Math.round((f / 100) * n);
  const u = Math.min(0.75, Math.max(0.3, 0.45 + (60 - f) / 100));
  const U = Math.round((n - F) * u), N = n - F - U;
  const SA = Math.round(F * 0.4), SD = Math.round(U * 0.35);
  return [SD, U - SD, N, F - SA, SA];
}
TEAMS.forEach((t) => {
  t.cells = DRIVERS.map((d, i) => {
    const cur = dist(t.n, t.fav[i]), prev = dist(t.n, t.fav[i] - t.d[i]);
    const h = (t.k.charCodeAt(0) * 7 + i * 13) % 7 - 3;
    return { cur, prev, q1: t.fav[i] - t.d[i] - h, q4: t.fav[i] - t.d[i] - h - (((i * 5 + t.n) % 5) - 2) };
  });
});
const favOf = (dd) => (dd[3] + dd[4]) / dd.reduce((a, b) => a + b, 0);
const pctOf = (v) => Math.round(v * 100);
function company(i) {
  const cur = [0, 0, 0, 0, 0], prev = [0, 0, 0, 0, 0];
  TEAMS.forEach((t) => { t.cells[i].cur.forEach((v, j) => { cur[j] += v; }); t.cells[i].prev.forEach((v, j) => { prev[j] += v; }); });
  const n = TEAMS.reduce((a, t) => a + t.n, 0);
  const q1 = TEAMS.reduce((a, t) => a + t.cells[i].q1 * t.n, 0) / n, q4 = TEAMS.reduce((a, t) => a + t.cells[i].q4 * t.n, 0) / n;
  return { cur, prev, q1, q4 };
}
const CO = { k: 'all', name: 'All teams', n: TEAMS.reduce((a, t) => a + t.n, 0), hc: TEAMS.reduce((a, t) => a + t.hc, 0), lead: 'Executive team', cells: DRIVERS.map((d, i) => company(i)) };
const ROWS = [CO].concat(TEAMS);
const byKey = Object.fromEntries(ROWS.map((r) => [r.k, r]));
const hidden = (r) => r.k !== 'all' && r.n < MIN_N;
// Values per lens. Column 8 is the engagement index: the mean of the eight drivers.
function val(r, ci, lens) {
  if (ci === 8) { const v = DRIVERS.map((d, i) => val(r, i, lens)); return v.reduce((a, b) => a + b, 0) / v.length; }
  const c = r.cells[ci], now = favOf(c.cur) * 100;
  if (lens === 'delta') return now - favOf(c.prev) * 100;
  if (lens === 'gap') return now - DRIVERS[ci].bench;
  return now;
}
const ENG_CO = val(CO, 8, 'score');
function enps(r) {
  const e = val(r, 8, 'score');
  const pro = Math.max(5, Math.min(70, Math.round((e - 40) * 0.95))), det = Math.max(4, Math.min(60, Math.round((80 - e) * 0.75)));
  return { pro, det, score: pro - det };
}
function enpsCo() {
  let p = 0, d = 0; TEAMS.forEach((t) => { const x = enps(t); p += (x.pro / 100) * t.n; d += (x.det / 100) * t.n; });
  return Math.round(((p - d) / CO.n) * 100);
}

const S = { lens: 'score', sort: null, dir: -1, sel: { r: 'dc', c: 3 }, focus: { r: 'dc', c: 3 }, bench: false, sheet: false, actions: [{ id: 'a0', r: 'dc', c: 3, text: 'Staff a floater pool for peak weeks', owner: 'Ramon Ibarra', due: 'Oct 30' }] };
let aseq = 1;

/* ---------------- header ---------------- */
function renderKpis() {
  const rate = CO.n / CO.hc, e = ENG_CO, ePrev = DRIVERS.reduce((a, d, i) => a + favOf(CO.cells[i].prev) * 100, 0) / DRIVERS.length;
  const moves = DRIVERS.map((d, i) => ({ d, v: val(CO, i, 'delta') })).sort((a, b) => a.v - b.v);
  const worst = moves[0], best = moves[moves.length - 1];
  $('.ahr-pulse__kpis').innerHTML = `
    <div class="ahr-pulse__kpi"><span>Responses</span><b>${pctOf(rate)}%</b><small>${CO.n} of ${CO.hc} people</small></div>
    <div class="ahr-pulse__kpi"><span>Engagement</span><b>${Math.round(e)}</b><small class="${e - ePrev >= 0 ? 'ahr-pulse__up' : 'ahr-pulse__down'}">${e - ePrev >= 0 ? '+' : '−'}${Math.abs(e - ePrev).toFixed(1)} since Q2</small></div>
    <div class="ahr-pulse__kpi"><span>eNPS</span><b>${enpsCo() > 0 ? '+' : ''}${enpsCo()}</b><small>promoters − detractors</small></div>
    <div class="ahr-pulse__kpi"><span>Biggest moves</span><b class="ahr-pulse__down">${esc(worst.d.name)} ${fmtV(worst.v, 'delta')}</b><small class="ahr-pulse__up">${esc(best.d.name)} ${fmtV(best.v, 'delta')}</small></div>`;
}
const LENSES = { score: ['Score', 'favourable %'], delta: ['Change', 'points since the Q2 pulse'], gap: ['vs benchmark', 'points against the retail benchmark'] };
function renderBar() {
  $('.ahr-pulse__lens').innerHTML = Object.entries(LENSES).map(([k, [l]]) => `<button type="button" role="radio" data-lens="${k}" aria-checked="${S.lens === k}">${l}</button>`).join('');
  const sw = $('[data-act="bench"]'); sw.setAttribute('aria-checked', String(S.bench));
  const lg = S.lens === 'score' ? [`${Math.round(ENG_CO - 25)}%`, `${Math.round(ENG_CO + 25)}%`] : S.lens === 'delta' ? ['−12', '+12'] : ['−20', '+20'];
  $('.ahr-pulse__legend').innerHTML = `<span>${lg[0]}</span><i></i><span>${lg[1]}</span><em>${S.lens === 'score' ? `centred on the company engagement of ${Math.round(ENG_CO)}` : esc(LENSES[S.lens][1])}</em>`;
  root.dataset.lens = S.lens; root.dataset.bench = S.bench ? 'on' : 'off';
}

/* ---------------- heatmap (persistent cells, re-coloured in place) ---------------- */
const heat = $('.ahr-pulse__heat');
const COLS = DRIVERS.map((d) => d.name).concat(['Engagement']);
function buildHeat() {
  let h = `<div class="ahr-pulse__row ahr-pulse__hrow" role="row"><div class="ahr-pulse__colh" role="columnheader" data-col="team"><button type="button" data-sort="team">Team<small>responses</small>${ic('sort')}</button></div>${COLS.map((name, ci) => `<div class="ahr-pulse__colh" role="columnheader" data-col="${ci}"><button type="button" data-sort="${ci}">${esc(name)}<small>${ci < 8 ? 'bench ' + DRIVERS[ci].bench : 'index'}</small>${ic('sort')}</button></div>`).join('')}</div>`;
  ROWS.forEach((r) => {
    const hid = hidden(r);
    h += `<div class="ahr-pulse__row${r.k === 'all' ? ' is-company' : ''}" role="row" data-row="${r.k}"><div class="ahr-pulse__team" role="rowheader" style="--rr:${r.n / r.hc}"><b>${esc(r.name)}</b><small>${r.n} of ${r.hc} · ${pctOf(r.n / r.hc)}%</small><i></i></div>${COLS.map((c, ci) => `<div role="gridcell" class="${ci === 8 ? 'ahr-pulse__eng' : ''}"><button type="button" class="ahr-pulse__cell" data-r="${r.k}" data-c="${ci}" style="--c:${ci}" tabindex="-1" ${hid ? `disabled title="Hidden: ${r.n} responses is under the anonymity minimum of ${MIN_N}"` : ''}></button></div>`).join('')}</div>`;
  });
  heat.innerHTML = h;
  heat.setAttribute('aria-rowcount', ROWS.length + 1);
  heat.setAttribute('aria-colcount', COLS.length + 1);
}
function tOf(v, lens) {
  if (lens === 'score') return Math.max(-1, Math.min(1, (v - ENG_CO) / 25));
  if (lens === 'delta') return Math.max(-1, Math.min(1, v / 12));
  return Math.max(-1, Math.min(1, v / 20));
}
function fmtV(v, lens) { const r = Math.round(v); return lens === 'score' ? String(r) : (r > 0 ? '+' : r < 0 ? '−' : '±') + Math.abs(r); }
function paintHeat() {
  $$('.ahr-pulse__cell', heat).forEach((b) => {
    const r = byKey[b.dataset.r], ci = +b.dataset.c;
    if (hidden(r)) { b.textContent = `n<${MIN_N}`; return; }
    const v = val(r, ci, S.lens), t = tOf(v, S.lens), score = val(r, ci, 'score');
    b.style.setProperty('--p', t > 0 ? (t * 100).toFixed(0) + '%' : '0%');
    b.style.setProperty('--n', t < 0 ? (-t * 100).toFixed(0) + '%' : '0%');
    b.classList.toggle('is-dark', Math.abs(t) > 0.58);
    b.classList.toggle('is-below', ci < 8 && score < DRIVERS[ci].bench);
    b.innerHTML = `<span>${fmtV(v, S.lens)}${S.lens === 'score' ? '<sup>%</sup>' : ''}</span>`;
    const sel = S.sel && S.sel.r === r.k && S.sel.c === ci;
    b.setAttribute('aria-selected', String(!!sel));
    b.tabIndex = S.focus.r === r.k && S.focus.c === ci ? 0 : -1;
    b.setAttribute('aria-label', `${r.name}, ${COLS[ci]}: ${Math.round(score)}% favourable, ${fmtV(val(r, ci, 'delta'), 'delta')} since Q2${ci < 8 ? `, benchmark ${DRIVERS[ci].bench}` : ''}`);
  });
  $$('.ahr-pulse__colh', heat).forEach((h) => {
    const k = h.dataset.col, on = S.sort !== null && String(S.sort) === k;
    if (on) h.setAttribute('aria-sort', S.dir > 0 ? 'ascending' : 'descending'); else h.removeAttribute('aria-sort');
    h.classList.toggle('is-hot', S.sel && String(S.sel.c) === k);
  });
  $$('.ahr-pulse__row[data-row]', heat).forEach((row) => row.classList.toggle('is-hot', S.sel && S.sel.r === row.dataset.row));
}
function sortRows() {
  const rows = $$('.ahr-pulse__row[data-row]:not(.is-company)', heat);
  const before = new Map(rows.map((el) => [el.dataset.row, el.getBoundingClientRect().top]));
  const key = (k) => { const r = byKey[k]; if (S.sort === null) return -TEAMS.indexOf(r); if (hidden(r)) return S.dir < 0 ? -1e9 : 1e9; if (S.sort === 'team') return r.n; return val(r, +S.sort, S.lens); };
  rows.sort((a, b) => (key(a.dataset.row) - key(b.dataset.row)) * (S.sort === null ? -1 : S.dir));
  rows.forEach((el) => heat.appendChild(el));
  if (!RM.matches) rows.forEach((el, i) => {
    const dy = before.get(el.dataset.row) - el.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) el.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: SPRING, delay: i * 12 });
  });
}

/* ---------------- detail ---------------- */
function trendSVG(r, ci) {
  const pts = ci === 8
    ? ['q4', 'q1', 'prev', 'cur'].map((q) => DRIVERS.reduce((a, d, i) => a + (q === 'cur' ? favOf(r.cells[i].cur) * 100 : q === 'prev' ? favOf(r.cells[i].prev) * 100 : r.cells[i][q]), 0) / 8)
    : [r.cells[ci].q4, r.cells[ci].q1, favOf(r.cells[ci].prev) * 100, favOf(r.cells[ci].cur) * 100];
  const co = ci === 8 ? ['q4', 'q1', 'prev', 'cur'].map((q) => DRIVERS.reduce((a, d, i) => a + (q === 'cur' ? favOf(CO.cells[i].cur) * 100 : q === 'prev' ? favOf(CO.cells[i].prev) * 100 : CO.cells[i][q]), 0) / 8)
    : [CO.cells[ci].q4, CO.cells[ci].q1, favOf(CO.cells[ci].prev) * 100, favOf(CO.cells[ci].cur) * 100];
  const lab = ['Q4 ’25', 'Q1', 'Q2', 'Q3'];
  const all = pts.concat(co, ci < 8 ? [DRIVERS[ci].bench] : []);
  const lo = Math.floor(Math.min(...all) / 5) * 5 - 5, hi = Math.ceil(Math.max(...all) / 5) * 5 + 5;
  const W = 290, H = 110, x = (i) => 18 + (i * (W - 36)) / 3, y = (v) => 14 + ((hi - v) / (hi - lo)) * (H - 36);
  const line = (a) => a.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join('');
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Trend: ${pts.map((v, i) => lab[i] + ' ' + Math.round(v)).join(', ')}">
    ${ci < 8 ? `<line class="is-bench" x1="10" x2="${W - 10}" y1="${y(DRIVERS[ci].bench)}" y2="${y(DRIVERS[ci].bench)}"/>` : ''}
    ${r.k !== 'all' ? `<path class="is-co" d="${line(co)}"/>` : ''}<path class="is-team" d="${line(pts)}" pathLength="400"/>
    ${pts.map((v, i) => `<circle cx="${x(i)}" cy="${y(v)}" r="3.5"/><text class="is-v" x="${x(i)}" y="${y(v) - 8}" text-anchor="middle">${Math.round(v)}</text><text x="${x(i)}" y="${H - 4}" text-anchor="middle">${lab[i]}</text>`).join('')}
  </svg>`;
}
function renderDetail() {
  const el = $('.ahr-pulse__detail');
  const { r: rk, c: ci } = S.sel, r = byKey[rk];
  const score = val(r, ci, 'score'), delta = val(r, ci, 'delta');
  const name = COLS[ci];
  const has = S.actions.some((a) => a.r === rk && a.c === ci);
  let body = '';
  if (ci < 8) {
    const dd = r.cells[ci].cur, n = dd.reduce((a, b) => a + b, 0), gap = score - DRIVERS[ci].bench;
    body = `<div class="ahr-pulse__big"><b>${Math.round(score)}<small>%</small></b><span class="${delta >= 0 ? 'ahr-pulse__up' : 'ahr-pulse__down'}">${fmtV(delta, 'delta')} since Q2</span><span class="${gap >= 0 ? 'ahr-pulse__up' : 'ahr-pulse__down'}">${fmtV(gap, 'delta')} vs benchmark</span><em>${dd[3] + dd[4]} of ${n} answered agree or strongly agree</em></div>
      <div class="ahr-pulse__dist"><p class="ahr-pulse__h">Responses<span>${n} people</span></p><div class="ahr-pulse__stack" role="img" aria-label="${SCALE.map((s, i) => `${s}: ${dd[i]}`).join(', ')}">${dd.map((v, i) => `<i style="--n:${v};--c:${SCOLOR[i]};--i:${i}" class="${i === 0 || i === 4 ? 'is-dark' : ''}">${v / n >= 0.08 ? v : ''}</i>`).join('')}</div>
      <ul>${dd.map((v, i) => `<li><b>${pctOf(v / n)}%</b>${SCALE[i].replace('Strongly ', 'Str. ')}</li>`).join('')}</ul></div>`;
  } else {
    body = `<div class="ahr-pulse__big"><b>${Math.round(score)}</b><span class="${delta >= 0 ? 'ahr-pulse__up' : 'ahr-pulse__down'}">${fmtV(delta, 'delta')} since Q2</span><span>eNPS ${(() => { const v = rk === 'all' ? enpsCo() : enps(r).score; return (v > 0 ? '+' : '') + v; })()}</span><em>Mean favourability of the eight drivers</em></div>
      <div><p class="ahr-pulse__h">Drivers<span>tick = benchmark</span></p><ul class="ahr-pulse__drivers">${DRIVERS.map((d, i) => { const v = val(r, i, 'score'); return `<li style="--w:${v}%;--b:${d.bench}%;--c:${v >= d.bench ? 'var(--ahr-pulse-pos)' : 'var(--ahr-pulse-neg)'};--i:${i}"><span>${d.name}</span><i></i><b>${Math.round(v)}</b></li>`; }).join('')}</ul></div>`;
  }
  const cm = COMMENTS.filter((c) => (rk === 'all' || c[0] === rk) && (ci === 8 || c[1] === DRIVERS[ci].k)).slice(0, 4);
  const cmHTML = cm.length ? cm.map((c) => `<blockquote style="--c:${c[2] > 0 ? 'var(--ahr-pulse-pos)' : c[2] < 0 ? 'var(--ahr-pulse-neg)' : 'var(--ahr-pulse-faint)'}">“${esc(c[3])}”<cite>${esc(byKey[c[0]].name)}${ci === 8 ? ' · ' + esc(DRIVERS.find((d) => d.k === c[1]).name) : ''}</cite></blockquote>`).join('')
    : `<p>No comments about ${esc(name.toLowerCase())} from ${esc(r.name)} this pulse.</p>`;
  const acts = S.actions.map((a) => `<li data-aid="${a.id}"><b>${esc(a.text)}</b><small>${esc(byKey[a.r].name)} · ${esc(COLS[a.c])} · ${esc(a.owner)} · due ${esc(a.due)}</small><button type="button" data-remove="${a.id}" aria-label="Remove action: ${esc(a.text)}">${ic('x')}</button></li>`).join('');
  el.innerHTML = `<div class="ahr-pulse__dv">
    <header class="ahr-pulse__dhead"><p>${esc(r.name)}</p><h3>${esc(name)}</h3>${ci < 8 ? `<q>${esc(DRIVERS[ci].q)}</q>` : ''}<button type="button" data-act="close" aria-label="Close detail">${ic('close')}</button></header>
    ${body}
    <figure class="ahr-pulse__trend"><p class="ahr-pulse__h">Last four pulses<span>${r.k === 'all' ? 'company' : 'dashed: company'}</span></p>${trendSVG(r, ci)}</figure>
    <div class="ahr-pulse__comments"><p class="ahr-pulse__h">Comments<span>${cm.length} shown · anonymised</span></p>${cmHTML}</div>
    <div class="ahr-pulse__actions"><p class="ahr-pulse__h">Action plan<span>${S.actions.length} open</span></p>
      <button type="button" class="ahr-pulse__make" data-act="action" ${has ? 'disabled title="There is already an action for this team and driver"' : ''}>${ic(has ? 'check' : 'plus')}${has ? 'Action planned' : `Plan an action for ${esc(r.k === 'all' ? 'all teams' : r.name.split(' · ').pop())}`}</button>
      ${acts ? `<ul style="display:grid;gap:6px">${acts}</ul>` : ''}</div>
  </div>`;
}

/* ---------------- orchestration ---------------- */
function render() { renderKpis(); renderBar(); paintHeat(); renderDetail(); root.dataset.sheet = S.sheet ? 'open' : 'closed'; }
let toastT = 0;
function toast(msg, undo) {
  const t = $('.ahr-pulse__toast');
  t.innerHTML = `<span>${esc(msg)}</span>${undo ? `<button type="button" data-undo="${undo}">Undo</button>` : ''}`;
  clearTimeout(toastT); toastT = setTimeout(() => { t.innerHTML = ''; }, 4200);
}
function select(rk, ci, focus) {
  S.sel = { r: rk, c: ci }; S.focus = { r: rk, c: ci };
  if (root.clientWidth < 960) S.sheet = true;
  render();
  const d = $('.ahr-pulse__detail'); d.scrollTop = 0;
  if (focus) { const b = $(`.ahr-pulse__cell[data-r="${rk}"][data-c="${ci}"]`); if (b) b.focus({ preventScroll: false }); }
}
const IDEAS = { recog: 'Monthly peer-nominated shout-outs in huddles', growth: 'Publish the tier-to-tier promotion criteria', mgr: 'Fortnightly 1:1s for every direct report', load: 'Staff a floater pool for peak weeks', belong: 'Buddy for every new hire for 60 days', tools: 'Fix the aisle Wi-Fi dead zones', strat: 'Share the store roadmap before announcements', well: 'Protected 15-minute buffer between escalations' };
const DUE = ['Oct 30', 'Nov 6', 'Nov 13', 'Nov 20'];

root.addEventListener('click', (e) => {
  const t = e.target;
  const cell = t.closest('.ahr-pulse__cell');
  if (cell && !cell.disabled) { select(cell.dataset.r, +cell.dataset.c, false); return; }
  const so = t.closest('[data-sort]');
  if (so) {
    const k = so.dataset.sort === 'team' ? 'team' : +so.dataset.sort;
    if (S.sort === k) { if (S.dir === -1) S.dir = 1; else { S.sort = null; S.dir = -1; } } else { S.sort = k; S.dir = -1; }
    paintHeat(); sortRows();
    toast(S.sort === null ? 'Original team order' : `Sorted by ${k === 'team' ? 'responses' : COLS[k]} · ${S.dir < 0 ? 'high to low' : 'low to high'}`);
    return;
  }
  const ln = t.closest('[data-lens]');
  if (ln && ln.closest('.ahr-pulse__lens')) { S.lens = ln.dataset.lens; render(); if (S.sort !== null && S.sort !== 'team') sortRows(); return; }
  const rm = t.closest('[data-remove]');
  if (rm) { const i = S.actions.findIndex((a) => a.id === rm.dataset.remove); const [a] = S.actions.splice(i, 1); S.removed = { a, i }; renderDetail(); toast(`Removed “${a.text}”`, 'restore'); return; }
  const un = t.closest('[data-undo]');
  if (un) {
    if (un.dataset.undo === 'restore' && S.removed) { S.actions.splice(S.removed.i, 0, S.removed.a); S.removed = null; renderDetail(); toast('Action restored'); }
    else if (un.dataset.undo.startsWith('add:')) { S.actions = S.actions.filter((a) => a.id !== un.dataset.undo.slice(4)); renderDetail(); toast('Action removed'); }
    return;
  }
  const a = t.closest('[data-act]');
  if (!a) return;
  if (a.dataset.act === 'bench') { S.bench = !S.bench; render(); toast(S.bench ? `${$$('.ahr-pulse__cell.is-below').length} cells are below the retail benchmark` : 'Benchmark outlines off'); }
  else if (a.dataset.act === 'close') { S.sheet = false; render(); const b = $(`.ahr-pulse__cell[data-r="${S.sel.r}"][data-c="${S.sel.c}"]`); if (b) b.focus(); }
  else if (a.dataset.act === 'action') {
    const { r: rk, c: ci } = S.sel, r = byKey[rk];
    const id = 'a' + aseq++;
    S.actions.push({ id, r: rk, c: ci, text: ci < 8 ? IDEAS[DRIVERS[ci].k] : 'Run a driver deep-dive with the team', owner: r.lead, due: DUE[S.actions.length % DUE.length] });
    renderDetail();
    toast(`Action assigned to ${r.lead}`, 'add:' + id);
  }
});
root.addEventListener('keydown', (e) => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const cell = e.target.closest && e.target.closest('.ahr-pulse__cell');
  if (e.key === 'Escape' && S.sheet) { S.sheet = false; render(); return; }
  if (e.key.toLowerCase() === 'l') { e.preventDefault(); const ks = Object.keys(LENSES); S.lens = ks[(ks.indexOf(S.lens) + 1) % ks.length]; render(); if (S.sort !== null && S.sort !== 'team') sortRows(); toast(`Lens: ${LENSES[S.lens][0]}`); return; }
  if (!cell) return;
  const order = $$('.ahr-pulse__row[data-row]', heat).map((r) => r.dataset.row).filter((k) => !hidden(byKey[k]));
  let ri = order.indexOf(cell.dataset.r), ci = +cell.dataset.c;
  if (e.key === 's' || e.key === 'S') { e.preventDefault(); if (S.sort === ci) S.dir = -S.dir; else { S.sort = ci; S.dir = -1; } paintHeat(); sortRows(); cell.focus(); toast(`Sorted by ${COLS[ci]} · ${S.dir < 0 ? 'high to low' : 'low to high'}`); return; }
  const mv = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1], Home: [0, -99], End: [0, 99] }[e.key];
  if (mv) {
    e.preventDefault();
    ri = Math.max(0, Math.min(order.length - 1, ri + mv[0])); ci = Math.max(0, Math.min(8, ci + mv[1]));
    S.focus = { r: order[ri], c: ci };
    paintHeat();
    const b = $(`.ahr-pulse__cell[data-r="${order[ri]}"][data-c="${ci}"]`); if (b) { b.focus(); b.scrollIntoView({ block: 'nearest', inline: 'nearest' }); }
  }
});

buildHeat();
render();
